INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-physc-mech_q1', 'ap-topic-physc-mech', 1, false, 'B', 'Rotation', 'hard', 'Find the rotational kinetic energy of a solid cylinder of mass $M$ and radius $R$ rotating at angular speed $\omega$.', '["$\\frac{1}{2} M R^2 \\omega^2$","$\\frac{1}{4} M R^2 \\omega^2$","$M R^2 \\omega^2$","$\\frac{1}{3} M R^2 \\omega^2$"]'::jsonb, '$I = \frac{1}{2} M R^2 \implies K_{rot} = \frac{1}{2} I \omega^2 = \frac{1}{4} M R^2 \omega^2$.'),
  ('ap-topic-physc-mech_q2', 'ap-topic-physc-mech', 2, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A particle of mass $m = 2.0\text{ kg}$ moves along the $x$-axis subject to a net position-dependent force $F(x) = 6x^2 - 4x$ (in Newtons). If the particle starts from rest at $x = 0$, what is its speed when it reaches $x = 2.0\text{ m}$?', '["2.8 m/s","4.0 m/s","8.0 m/s","2.0 m/s"]'::jsonb, 'By the Work-Energy Theorem, $W_{\text{net}} = \Delta K = \frac{1}{2}m v_f^2 - 0$. Calculate work: $W = \int_0^2 (6x^2 - 4x)\,dx = \left[ 2x^3 - 2x^2 \right]_0^2 = 2(8) - 2(4) = 16 - 8 = 8.0\text{ J}$. Then $\frac{1}{2}(2.0) v_f^2 = 8.0 \implies v_f^2 = 8.0 \implies v_f = \sqrt{8} \approx 2.83\text{ m/s} \approx 2.8\text{ m/s}$.'),
  ('ap-topic-physc-mech_q3', 'ap-topic-physc-mech', 3, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A thin non-uniform rod of length $L$ and total mass $M$ has a linear mass density given by $\lambda(x) = cx$, where $x$ is measured from one end ($x = 0$). What is the distance from $x = 0$ to the rod''s center of mass $x_{\text{cm}}$?', '["$\\frac{2}{3}L$","$\\frac{1}{2}L$","$\\frac{3}{4}L$","$\\frac{1}{3}L$"]'::jsonb, 'Total mass $M = \int_0^L \lambda(x)\,dx = \int_0^L cx\,dx = \frac{1}{2}cL^2$. The first moment is $\int_0^L x \lambda(x)\,dx = \int_0^L c x^2\,dx = \frac{1}{3}cL^3$. Therefore $x_{\text{cm}} = \frac{\int x\,dm}{M} = \frac{\frac{1}{3}cL^3}{\frac{1}{2}cL^2} = \frac{2}{3}L$.'),
  ('ap-topic-physc-mech_q4', 'ap-topic-physc-mech', 4, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A uniform solid sphere (mass $M$, radius $R$, $I = \frac{2}{5}MR^2$) rolls without slipping down a ramp inclined at angle $\theta$ to the horizontal. What is the linear acceleration $a$ of its center of mass?', '["$\\frac{5}{7}g\\sin\\theta$","$\\frac{2}{7}g\\sin\\theta$","$\\frac{1}{2}g\\sin\\theta$","$\\frac{5}{9}g\\sin\\theta$"]'::jsonb, 'Forces along incline: $Mg\sin\theta - f_s = Ma$. Torque about center of mass: $\tau = f_s R = I\alpha = \left(\frac{2}{5}MR^2\right)\left(\frac{a}{R}\right) \implies f_s = \frac{2}{5}Ma$. Substituting into Newton''s 2nd Law: $Mg\sin\theta - \frac{2}{5}Ma = Ma \implies Mg\sin\theta = \frac{7}{5}Ma \implies a = \frac{5}{7}g\sin\theta$.'),
  ('ap-topic-physc-mech_q5', 'ap-topic-physc-mech', 5, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'An object of mass $m$ is dropped from rest in a medium where it experiences a linear drag force $F_d = -bv$. Which expression gives its velocity as a function of time $t$?', '["$v(t) = \\frac{mg}{b}\\left(1 - e^{-bt/m}\\right)$","$v(t) = \\frac{mg}{b} e^{-bt/m}$","$v(t) = gt - \\frac{b}{m}t^2$","$v(t) = \\frac{mg}{b}\\left(1 - e^{-gt/b}\\right)$"]'::jsonb, 'Equation of motion: $m\frac{dv}{dt} = mg - bv \implies \frac{dv}{g - (b/m)v} = dt$. Integrating from $v(0) = 0$ yields $-\frac{m}{b}\ln\left(1 - \frac{b}{mg}v\right) = t \implies 1 - \frac{bv}{mg} = e^{-bt/m} \implies v(t) = \frac{mg}{b}\left(1 - e^{-bt/m}\right)$.'),
  ('ap-topic-physc-mech_q6', 'ap-topic-physc-mech', 6, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A thin uniform rod of mass $M$ and length $L$ has moment of inertia $I_{\text{cm}} = \frac{1}{12}ML^2$. Using the parallel-axis theorem, what is its moment of inertia about an axis perpendicular to the rod passing through a point $\frac{L}{4}$ from one end?', '["$\\frac{7}{48}ML^2$","$\\frac{1}{16}ML^2$","$\\frac{1}{3}ML^2$","$\\frac{5}{24}ML^2$"]'::jsonb, 'The center of mass is at $\frac{L}{2}$ from the end. The distance from the center of mass to the pivot axis at $\frac{L}{4}$ is $d = \left|\frac{L}{2} - \frac{L}{4}\right| = \frac{L}{4}$. By the parallel-axis theorem: $I = I_{\text{cm}} + Md^2 = \frac{1}{12}ML^2 + M\left(\frac{L}{4}\right)^2 = \frac{1}{12}ML^2 + \frac{1}{16}ML^2 = \left(\frac{4}{48} + \frac{3}{48}\right)ML^2 = \frac{7}{48}ML^2$.'),
  ('ap-topic-physc-mech_q7', 'ap-topic-physc-mech', 7, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A uniform rod of length $L$ and mass $M$ pivots frictionlessly about a horizontal axis through its top end. What is the period of small-angle oscillations for this physical pendulum?', '["$T = 2\\pi \\sqrt{\\frac{2L}{3g}}$","$T = 2\\pi \\sqrt{\\frac{L}{g}}$","$T = 2\\pi \\sqrt{\\frac{L}{2g}}$","$T = 2\\pi \\sqrt{\\frac{3L}{2g}}$"]'::jsonb, 'For a physical pendulum, period is $T = 2\pi\sqrt{\frac{I}{mgd}}$, where $I = \frac{1}{3}ML^2$ about the end pivot and $d = \frac{L}{2}$ is the distance from the pivot to the center of mass. $T = 2\pi \sqrt{\frac{\frac{1}{3}ML^2}{Mg(L/2)}} = 2\pi \sqrt{\frac{2ML^2}{3MgL}} = 2\pi \sqrt{\frac{2L}{3g}}$.'),
  ('ap-topic-physc-mech_q8', 'ap-topic-physc-mech', 8, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A satellite of mass $m$ moves in a circular orbit of radius $r$ around a planet of mass $M$. What is the total mechanical energy $E$ of the satellite?', '["$E = -\\frac{GMm}{2r}$","$E = -\\frac{GMm}{r}$","$E = +\\frac{GMm}{2r}$","$E = 0$"]'::jsonb, 'Orbital velocity satisfies $\frac{mv^2}{r} = \frac{GMm}{r^2} \implies mv^2 = \frac{GMm}{r}$. Kinetic energy is $K = \frac{1}{2}mv^2 = \frac{GMm}{2r}$. Gravitational potential energy is $U = -\frac{GMm}{r}$. Total mechanical energy is $E = K + U = \frac{GMm}{2r} - \frac{GMm}{r} = -\frac{GMm}{2r}$.'),
  ('ap-topic-physc-mech_q9', 'ap-topic-physc-mech', 9, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A particle moves in a conservative force field where the potential energy function is $U(x) = 4x^3 - 9x^2 + 6x$. At which point is the particle in stable equilibrium?', '["$x = 1.0$","$x = 0.5$","$x = 0$","$x = 1.5$"]'::jsonb, 'Equilibrium occurs where force $F = -\frac{dU}{dx} = 0$. $\frac{dU}{dx} = 12x^2 - 18x + 6 = 6(2x^2 - 3x + 1) = 6(2x - 1)(x - 1) = 0 \implies x = 0.5$ or $x = 1.0$. Second derivative test for stability: $\frac{d^2U}{dx^2} = 24x - 18$. At $x = 0.5$, $\frac{d^2U}{dx^2} = 12 - 18 = -6 < 0$ (unstable). At $x = 1.0$, $\frac{d^2U}{dx^2} = 24(1) - 18 = +6 > 0$ (local minimum of $U$, stable equilibrium).'),
  ('ap-topic-physc-mech_q10', 'ap-topic-physc-mech', 10, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A uniform solid disk of mass $M$ and radius $R$ is rotating freely with angular velocity $\omega_0$ about a central frictionless axle. A small lump of clay of mass $m$ is dropped vertically onto the outer rim ($r = R$) and sticks. What is the final angular velocity $\omega_f$?', '["$\\frac{M}{M + 2m}\\omega_0$","$\\frac{M}{M + m}\\omega_0$","$\\frac{M + 2m}{M}\\omega_0$","$\\frac{2M}{2M + m}\\omega_0$"]'::jsonb, 'Angular momentum is conserved about the central axle ($L_i = L_f$). Initial: $L_i = I_{\text{disk}}\omega_0 = \left(\frac{1}{2}MR^2\right)\omega_0$. Final: $L_f = (I_{\text{disk}} + I_{\text{clay}})\omega_f = \left(\frac{1}{2}MR^2 + mR^2\right)\omega_f = R^2\left(\frac{1}{2}M + m\right)\omega_f$. Equating: $\frac{1}{2}MR^2\omega_0 = R^2\left(\frac{M + 2m}{2}\right)\omega_f \implies \omega_f = \frac{M}{M + 2m}\omega_0$.'),
  ('ap-topic-physc-mech_q11', 'ap-topic-physc-mech', 11, false, 'A', 'Newtonian Mechanics & Rotation', 'medium', 'An object of mass $m = 0.5\text{ kg}$ is attached to an ideal spring with spring constant $k = 50\text{ N/m}$ on a frictionless horizontal surface. If the object is displaced $0.10\text{ m}$ from equilibrium and released, what is its maximum acceleration?', '["10 m/s^2","5.0 m/s^2","1.0 m/s^2","20 m/s^2"]'::jsonb, 'Hooke''s Law gives maximum restoring force at maximum displacement $A$: $F_{\max} = kA = (50\text{ N/m})(0.10\text{ m}) = 5.0\text{ N}$. By Newton''s 2nd Law: $a_{\max} = \frac{F_{\max}}{m} = \frac{5.0\text{ N}}{0.5\text{ kg}} = 10\text{ m/s}^2$. Alternatively, $\omega = \sqrt{k/m} = \sqrt{100} = 10\text{ rad/s}$, and $a_{\max} = \omega^2 A = (100)(0.10) = 10\text{ m/s}^2$.'),
  ('ap-topic-physc-mech_q12', 'ap-topic-physc-mech', 12, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A rocket of initial mass $m_0$ burns fuel at a constant rate $R = -\frac{dm}{dt}$ with constant exhaust speed $u$ relative to the rocket in deep space. What is the rocket''s speed after its mass has decreased to $\frac{m_0}{e}$?', '["$u$","$2u$","$e \\cdot u$","$\\frac{u}{e}$"]'::jsonb, 'By Tsiolkovsky''s rocket equation: $\Delta v = u \ln\left(\frac{m_0}{m_f}\right)$. Given $m_f = \frac{m_0}{e}$, the mass ratio is $\frac{m_0}{m_0/e} = e$. Thus $\Delta v = u \ln(e) = u(1) = u$.'),
  ('ap-topic-physc-mech_q13', 'ap-topic-physc-mech', 13, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A force $\vec{F} = 4y\hat{i} + 3x\hat{j}$ (in Newtons) acts on a particle as it moves along a path from $(0, 0)$ to $(2, 2)$. Is this force conservative?', '["No, because $\\frac{\\partial F_y}{\\partial x} \\neq \\frac{\\partial F_x}{\\partial y}$","Yes, because the curl of the force is zero everywhere","Yes, because both components are linear functions of coordinates","No, because the work along any path is always zero"]'::jsonb, 'A 2D force is conservative if and only if $\frac{\partial F_y}{\partial x} = \frac{\partial F_x}{\partial y}$. Here $F_x = 4y \implies \frac{\partial F_x}{\partial y} = 4$, and $F_y = 3x \implies \frac{\partial F_y}{\partial x} = 3$. Since $3 \neq 4$, the curl $(\nabla \times \vec{F})_z = 3 - 4 = -1 \neq 0$, proving the force is non-conservative.'),
  ('ap-topic-physc-mech_q14', 'ap-topic-physc-mech', 14, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A particle of mass $m$ moves in the $xy$-plane with position vector $\vec{r}(t) = 3t^2\hat{i} + 2t^3\hat{j}$. What is the angular momentum $\vec{L}$ of the particle about the origin as a function of time?', '["$6mt^4\\hat{k}$","$-6mt^4\\hat{k}$","$12mt^4\\hat{k}$","$0$"]'::jsonb, 'Velocity $\vec{v}(t) = \frac{d\vec{r}}{dt} = 6t\hat{i} + 6t^2\hat{j}$. Momentum $\vec{p} = m\vec{v} = 6mt\hat{i} + 6mt^2\hat{j}$. Angular momentum is $\vec{L} = \vec{r} \times \vec{p} = (3t^2)(6mt^2)\hat{k} - (2t^3)(6mt)\hat{k} = 18mt^4\hat{k} - 12mt^4\hat{k} = 6mt^4\hat{k}$.'),
  ('ap-topic-physc-mech_q15', 'ap-topic-physc-mech', 15, false, 'A', 'Newtonian Mechanics & Rotation', 'medium', 'What is the escape speed from the surface of a spherical planet of mass $M$ and radius $R$?', '["$v_{\\text{esc}} = \\sqrt{\\frac{2GM}{R}}$","$v_{\\text{esc}} = \\sqrt{\\frac{GM}{R}}$","$v_{\\text{esc}} = \\frac{2GM}{R}$","$v_{\\text{esc}} = \\sqrt{\\frac{GM}{2R}}$"]'::jsonb, 'Conservation of mechanical energy from the surface to infinity ($E_f = 0$): $E_i = \frac{1}{2}m v_{\text{esc}}^2 - \frac{GMm}{R} = 0 \implies \frac{1}{2}v_{\text{esc}}^2 = \frac{GM}{R} \implies v_{\text{esc}} = \sqrt{\frac{2GM}{R}}$.'),
  ('ap-topic-physc-mech_q16', 'ap-topic-physc-mech', 16, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A mass $m$ undergoes damped harmonic motion described by $\frac{d^2x}{dt^2} + 2\beta\frac{dx}{dt} + \omega_0^2 x = 0$. What is the condition on $\beta$ and $\omega_0$ for critical damping?', '["$\\beta = \\omega_0$","$\\beta > \\omega_0$","$\\beta < \\omega_0$","$\\beta = 0$"]'::jsonb, 'The characteristic equation is $r^2 + 2\beta r + \omega_0^2 = 0$, with roots $r = -\beta \pm \sqrt{\beta^2 - \omega_0^2}$. Critical damping occurs when the discriminant vanishes, yielding repeated real roots without oscillation: $\beta^2 - \omega_0^2 = 0 \implies \beta = \omega_0$.'),
  ('ap-topic-physc-mech_q17', 'ap-topic-physc-mech', 17, false, 'A', 'Newtonian Mechanics & Rotation', 'medium', 'A constant torque of $20\text{ N}\cdot\text{m}$ is applied to a flywheel with rotational inertia $I = 4.0\text{ kg}\cdot\text{m}^2$ initially at rest. What is the flywheel''s rotational kinetic energy after $3.0\text{ seconds}$?', '["450 J","150 J","900 J","300 J"]'::jsonb, 'Angular acceleration $\alpha = \frac{\tau}{I} = \frac{20}{4.0} = 5.0\text{ rad/s}^2$. Angular speed after $3.0\text{ s}$: $\omega = \alpha t = (5.0)(3.0) = 15\text{ rad/s}$. Rotational kinetic energy $K_{\text{rot}} = \frac{1}{2}I\omega^2 = \frac{1}{2}(4.0)(15^2) = 2(225) = 450\text{ J}$.'),
  ('ap-topic-physc-mech_q18', 'ap-topic-physc-mech', 18, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A block of mass $m$ is pushed against a spring with constant $k$, compressing it by distance $x$. The block is released and slides up a frictionless incline of angle $\theta$. What maximum distance $d$ along the ramp does the block travel before coming to rest?', '["$d = \\frac{kx^2}{2mg\\sin\\theta}$","$d = \\frac{kx^2}{mg\\sin\\theta}$","$d = \\frac{kx^2}{2mg\\cos\\theta}$","$d = \\frac{kx}{mg\\sin\\theta}$"]'::jsonb, 'Conservation of mechanical energy: initial elastic potential energy converts to gravitational potential energy at height $h = d\sin\theta$: $\frac{1}{2}kx^2 = mgh = mg(d\sin\theta) \implies d = \frac{kx^2}{2mg\sin\theta}$.'),
  ('ap-topic-physc-mech_q19', 'ap-topic-physc-mech', 19, false, 'A', 'Newtonian Mechanics & Rotation', 'hard', 'A particle of mass $m$ moves in a circular path of radius $R$ with tangential speed increasing according to $v(t) = ct^2$. What is the magnitude of the net acceleration vector of the particle at time $t$?', '["$\\sqrt{(2ct)^2 + \\left(\\frac{c^2t^4}{R}\\right)^2}$","$\\frac{c^2t^4}{R}$","$2ct$","$2ct + \\frac{c^2t^4}{R}$"]'::jsonb, 'Tangential acceleration is $a_t = \frac{dv}{dt} = 2ct$. Centripetal (radial) acceleration is $a_c = \frac{v^2}{R} = \frac{(ct^2)^2}{R} = \frac{c^2t^4}{R}$. Because these components are mutually perpendicular, total acceleration magnitude is $a = \sqrt{a_t^2 + a_c^2} = \sqrt{(2ct)^2 + \left(\frac{c^2t^4}{R}\right)^2}$.'),
  ('ap-topic-physc-mech_q20', 'ap-topic-physc-mech', 20, false, 'A', 'Newtonian Mechanics & Rotation', 'medium', 'How is impulse related to momentum in calculus notation?', '["$\\vec{J} = \\int_{t_1}^{t_2} \\vec{F}\\,dt = \\Delta\\vec{p}$","$\\vec{J} = \\frac{d\\vec{F}}{dt} = \\vec{p}$","$\\vec{J} = \\int \\vec{p}\\,dt = \\vec{F}$","$\\vec{J} = \\vec{F} \\times \\vec{v} = \\Delta\\vec{p}$"]'::jsonb, 'By Newton''s 2nd Law in momentum form, $\vec{F} = \frac{d\vec{p}}{dt}$. Integrating with respect to time yields the Impulse-Momentum Theorem: $\vec{J} = \int_{t_1}^{t_2} \vec{F}\,dt = \Delta\vec{p}$.'),
  ('ap-diag-physc-mech_q1', 'ap-diag-physc-mech', 1, false, 'B', 'Diagnostic Test – Mechanics', 'medium', 'A block lies on an inclined plane with angle of elevation \theta, as shown in the figure. The inclined plane is frictionless, and the plane is accelerated to the left such that the block’s height remains constant. What is the net force on the block?', '["mg cot\\theta","mg tan\\theta","mg cos\\theta","mg sin\\theta","zero"]'::jsonb, '(B) Consider the figure. Because the block accelerates horizontally, we choose horizontal (x) and vertical (y) coordinates rather than the usual tilted coordinates of inclined plane problems. The y-component of the normal force must balance gravity for the block’s height to remain constant: Because the force in the y-direction is zero, the force in the x-direction is equal to the net force. Based on the diagram, this force is For more practice with this type of problem, see Chapter 3.'),
  ('ap-diag-physc-mech_q2', 'ap-diag-physc-mech', 2, false, 'E', 'Diagnostic Test – Mechanics', 'medium', 'Consider an Atwood machine consisting of two unequal masses m1 and m2 (with m1 > m2) connected by a light string that passes over a cylindrical pulley. If the pulley has non-negligible mass M and radius R (rotational inertia I = 1/2 M R^2), which of the following is true of the linear acceleration a of the masses compared to the acceleration a_0 when the pulley is ideal and massless?', '["a = g","a = a_0","a > a_0","a = (m1 + m2)g / (m1 - m2)","a < a_0 because rotational inertia of the pulley reduces linear acceleration"]'::jsonb, 'For a massless pulley, linear acceleration is a_0 = (m1 - m2)g / (m1 + m2). When the pulley has non-negligible mass M and rotational inertia I = 1/2 M R^2, torque equation tau = (T1 - T2)R = I alpha = I (a/R) requires different tensions on either side of the pulley. Summing Newton''s second law for the system yields (m1 - m2)g = (m1 + m2 + I/R^2)a = (m1 + m2 + 1/2 M)a, so a = (m1 - m2)g / (m1 + m2 + 1/2 M) < a_0. Thus, the acceleration is strictly less than in the massless pulley case.'),
  ('ap-diag-physc-mech_q3', 'ap-diag-physc-mech', 3, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'An object moves in the xy-plane with instantaneous velocity vector v directed along the positive x-axis. Five different constant acceleration vectors a are tested over a short time interval Delta t. In which case does the object experience the greatest increase in speed?', '["a is perpendicular to v (directed along the positive y-axis)","a is directed at an angle of 135 degrees relative to v","a is directed opposite to v (along the negative x-axis)","a is directed parallel to and in the same direction as v","a has zero magnitude"]'::jsonb, 'The rate of change of speed is given by d|v|/dt = a_parallel = a * cos(theta), the component of acceleration parallel to velocity. When acceleration is parallel and in the same direction as velocity (theta = 0 degrees), cos(0) = 1, giving the maximum possible rate of increase in speed. Perpendicular acceleration changes direction only, while antiparallel acceleration decreases speed.'),
  ('ap-diag-physc-mech_q4', 'ap-diag-physc-mech', 4, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'The moment of inertia (rotational inertia), \int r2 dm, is the rotational analog of', '["displacement","center of mass","velocity","mass","force"]'::jsonb, '(D) Mass is a measure of linear inertia. (For more information, see the definition of rotational inertia and the table comparing linear and angular quantities in Chapter 7.)'),
  ('ap-diag-physc-mech_q5', 'ap-diag-physc-mech', 5, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'A mass m connected to a spring with spring constant k oscillates at a frequency f. If the mass is increased by a factor of 4 and the spring constant is increased by a factor of 2, the new frequency will be', '["2f","8f","1","2","none of the above Questions 6–8 refer to the figure below, which shows two masses connected by a massless pulley. Assume the incline is frictionless."]'::jsonb, '(D) According to the equation , quadrupling the mass and doubling the spring constant causes the frequency to decrease by a factor of . For more information about oscillating spring systems, see Chapter 8.'),
  ('ap-diag-physc-mech_q6', 'ap-diag-physc-mech', 6, false, 'B', 'Diagnostic Test – Mechanics', 'medium', 'A mass m1 moves horizontally to the right with speed v along the positive x-axis, while a mass m2 moves vertically downward with speed v along the negative y-axis. What is the total momentum vector p_total of the two-mass system?', '["(m1 + m2)v i","m1 v i - m2 v j","m1 v i + m2 v j","(m1 - m2)v j","Zero"]'::jsonb, 'Linear momentum is a vector quantity given by p = m v. The momentum of mass m1 is p1 = m1 v i (directed to the right). The momentum of mass m2 is p2 = -m2 v j (directed downward). The total momentum of the system is the vector sum p_total = p1 + p2 = m1 v i - m2 v j.'),
  ('ap-diag-physc-mech_q7', 'ap-diag-physc-mech', 7, false, 'B', 'Diagnostic Test – Mechanics', 'medium', 'When m2 has fallen a distance d, what is the change in the total kinetic energy of the system?', '["g(m2d + m1d sin \\theta)","g(m2d − m1d sin \\theta)","g(m2d + m1d cos \\theta)","g(m2d − m1d cos \\theta)","Total kinetic energy is conserved."]'::jsonb, '(B) The change in the potential energy is Because of conservation of energy, the change in the kinetic energy must have the opposite sign of this change in the potential energy. More information about kinetic energy can be found in Chapter 4.'),
  ('ap-diag-physc-mech_q8', 'ap-diag-physc-mech', 8, false, 'C', 'Diagnostic Test – Mechanics', 'medium', 'Now consider that the inclined plane, which has mass M and rests on a frictionless surface, can move as well. When both small masses start from rest, which of the following quantities evaluated for the system of the three masses is conserved?', '["gravitational potential energy","kinetic energy","x-momentum","y-momentum","None of the above are conserved for this system."]'::jsonb, '(C) As shown in question 6, the potential and kinetic energy both change, so choices (A) and (B) are not correct. There are no external forces acting in the x-direction, so the momentum in this direction must be conserved. There are external forces acting in the y-direction (gravity and the normal force exerted on the incline by the horizontal surface), so y-momentum is not conserved. Conservation of momentum is discussed in Chapter 5.'),
  ('ap-diag-physc-mech_q9', 'ap-diag-physc-mech', 9, false, 'B', 'Diagnostic Test – Mechanics', 'medium', 'Two objects with equal masses and speeds as shown collide and stick together. What is the final speed of the combined mass?', '["v/2","v/","v","(E) 2v","Zero net field / magnitude"]'::jsonb, '(B) This is an inelastic collision in two dimensions such that momentum (but not energy) is conserved. Thus, in the horizontal (x) direction we have the equation mv + m(0) = (2m)v; similarly, in the vertical (y) direction we have m(0) + mv = (2m)v. Therefore, the final velocity has components in both directions that are equal to v/2, so that the final velocity has a magnitude of Collision problems are discussed in Chapter 5.'),
  ('ap-diag-physc-mech_q10', 'ap-diag-physc-mech', 10, false, 'C', 'Diagnostic Test – Mechanics', 'medium', 'An object moving with constant acceleration can have how many of the following path types? I. a linear path II. a circular path III. a parabolic path IV. an elliptical path V. a spiral path', '["none","one","two","three","four"]'::jsonb, '(C) An object with constant acceleration can have a linear path (e.g., a projectile thrown directly upward) or a parabolic path (e.g., a projectile launched at an angle). Moving in circular, elliptical, or spiral paths all require centripetal forces that change in direction. Motion in multiple dimensions with a constant acceleration is essentially identical to projectile motion, which is discussed in Chapter 2.'),
  ('ap-diag-physc-mech_q11', 'ap-diag-physc-mech', 11, false, 'E', 'Diagnostic Test – Mechanics', 'medium', 'A mass is pulled up a frictionless incline by a force applied parallel to the incline. The change in the object’s kinetic energy is equal to which of the following?', '["the negative of the change in potential energy","the work done by gravity","the work done by the applied force","the work done by the applied force minus the work done by gravity","the work done by the applied force plus the work done by gravity"]'::jsonb, '(E) The kinetic energy is not equal to the negative of the change in the potential energy due to the presence of the external force. (Imagine, for example, that the force F accelerates the mass as it moves up the incline; certainly energy is not being conserved in this situation.) The change in kinetic energy is equal to the net work done on the object, which in turn is equal to the sum of the work done by each of the forces, as stated in the work-energy theorem. (The normal force of the incline does zero work.) Choice (D) is incorrect because although gravity does do negative work, this negative sign is contained within the phrase “the work done by gravity.” The work-energy theorem is derived and discussed in Chapter 4.'),
  ('ap-diag-physc-mech_q12', 'ap-diag-physc-mech', 12, false, 'E', 'Diagnostic Test – Mechanics', 'medium', 'Which of the following changes does not affect the period of a horizontal mass-spring system undergoing simple harmonic motion?', '["doubling the mass","attaching an identical spring in parallel (as in the figure)","attaching an identical spring in series (as in the figure)","the presence of friction between the block and the horizontal surface","any manipulation of the masses and springs that does not affect the ratio of the maximum amplitude to the maximum velocity"]'::jsonb, '(E) The period is given by the equation . Therefore, doubling the mass, adding a spring in parallel (which doubles the effective spring constant), or adding a spring in series (which halves the effective spring constant) all affect the period. Adding friction complicates the motion such that it is no longer simple harmonic motion, and the period changes. Based on conservation of energy, , so that . Therefore, any change in the parameters of the system that does not affect the ratio A/vmax does not affect the ratio m/k and thus does not affect the period. For further information on mass-spring systems, see Chapter 8.'),
  ('ap-diag-physc-mech_q13', 'ap-diag-physc-mech', 13, false, 'E', 'Diagnostic Test – Mechanics', 'medium', 'As a block moves up an incline at constant speed, the frictional force performs −5 J of work on the block. As the block moves down the same incline at constant speed over the same distance, how much work does the frictional force perform on the block?', '["−5 J","0 J","+5 J","It depends on the angle of elevation of the incline.","It depends on whether the applied force is the same in both situations."]'::jsonb, '(E) The fact that the net force is zero does not constrain the frictional force to a single value. Instead, the frictional force depends on the nature of the applied force and the resulting normal force. Consider, for example, the two cases in the figure that show two different ways to push a mass up an incline. In case 1, assume that the applied force exactly cancels the gravitational force; thus, both the normal and frictional forces are zero. In case 2, on the other hand, there are nonzero normal and frictional forces. (The component of the applied force parallel to the direction of motion cancels the frictional force such that the net force is zero.) Note: If the normal force were the same on the way up and on the way down, the frictional force would perform −5 J of work on the way down. The kinetic frictional force always opposes the motion and always performs negative work. The friction force is discussed further in Chapter 3; work is discussed in Chapter 4.'),
  ('ap-diag-physc-mech_q14', 'ap-diag-physc-mech', 14, false, 'E', 'Diagnostic Test – Mechanics', 'medium', 'An object of mass m undergoes simple harmonic motion with position x(t) = A cos(omega t) and velocity v(t) = -A omega sin(omega t). Which of the following correctly describes the potential energy U(t) of the oscillator as a function of time?', '["U(t) is constant and independent of time","U(t) reaches its maximum whenever the speed of the object is maximum","U(t) oscillates with angular frequency omega/2","U(t) is zero at the turning points x = +A and x = -A","U(t) oscillates between 0 and 1/2 k A^2, reaching its maxima whenever the velocity is zero"]'::jsonb, 'Total mechanical energy in simple harmonic motion is conserved: E = K + U = 1/2 k A^2. When velocity is zero (at the turning points x = +/- A), kinetic energy K = 1/2 m v^2 = 0, so potential energy U reaches its maximum value of 1/2 k A^2. When velocity is maximum (at equilibrium x = 0), potential energy is zero. Thus U(t) reaches its maximum whenever velocity is zero.'),
  ('ap-diag-physc-mech_q15', 'ap-diag-physc-mech', 15, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'Consider the two concentric cylinders in the figure, which are fastened to each other and suspended by a pin through their center, which exerts a force of F1. Two additional forces, F2 and F3, act on the cylinders as shown. Which of the following equations is a necessary condition for the two-cylinder system to remain in static equilibrium?', '["F1 − F3 sin − F2 sin \\theta = 0","F1 − F3 cos + F2 cos \\theta = 0","F2 cos\\theta − F3 cos = 0","F2(cos\\theta)r2 − F3(cos )r1 = 0","F2(cos\\theta)r1 − F3(cos )r2 = 0 Questions 16–18 refer to the figure below, which shows a mass m connected to a spring (of spring constant k) rotating in a circle on a frictionless table at constant speed."]'::jsonb, '(D) The following equations are required for static equilibrium. The net force in the x-direction must be zero: The net force in the y-direction must be zero: The net torque about their centers must be zero: Inspection reveals that the only valid choice is (D), which is the negative of the torque condition above. For further information about the static equilibrium of extended objects (objects that can rotate), see Chapter 7.'),
  ('ap-diag-physc-mech_q16', 'ap-diag-physc-mech', 16, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'If x is the extension of the spring from its unstretched length, v is the speed of the mass, and r is the radius of the circular path, which of the following equations is valid?', '["kx = mv 2/2","kx 2/2 = mv 2/2","kx 2/2 = mv 2/r","kx = mv 2/r","None of the above equations are valid."]'::jsonb, '(D) The spring force provides the centripetal force, so it must equal the centripetal force. The centripetal force is discussed in the section on uniform circular motion in Chapter 2.'),
  ('ap-diag-physc-mech_q17', 'ap-diag-physc-mech', 17, false, 'E', 'Diagnostic Test – Mechanics', 'medium', 'A block of mass m is attached to one end of a light horizontal spring with spring constant k. The other end of the spring is pivoted at a fixed point on a frictionless horizontal table. The block is set into uniform circular motion of radius r with constant speed v, maintaining a constant spring stretch x. What is the rate at which the spring does work on the block (the instantaneous power delivered by the spring)?', '["kx v","1/2 k x^2 (v / r)","k x^2 v / m","k x r sqrt(k/m)","Zero"]'::jsonb, 'Instantaneous power is defined as P = F * v. For uniform circular motion, the spring force acts as the centripetal force and is directed radially inward toward the pivot, while the instantaneous velocity is directed tangentially along the circle. Because F and v are perpendicular at all times, F * v = |F||v| cos(90 deg) = 0. Therefore, the spring does zero work and delivers zero power to the block.'),
  ('ap-diag-physc-mech_q18', 'ap-diag-physc-mech', 18, false, 'A', 'Diagnostic Test – Mechanics', 'medium', 'Consider the block in the previous problem moving in a circle of radius r with the spring stretched by an extension x. If the spring is suddenly cut, what is the change in the elastic potential energy stored in the spring as it returns to its unstretched equilibrium length?', '["A decrease of 1/2 k x^2","An increase of 1/2 k x^2","A decrease of k x^2","A decrease of 1/2 m v^2","No change in energy"]'::jsonb, 'Before being cut, the spring is stretched by x and stores elastic potential energy U_initial = 1/2 k x^2. After being cut, the spring is free of tension and relaxes to its unstretched equilibrium length where x = 0 and U_final = 0. The change in the spring''s potential energy is Delta U = U_final - U_initial = 0 - 1/2 k x^2 = -1/2 k x^2 (a decrease of 1/2 k x^2).'),
  ('ap-diag-physc-mech_q19', 'ap-diag-physc-mech', 19, false, 'B', 'Diagnostic Test – Mechanics', 'medium', 'Consider a disk that has uniform density and a hole as shown. Where is the center of mass of this disk located?', '["point A","point B","point C","point D","point E"]'::jsonb, '(B) There is more mass to the left of point C than to the right of point C, so the center of mass must lie to the left of point C. Because all the mass lies to the right of point A, point A cannot be the center of mass. Thus, by elimination, the center of mass must be point B. Note that the center of mass must lie on the horizontal line AE because of symmetry. Further information about calculating the center of mass of this object can be found in Example 5.10.'),
  ('ap-diag-physc-mech_q20', 'ap-diag-physc-mech', 20, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'A mass m is suspended by two ropes as shown. What is the tension in each of the ropes?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(D) Because of symmetry, the two tension forces will be equal in magnitude. Therefore, to keep the mass in static equilibrium requires . Solving this equation for the tension force gives choice (D). More information about the static equilibrium of point masses can be found in Chapter 3 (particularly Example 3.3).'),
  ('ap-diag-physc-mech_q21', 'ap-diag-physc-mech', 21, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'What is the maximum speed of a simple pendulum with length l whose maximum angle of displacement from the vertical is \theta?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Not enough information given."]'::jsonb, '(D) At the maximum height of the pendulum, all the energy is gravitational potential energy. At the minimum height of the pendulum, all this potential energy has been converted to kinetic energy. Energy conservation between these extreme points yields (y is set equal to zero at the bottom of the pendulum’s arc; see Example 8.1 for the geometry of the height difference.) Solving for velocity yields choice (D). Further information about the conservation of energy can be found in Chapter 4.'),
  ('ap-diag-physc-mech_q22', 'ap-diag-physc-mech', 22, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'A ball released from rest at height h rolls down a curved incline without slipping, as shown. What fraction of its final angular speed \omegaf does the ball have at point P?', '["\\omegap = \\omegaf / 4","(C) \\omegap = \\omegaf / 2","1","(E) \\omegap = \\omegaf","4"]'::jsonb, '(D) Because the ball rolls without slipping, the relationship between the velocity of its center of mass and its angular velocity is v = r\omega. Therefore, the total kinetic energy of the ball is equal to so that the kinetic energy is proportional to \omega2. The kinetic energy at the bottom of the incline is twice the kinetic energy at point P (because half of the gravitational potential energy has been converted to kinetic energy at point P). Therefore, the angular velocity is smaller by a factor of at point P. Gravitational potential energy is discussed in Chapter 4, while rotational kinetic energy is covered in Chapter 6.'),
  ('ap-diag-physc-mech_q23', 'ap-diag-physc-mech', 23, false, 'E', 'Diagnostic Test – Mechanics', 'medium', 'Which of the following is true of the potential and kinetic energies in a system undergoing SHM?', '["The total energy is maximized at the equilibrium point.","The total energy is maximized at the turning points.","The sum of the potential and kinetic energies varies sinusoidally.","The kinetic energy is maximized when the acceleration is maximized.","The maximum potential energy equals the maximum kinetic energy."]'::jsonb, '(E) Choices (A), (B), and (C) are false because the total energy is constant. Choice (D) is false because the kinetic energy is maximized at the equilibrium point, where the acceleration is zero. Choice (E) is correct because the maximum potential energy equals the maximum kinetic energy, which equals the total energy.'),
  ('ap-diag-physc-mech_q24', 'ap-diag-physc-mech', 24, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'Consider a planet in an elliptical orbit around the sun as shown. Which of the following is the correct ratio of the magnitudes of the planet’s acceleration at points A and B?', '["aA/aB = rA/rB","aA/aB = rB/rA","1","2","4"]'::jsonb, '(D) The acceleration is equal to the net force divided by the mass, and the net force at either of the points is equal to the gravitational force due to the sun. Therefore, and . Finding the ratio of these two accelerations yields choice (D). Further information about universal gravitation can be found in Chapter 9.'),
  ('ap-diag-physc-mech_q25', 'ap-diag-physc-mech', 25, false, 'C', 'Diagnostic Test – Mechanics', 'medium', 'If an object of mass m moves along a straight line such that its position as a function of time is given by x(t) = v0 t, where v0 is a constant velocity, what is the object''s kinetic energy?', '["Zero","1/2 m v0 t","1/2 m v0^2 (a constant independent of time)","m v0^2 t^2","1/2 m (v0 t)^2"]'::jsonb, 'The velocity of the object is v(t) = dx/dt = d(v0 t)/dt = v0, which is constant over time. The kinetic energy is K = 1/2 m v^2 = 1/2 m v0^2, which is constant and independent of time.'),
  ('ap-diag-physc-mech_q26', 'ap-diag-physc-mech', 26, false, 'B', 'Diagnostic Test – Mechanics', 'medium', 'In order to swim directly across a stream with water moving with speed vstream with respect to the ground as shown, which of the following is required of the magnitude of the swimmer’s speed with respect to the water, vswimmer?', '["vswimmer = vstream","vswimmer > vstream","Perpendicular into the page","Perpendicular out of the page","vswimmer > 0"]'::jsonb, '(B) The relative velocity vectors are shown in the figure accompanying the question. The velocity of the swimmer with respect to the ground is equal to the velocity of the swimmer with respect to the water (vswimmer) plus the velocity of the water with respect to the ground (vstream). In order for the sum of these velocities to point directly across the stream, the swimmer’s velocity vswimmer must (1) cancel the velocity of the current vstream and (2) provide a perpendicular component across the stream. For vswimmer to have a y-component equal in magnitude to vstream and a nonzero x-component, its magnitude must be greater than vstream. Imagine what would happen if vswimmer = vstream. If the swimmer swam in the direction opposite the current, the swimmer would remain stationary with respect to the shore. If the swimmer tried to cross the stream, the y-component of vswimmer would be less than vstream, and the swimmer would be swept downstream. Although it would be possible to cross the stream, it would be impossible to cross the stream along a path perpendicular to the banks of the stream. Further information about relative velocity can be found in Chapter 2 (in particular, see Example 2.9).'),
  ('ap-diag-physc-mech_q27', 'ap-diag-physc-mech', 27, false, 'A', 'Diagnostic Test – Mechanics', 'medium', 'What is the effective spring constant of two identical springs (each of spring constant k) attached in series (end-to-end—see question 12)?', '["k/2","Inversely proportional to the square of the separation","k","(E) 2k","Zero net change under static equilibrium conditions"]'::jsonb, '(A) Because the springs are identical, they are stretched the same amount. (This is required in order for the tension force to be constant throughout the two springs. If the tension in the springs were not equal, there would be a net force on the point where the springs were connected together, causing the extension of the springs to change until the two tension forces were equal.) Therefore, when a mass attached to the two springs is moved a distance \Delta x, each spring is displaced by an amount \Delta x/2 such that the tension force within each spring is F = −k(\Delta x/2). This tension force is equal to the force the springs exert on the mass so that the effective spring constant is keffective = −F/\Delta x = k/2.'),
  ('ap-diag-physc-mech_q28', 'ap-diag-physc-mech', 28, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'If the angular velocity of a disk is given in rads by the equation \omega(t) = 9 + 3t, what is the disk’s angular displacement between t = 0 and t = 1 s?', '["0.75 rad","8.25 rad","9 rad","10.5 rad","18 rad"]'::jsonb, '(D) The angular velocity is proportional to t, thus the angular acceleration is constant. The angular displacement then obeys (see Chapter 6) with \omega0 = 9 and \alpha = 3. Thus, the angular displacement is (9)(1 − 0) + 0.5(3)(1) = 10.5 rad.'),
  ('ap-diag-physc-mech_q29', 'ap-diag-physc-mech', 29, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'You open a 1.0 m-wide door by pushing on the edge farthest from the hinge. You apply a force of 2.0 N at right angles to the front of the door. If you rotate the door 0.5 radians in 0.5 s, at what rate have you done work on the door?', '["−2.0 J/s","0.25 J/s","0.5 J/s","2.0 J/s","4.0 J/s"]'::jsonb, '(D) You exert a constant torque of (1.0 m)(2.0 N) sin 90° on the door. The rate at which you do work is given (for constant torque) by choice (D).'),
  ('ap-diag-physc-mech_q30', 'ap-diag-physc-mech', 30, false, 'C', 'Diagnostic Test – Mechanics', 'medium', 'A projectile is launched vertically upward into the air. When is the rate of work done by gravity on the projectile maximized?', '["at the top of the trajectory","right after the particle is launched","right before the particle hits the ground","The rate is constant.","The rate is zero."]'::jsonb, '(C) P = F \cdot  v. The force is the constant downward gravitational force, so the power is maximized when the downward velocity is maximized. This occurs just before the particle hits the ground, when it is moving with its maximum speed in the downward direction. Projectile motion is discussed in Chapter 2, and power is discussed in Chapter 4.')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-diag-physc-mech_q31', 'ap-diag-physc-mech', 31, false, 'C', 'Diagnostic Test – Mechanics', 'medium', 'A planet moves in an elliptical orbit around the sun (which is assumed to be stationary) as shown. What is the planet’s speed v2 at the point of closest approach to the sun?', '["v2 = v1","v2 = v1r2/r1","v2 = (v1r1 sin \\theta)/r2","v2 = (v1r1 cos \\theta)/v2","v2 = (v1r1 tan \\theta)/v2"]'::jsonb, '(C) The angular momentum around the sun is constant. Therefore, using the equation . Solving for v2 yields choice (C).'),
  ('ap-diag-physc-mech_q32', 'ap-diag-physc-mech', 32, false, 'A', 'Diagnostic Test – Mechanics', 'medium', 'The potential function for an object in a region of space where there are no nonconservative forces is U(x) = −ax2 + bx − c. What is the force on the object in this region?', '["F(x) = 2ax − b","F(x) = −2ax + b","F(x) = m(2ax − b)","F(x) = m(−2ax + b)","F(x) = (ax3/3) − (bx2/2) + cx"]'::jsonb, '(A) Using F (x) = −dU/dx, we see that choice (A) is correct.'),
  ('ap-diag-physc-mech_q33', 'ap-diag-physc-mech', 33, false, 'C', 'Diagnostic Test – Mechanics', 'medium', 'If an object’s position is given by the equation (where position is in meters and time is in seconds), what is the magnitude of the object’s velocity at time t = 1?', '["1 m/s","2 m/s","3 m/s","4 m/s","6 m/s"]'::jsonb, '(C) Velocity is the time derivative of position, and taking the derivative yields v(t) = 4 − t. Substituting t = 1 yields choice (C).'),
  ('ap-diag-physc-mech_q34', 'ap-diag-physc-mech', 34, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'Two particles are launched from the top of a building at the same time with the same initial speed. One particle is launched with an initial velocity pointing \theta degrees above the horizontal, while the other particle is launched with an initial velocity pointing \theta degrees below the horizontal, as shown. Discounting air resistance, which of the following is true?', '["Both particles spend the same amount of time in the air.","Both particles hit the ground the same distance from the building.","At any particular instant in time, both particles have the same potential energy.","Both particles hit the ground at the same angle of impact (i.e., when they hit the ground, their velocities are parallel).","none of the above"]'::jsonb, '(D) Conservation of energy requires that both particles have the same kinetic energy when they strike the ground. Because (on impact) they have the same x-component of velocity (their x-components of velocity are initially equal and remain unchanged) and the same initial speeds, they must have the same y-components of velocity (recall that . Therefore, they have the same velocity vector on impact and must also share the same angle of impact.'),
  ('ap-diag-physc-mech_q35', 'ap-diag-physc-mech', 35, false, 'D', 'Diagnostic Test – Mechanics', 'medium', 'A figure skater is spinning without friction when he extends his arms, moving his hands farther from his axis of rotation and decreasing his angular velocity by a factor of 2. Which of the following statements is true?', '["Both his angular momentum and kinetic energy are constant.","His angular momentum decreases by a factor of 2, while his kinetic energy remains constant.","His angular momentum remains constant, while his kinetic energy decreases by a factor of 4.","His angular momentum remains constant, while his kinetic energy decreases by a factor of 2.","His angular momentum remains constant, while his kinetic energy increases by a factor of 2. Free-Response Questions DIRECTIONS: Use separate sheets of paper to write down your answers to the free-response questions. You may refer to the formula sheet in the Appendix (pages 575–578). Mechanics Mechanics I A pulley consists of two cylinders of radii r and 2r (see figure) with a total rotational inertia of I. Mass m2 is sliding along a frictionless incline with an angle of elevation of \\theta. Assume that both m1 and m2 have the same mass m. (a) Given that the angular acceleration of the pulley is zero (and assuming that the rope rolls without slipping over the pulley), what is the angle of elevation of the inclined plane? (b) If the mass on the inclined plane is sliding down the ramp with a speed of v2, what is the speed of the hanging mass? Then the rope attaching m2 to the pulley is cut, causing the hanging mass to accelerate. (c) What is the acceleration of the hanging mass, m1, under these conditions? (d) What is the rate at which the kinetic energy of the pulley and m1 is changing? (Your answer can include the angular speed of the pulley, \\omega.) Mechanics II A roller coaster (mass m), starting from rest at a height h, goes around a circular loop of radius r as shown. (a) If the normal force exerted on the roller coaster by the track at the top of the loop is zero, what is the roller coaster’s speed at this point? (b) Assuming that the track is frictionless, at what height h must the roller coaster have started? (c) Draw a free-body diagram for the roller coaster as it passes point A. (d) What is the object’s speed as it passes through point A? Mechanics III A horizontal force F acts on a mass m sliding along an inclined plane with a coefficient of kinetic friction \\muk, as shown."]'::jsonb, '(D) The ice exerts no torque on the skater. (The normal force acts essentially at the axis of rotation and exerts zero torque.) Therefore, the skater’s angular momentum, L = I\omega, must remain constant (such that if the angular velocity decreases by a factor of 2, the moment of inertia must increase by a factor of 2). Given these changes, the kinetic energy, , decreases by a factor of 2. Free-Response Mechanics I (a) If the angular acceleration is zero, the acceleration of the two masses m1 and m2 must be zero (assuming that there’s no slippage of the rope so that the masses cannot accelerate while the pulley rotates at a constant angular speed). This means that the net forces on these objects must be zero, which requires that T1 = mg and T2 = mg sin \theta. Note that m1 = m2 =m. Because the angular acceleration is zero, the net torque must also be zero. Designating counterclockwise torque as positive (and using the tension forces just calculated), we find that the net torque on the pulley is given by This part involves Newton’s laws (Chapter 3) and their application to rotational motion. (b) For both m1 and m2, the equation v = r\omega (i.e., rolling without slipping of the rope) holds: (c) Applying Newton’s second law to the hanging mass (and designating downward acceleration as positive) yields Applying Newton’s second law to the pulley (and designating counterclockwise acceleration as positive such that both the linear and angular accelerations are positive), The final equation relates the linear acceleration of m1 and the angular acceleration of the pulley (expressing the fact that the pulley rolls without slipping on the rope connecting it to m1): a = r\alpha. Solving these three equations with three unknown variables for a yields (d) Because of conservation of energy, the rate at which the kinetic energy is changing is equal to the rate at which the potential energy is decreasing. Because the gravitational force is converting potential energy to kinetic energy, this rate is equal to the power exerted by gravity, given by the formula P = F \cdot  v. When the pulley is rotating with a speed of \omega, the speed of the falling mass is v = r\omega (downward, parallel to gravity), so the power is P = F \cdot  v = gmr\omega. For further discussion of work, power, and translational KE, see Chapter 4. Mechanics II (a) The normal force at the top of the loop is zero, so the radial force is equal to the gravitational force, which must equal the centripetal force: Solving for the speed, (b) Applying conservation of energy between the initial position of the roller coaster and the top of the loop (and using the previous result for the speed at the top of the loop), (c) The forces are shown in the figure (the construction of free-body diagrams is discussed in Chapter 3). (d) Using energy conservation again [comparing the initial position of the roller coaster at height 2.5r with point A at height r(1 − sin \theta)], Mechanics III (a) The free-body diagram is shown. (b) Because the block remains on the incline, the acceleration and the net force in the y-direction are zero: The acceleration is parallel to the x-direction: This yields two equations with three variables. The final equation is Ffr = \mukFN. Solving these equations for the acceleration yields (c) The block leaves the incline when it has a net force in the y-direction (and thus a net acceleration in the y-direction). Recall the equation for the net force in the y-direction: Imagine increasing F from zero. As the applied force F increases, the normal force decreases such that the net force in the y-direction is zero and the block remains on the incline. However, the normal force cannot decrease indefinitely because it can never be negative. The maximum force that can be applied without causing the block to leave the incline occurs when the normal force is equal to zero: Solving for F yields F = mg cot\theta. Any force greater than this would produce a positive acceleration in the y-direction, causing the block to accelerate away from the incline. For further information on the construction of free-body diagrams and solutions to inclined plane problems, see Chapter 3. (d) According to part (c), the maximum force is given by F = mg cot\theta. Thus, plot F on one axis and cot\theta on the other. (e) The figure shows the plot and the straight-line fit. The slope of the line is given approximately by: The answer to part (c) predicts that this value should be mg = (1)(9.8) N = 9.8 N.'),
  ('ap-topic-physc-forces_q1', 'ap-topic-physc-forces', 1, false, 'E', 'Newton''s Third Law Action-Reaction Pairs', 'easy', 'A box is dragged across a table at constant velocity by a string. Which of the following is a Newton''s Third Law action-reaction pair?  I. Force of gravity on the box and normal force on the box  II. Force of friction on the box and tension force on the box  III. Force of the box pushing down on the table and normal force of the table pushing up on the box', '["I only","I and II only","II only","I and III only","III only"]'::jsonb, '(E) An action-reaction pair must involve mutual forces of the same physical type exerted between the same two objects in opposite directions. The table pushing up on the box ($F_{N,\text{table on box}}$) and the box pushing down on the table ($F_{N,\text{box on table}}$) act on each other, satisfying Newton''s Third Law.'),
  ('ap-topic-physc-forces_q2', 'ap-topic-physc-forces', 2, false, 'D', 'Apparent Weight in Accelerating Elevator', 'easy', 'A person who weighs $800\text{ N}$ steps onto a scale in an elevator accelerating upward at $5\text{ m/s}^2$. What will the scale read? ($g = 10\text{ m/s}^2$)', '["$400\\text{ N}$","$800\\text{ N}$","$1,000\\text{ N}$","$1,200\\text{ N}$","$1,600\\text{ N}$"]'::jsonb, '(D) Mass $m = \frac{W}{g} = \frac{800\text{ N}}{10\text{ m/s}^2} = 80\text{ kg}$.
Using Newton''s Second Law with upward as positive:
  $$F_N - mg = ma \implies F_N = m(g + a) = (80\text{ kg})(10 + 5\text{ m/s}^2) = 1,200\text{ N}$$'),
  ('ap-topic-physc-forces_q3', 'ap-topic-physc-forces', 3, false, 'D', 'Two-Block System Tension & Acceleration', 'medium', 'A horizontal force of $20\text{ N}$ pulls on a $1.0\text{ kg}$ block attached by a string to a $2.0\text{ kg}$ block on a frictionless surface. Find the tension $F_T$ in the connecting string and the acceleration $a$ of the system.', '["$F_T = 13.3\\text{ N},\\ a = 10\\text{ m/s}^2$","$F_T = 13.3\\text{ N},\\ a = 20\\text{ m/s}^2$","$F_T = 15\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_T = 13.3\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_T = 20\\text{ N},\\ a = 6.7\\text{ m/s}^2$"]'::jsonb, '(D) System acceleration:
  $$a = \frac{F_{\text{applied}}}{m_1 + m_2} = \frac{20\text{ N}}{1.0 + 2.0\text{ kg}} = \frac{20}{3}\text{ m/s}^2 \approx 6.7\text{ m/s}^2$$
Tension pulling the trailing $2.0\text{ kg}$ block:
  $$F_T = m_2 a = (2.0\text{ kg})\left(\frac{20}{3}\text{ m/s}^2\right) = \frac{40}{3}\text{ N} \approx 13.3\text{ N}$$'),
  ('ap-topic-physc-forces_q4', 'ap-topic-physc-forces', 4, false, 'C', 'Three-Block Frictionless Train Tensions', 'medium', 'A force of $20\text{ N}$ pulls a chain of three frictionless blocks: $3.0\text{ kg} - 2.0\text{ kg} - 1.0\text{ kg}$. Find $F_{T1}$ (between $1\text{ kg}$ and $2\text{ kg}$), $F_{T2}$ (between $2\text{ kg}$ and $3\text{ kg}$), and acceleration $a$.', '["$F_{T1} = 1\\text{ N},\\ a = 1\\text{ m/s}^2$","$F_{T1} = 3.3\\text{ N},\\ F_{T2} = 3.3\\text{ N},\\ a = 3.3\\text{ m/s}^2$","$F_{T1} = 3.3\\text{ N},\\ F_{T2} = 10\\text{ N},\\ a = 3.3\\text{ m/s}^2$","$F_{T1} = 3.3\\text{ N},\\ F_{T2} = 10\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_{T1} = 10\\text{ N},\\ a = 6.7\\text{ m/s}^2$"]'::jsonb, '(C) $$a = \frac{20\text{ N}}{1.0 + 2.0 + 3.0\text{ kg}} = \frac{20}{6}\text{ m/s}^2 = 3.33\text{ m/s}^2$$
$$F_{T1} = m_1 a = (1.0\text{ kg})(3.33\text{ m/s}^2) = 3.33\text{ N}$$
$$F_{T2} = (m_1 + m_2)a = (1.0 + 2.0\text{ kg})(3.33\text{ m/s}^2) = 10.0\text{ N}$$'),
  ('ap-topic-physc-forces_q5', 'ap-topic-physc-forces', 5, false, 'A', 'Incline Static Friction Threshold', 'medium', 'A box is placed at rest on a ramp ($\theta = 30^\circ, \mu_s = 0.5$). The box will:', '["Accelerate down the ramp","Accelerate briefly then stop","Move with constant velocity","Not move","Cannot be determined"]'::jsonb, '(A) Downhill gravitational component: $F_{g,\parallel} = mg\sin(30^\circ) = 0.50\,mg$.
Maximum static friction force:
  $$f_{s,\max} = \mu_s mg\cos(30^\circ) = (0.5)(0.866\,mg) \approx 0.433\,mg$$
Because $F_{g,\parallel} > f_{s,\max}$ ($0.50\,mg > 0.433\,mg$), the net force down the ramp is positive, and the box will accelerate down.'),
  ('ap-topic-physc-forces_q6', 'ap-topic-physc-forces', 6, false, 'C', 'Atwood Machine System Acceleration', 'easy', 'In an Atwood machine with hanging masses $m$ and $4m$, find the acceleration.', '["$0.2g$","$0.4g$","$0.6g$","$0.75g$","$0.8g$"]'::jsonb, '(C) $$a = \frac{m_2 - m_1}{m_1 + m_2}g = \frac{4m - m}{4m + m}g = \frac{3}{5}g = 0.6g$$'),
  ('ap-topic-physc-forces_q7', 'ap-topic-physc-forces', 7, false, 'E', 'Two-Block System with Kinetic Friction', 'medium', 'A $20\text{ N}$ force pulls a $2.0\text{ kg}$ block connected to a $1.0\text{ kg}$ trailing block on a rough surface ($\mu_k = 0.2$). Find the tension $F_T$ and acceleration $a$ ($g = 10\text{ m/s}^2$).', '["$F_T = 1\\text{ N},\\ a = 4.7\\text{ m/s}^2$","$F_T = 3.3\\text{ N},\\ a = 4.7\\text{ m/s}^2$","$F_T = 3.3\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_T = 6.7\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_T = 6.7\\text{ N},\\ a = 4.7\\text{ m/s}^2$"]'::jsonb, '(E) Total friction force: $f_{\text{total}} = \mu_k(m_1 + m_2)g = (0.2)(3.0\text{ kg})(10\text{ m/s}^2) = 6\text{ N}$.
Acceleration: $a = \frac{F - f_{\text{total}}}{m_1 + m_2} = \frac{20 - 6}{3} = \frac{14}{3} \approx 4.7\text{ m/s}^2$.
Tension on the $1.0\text{ kg}$ trailing block:
  $$F_T - f_1 = m_1 a \implies F_T = (0.2)(1.0)(10) + (1.0)(4.7) = 2.0 + 4.7 = 6.7\text{ N}$$'),
  ('ap-topic-physc-forces_q8', 'ap-topic-physc-forces', 8, false, 'B', 'Incline Gravitational Scaling', 'easy', 'An object slides down a frictionless incline of angle $\theta$ and reaches final speed $v$. On a planet with twice Earth''s gravitational acceleration ($2g$), what will be its final speed?', '["$v$","$\\sqrt{2}v$","$2v$","$4v$","$v/2$"]'::jsonb, '(B) Using $v = \sqrt{2ad} = \sqrt{2(g\sin\theta)d} \propto \sqrt{g}$. Doubling $g$ scales the final velocity by a factor of $\sqrt{2}$, giving $v_{\text{new}} = \sqrt{2}v$.'),
  ('ap-topic-physc-forces_q9', 'ap-topic-physc-forces', 9, false, 'B', 'Vertical Loop Minimum Cut-Off Speed', 'medium', 'A roller coaster completes a loop of radius $r = 25\text{ m}$. What is the minimum speed needed at the top of the loop for riders to remain safely in contact with the track? ($g = 10\text{ m/s}^2$)', '["$12.7\\text{ m/s}$","$15.8\\text{ m/s}$","$21.2\\text{ m/s}$","$29.3\\text{ m/s}$","$33.3\\text{ m/s}$"]'::jsonb, '(B) At critical cut-off speed, normal force $F_N \to 0$, so gravity alone provides the centripetal acceleration:
  $$\frac{mv^2}{r} = mg \implies v = \sqrt{gr} = \sqrt{(10\text{ m/s}^2)(25\text{ m})} = \sqrt{250} \approx 15.8\text{ m/s}$$'),
  ('ap-topic-physc-forces_q10', 'ap-topic-physc-forces', 10, false, 'B', 'Vertical Circular Motion Bottom Tension', 'medium', 'A bucket of mass $3\text{ kg}$ on a $0.6\text{-m}$ rope is whirled in a vertical circle. At the lowest point, the tension is $50\text{ N}$. What is the speed of the bucket? ($g = 10\text{ m/s}^2$)', '["$1\\text{ m/s}$","$2\\text{ m/s}$","$3\\text{ m/s}$","$4\\text{ m/s}$","$5\\text{ m/s}$"]'::jsonb, '(B) At the bottom of the circle: $F_T - mg = \frac{mv^2}{r}$.
  $$50\text{ N} - (3\text{ kg})(10\text{ m/s}^2) = \frac{3 v^2}{0.6} \implies 20 = 5v^2 \implies v^2 = 4 \implies v = 2\text{ m/s}$$'),
  ('ap-topic-physc-forces_q11', 'ap-topic-physc-forces', 11, false, 'C', 'Vertical String Circle Critical Apex Speed', 'medium', 'What is the critical speed at the top of the vertical circle for the bucket in Question 10 so the rope does not become slack?', '["$0.6\\text{ m/s}$","$1.8\\text{ m/s}$","$2.4\\text{ m/s}$","$3.2\\text{ m/s}$","$4.8\\text{ m/s}$"]'::jsonb, '(C) $$v_{\text{critical}} = \sqrt{gr} = \sqrt{(10\text{ m/s}^2)(0.60\text{ m})} = \sqrt{6.0} \approx 2.45\text{ m/s} \approx 2.4\text{ m/s}$$'),
  ('ap-topic-physc-forces_q12', 'ap-topic-physc-forces', 12, false, 'D', 'Centripetal Acceleration & Angular Frequency', 'easy', 'An object moves at constant speed in a circular path of radius $r$ at 1 revolution per second. What is its centripetal acceleration?', '["$2\\pi r$","$2\\pi^2 r$","$2\\pi^2 r^2$","$4\\pi^2 r$","$4\\pi^2 r^2$"]'::jsonb, '(D) With angular frequency $\omega = 2\pi f = 2\pi(1) = 2\pi\text{ rad/s}$:
  $$a_c = \omega^2 r = (2\pi)^2 r = 4\pi^2 r$$'),
  ('ap-topic-physc-momentum_q1', 'ap-topic-physc-momentum', 1, false, 'C', 'Momentum-Kinetic Energy Relationship', 'easy', 'An object of mass $2\text{ kg}$ has a linear momentum of magnitude $6\text{ kg}\cdot\text{m/s}$. What is this object''s kinetic energy?', '["$3\\text{ J}$","$6\\text{ J}$","$9\\text{ J}$","$12\\text{ J}$","$18\\text{ J}$"]'::jsonb, '(C) Using the relation between kinetic energy and momentum ($K = \frac{p^2}{2m}$):
  $$K = \frac{(6\text{ kg}\cdot\text{m/s})^2}{2(2\text{ kg})} = \frac{36}{4} = 9\text{ J}$$'),
  ('ap-topic-physc-momentum_q2', 'ap-topic-physc-momentum', 2, false, 'D', 'Impulse-Momentum Theorem & Velocity Change', 'easy', 'An object of mass $8\text{ kg}$ is moving in a straight line. If the impulse calculated from the force-time graph ($J = \int F\,dt$) is $80\text{ N}\cdot\text{s}$, what is its change in speed?', '["$16\\text{ m/s}$","$14\\text{ m/s}$","$12\\text{ m/s}$","$10\\text{ m/s}$","$8\\text{ m/s}$"]'::jsonb, '(D) By the Impulse-Momentum Theorem ($J = \Delta p = m\Delta v$):
  $$\Delta v = \frac{J}{m} = \frac{80\text{ N}\cdot\text{s}}{8\text{ kg}} = 10\text{ m/s}$$'),
  ('ap-topic-physc-momentum_q3', 'ap-topic-physc-momentum', 3, false, 'E', 'Average Impact Force Calculation', 'easy', 'A box of mass $2\text{ kg}$ accelerates in a straight line from $4\text{ m/s}$ to $8\text{ m/s}$ due to a force applied for $0.5\text{ s}$. Find the average strength of this force.', '["$4\\text{ N}$","$8\\text{ N}$","$12\\text{ N}$","$14\\text{ N}$","$16\\text{ N}$"]'::jsonb, '(E) $$F_{\text{avg}} = \frac{m(v_f - v_i)}{\Delta t} = \frac{(2\text{ kg})(8\text{ m/s} - 4\text{ m/s})}{0.5\text{ s}} = \frac{8}{0.5} = 16\text{ N}$$'),
  ('ap-topic-physc-momentum_q4', 'ap-topic-physc-momentum', 4, false, 'D', 'Elastic Wall Rebound Impulse', 'easy', 'A ball of mass $m$ traveling horizontally with velocity $v$ strikes a massive vertical wall and rebounds back along its original direction with no change in speed. What is the magnitude of the impulse delivered by the wall to the ball?', '["$0$","$\\frac{1}{2}mv$","$mv$","$2mv$","$4mv$"]'::jsonb, '(D) Taking the rebound direction as positive:
$$J = |\Delta p| = |m(v) - m(-v)| = 2mv$$'),
  ('ap-topic-physc-momentum_q5', 'ap-topic-physc-momentum', 5, false, 'B', '1D Perfectly Inelastic Collision Velocity', 'medium', 'Two objects, one of mass $3\text{ kg}$ moving at $2\text{ m/s}$ and the other of mass $5\text{ kg}$ moving at $2\text{ m/s}$ toward each other, collide head-on in a perfectly inelastic collision. Find the speed of the objects after the collision.', '["$0.25\\text{ m/s}$","$0.5\\text{ m/s}$","$0.75\\text{ m/s}$","$1.0\\text{ m/s}$","$2.0\\text{ m/s}$"]'::jsonb, '(B) Using conservation of linear momentum:
$$m_1 v_1 + m_2 v_2 = (m_1 + m_2)v_f \implies (3)(2) + (5)(-2) = (3 + 5)v_f$$
$$6 - 10 = 8v_f \implies v_f = -\frac{4}{8} = -0.5\text{ m/s}$$
The resulting speed is $0.5\text{ m/s}$.'),
  ('ap-topic-physc-momentum_q6', 'ap-topic-physc-momentum', 6, false, 'D', 'Static Equilibrium & Center of Mass', 'medium', 'A student balances a meter stick at its midpoint ($50\text{ cm}$). Given hanging masses $m_1 = 6\text{ kg}$ at $x = 0\text{ cm}$ and $m_2 = 2\text{ kg}$ at $x = 100\text{ cm}$, how far from the left edge should a third mass $m_3 = 10\text{ kg}$ be hung to balance the meter stick?', '["$40\\text{ cm}$","$50\\text{ cm}$","$60\\text{ cm}$","$70\\text{ cm}$","$80\\text{ cm}$"]'::jsonb, '(D) For rotational static equilibrium about the midpoint ($50\text{ cm}$), the system center of mass must equal $50\text{ cm}$ ($0.50\text{ m}$):
  $$x_{\text{cm}} = \frac{m_1 x_1 + m_2 x_2 + m_3 x_3}{m_1 + m_2 + m_3} \implies 0.50 = \frac{6(0) + 2(1.0) + 10 x_3}{6 + 2 + 10}$$
  $$0.50(18) = 2.0 + 10 x_3 \implies 9.0 - 2.0 = 10 x_3 \implies x_3 = 0.70\text{ m} = 70\text{ cm}$$'),
  ('ap-topic-physc-momentum_q7', 'ap-topic-physc-momentum', 7, false, 'C', 'Collision Elasticity & Momentum Conservation', 'easy', 'Two objects move toward each other, collide, and separate. If there was no net external force acting on the objects, but some kinetic energy was lost, then:', '["the collision was elastic and momentum was conserved","the collision was elastic and momentum was not conserved","the collision was not elastic and total linear momentum was conserved","the collision was not elastic and momentum was not conserved","Cannot be determined"]'::jsonb, '(C) With zero net external force ($F_{\text{net}} = 0$), linear momentum is strictly conserved in all collisions. Because mechanical kinetic energy is lost, the collision is by definition inelastic.'),
  ('ap-topic-physc-momentum_q8', 'ap-topic-physc-momentum', 8, false, 'B', 'U-Shaped Rod Assembly Center of Mass', 'medium', 'Three thin, uniform rods each of length $L$ are arranged in an inverted U-shape. The two vertical arms each have mass $m$; the horizontal top rod has mass $2m$. How far below the midpoint of the horizontal rod is the center of mass of the assembly?', '["$L/8$","$L/4$","$3L/8$","$L/2$","$3L/4$"]'::jsonb, '(B) Set $y = 0$ at the horizontal rod. The center of mass of the top rod ($2m$) is at $y = 0$. Each vertical rod ($m$) has its center of mass at $y = -L/2$.
  $$y_{\text{cm}} = \frac{(2m)(0) + m(-L/2) + m(-L/2)}{2m + m + m} = \frac{-mL}{4m} = -\frac{1}{4}L$$
The assembly center of mass is located a distance of $L/4$ below the horizontal rod.'),
  ('ap-topic-physc-momentum_q9', 'ap-topic-physc-momentum', 9, false, 'B', 'Inelastic Collision & Post-Crash Friction Work', 'medium', 'A car of mass $1,000\text{ kg}$ collides head-on with a truck of mass $2,000\text{ kg}$, both initially moving at $21\text{ m/s}$. The collision is perfectly inelastic. After the crash, the combined wreckage skids to a halt. How much work is done by friction after the crash?', '["$73,500\\text{ J}$","$-73,500\\text{ J}$","$147,000\\text{ J}$","$-147,000\\text{ J}$","$220,500\\text{ J}$"]'::jsonb, '(B) Post-collision velocity:
$$v_f = \frac{(2000)(21) + (1000)(-21)}{2000 + 1000} = \frac{21000}{3000} = 7\text{ m/s}$$
Kinetic energy immediately after collision:
$$K = \frac{1}{2}(3000\text{ kg})(7\text{ m/s})^2 = 1500(49) = 73,500\text{ J}$$
Work done by friction to stop the wreckage ($W_f = \Delta K = 0 - K$):
$$W_f = -73,500\text{ J}$$'),
  ('ap-topic-physc-momentum_q10', 'ap-topic-physc-momentum', 10, false, 'D', 'Inelastic Collision Rebound Return Time', 'hard', 'Block 1 ($m_1 = 2\text{ kg}$, $v_1 = 3\text{ m/s}$) and Block 2 ($m_2 = 5\text{ kg}$, $v_2 = 2\text{ m/s}$ towards block 1) start $1\text{ m}$ apart and collide perfectly inelastically. How long after collision does it take to return to one of the starting positions?', '["$0.55\\text{ s}$","$0.75\\text{ s}$","$0.95\\text{ s}$","$1.05\\text{ s}$","$1.25\\text{ s}$"]'::jsonb, '(D) Time to collide: $t_{\text{coll}} = \frac{1\text{ m}}{3 + 2\text{ m/s}} = 0.2\text{ s}$. Collision point is $d_1 = (3)(0.2) = 0.6\text{ m}$ from Block 1''s start.  
Post-collision velocity:
$$v_f = \frac{(2)(3) + (5)(-2)}{2 + 5} = \frac{-4}{7}\text{ m/s}$$
Distance back to Block 1''s starting position is $0.6\text{ m}$.  
Time: $t = \frac{0.6\text{ m}}{4/7\text{ m/s}} = \frac{4.2}{4} = 1.05\text{ s}$.'),
  ('ap-topic-physc-energy_q1', 'ap-topic-physc-energy', 1, false, 'A', 'Perpendicular Force & Zero Work', 'easy', 'A force $F = 20\text{ N}$ acts on a $3\text{ kg}$ object as it moves $4\text{ m}$. If $F$ is perpendicular to displacement, the work done is:', '["$0\\text{ J}$","$60\\text{ J}$","$80\\text{ J}$","$600\\text{ J}$","$2,400\\text{ J}$"]'::jsonb, '(A) $W = \vec{F}\cdot\vec{d} = F d \cos(90^\circ) = 0\text{ J}$. Any force acting strictly perpendicular to displacement performs zero work.'),
  ('ap-topic-physc-energy_q2', 'ap-topic-physc-energy', 2, false, 'B', 'Work-Energy Theorem & Kinetic Energy Change', 'easy', 'An object of mass $4\text{ kg}$ accelerates from $3\text{ m/s}$ to $6\text{ m/s}$ in $8\text{ s}$. How much work was done on the object?', '["$27\\text{ J}$","$54\\text{ J}$","$72\\text{ J}$","$96\\text{ J}$","Cannot be determined"]'::jsonb, '(B) By the Work-Energy Theorem ($W = \Delta K$):
  $$W = \frac{1}{2}m(v_f^2 - v_i^2) = \frac{1}{2}(4\text{ kg})((6\text{ m/s})^2 - (3\text{ m/s})^2) = 2(36 - 9) = 2(27) = 54\text{ J}$$'),
  ('ap-topic-physc-energy_q3', 'ap-topic-physc-energy', 3, false, 'D', 'Path Independence & Conservative Gravitational Work', 'easy', 'To lift a box of mass $m$ to height $h$, three options are considered: Option 1 (direct lift), Option 2 ($30^\circ$ incline), Option 3 (pulley system). Compare the work done under ideal conditions.', '["Option 1 > Option 2 > Option 3","Option 1 > Option 2 = Option 3","Option 1 = Option 3 > Option 2","Option 1 = Option 2 = Option 3","Cannot be determined"]'::jsonb, '(D) Under ideal conservative conditions, gravitational potential energy is path-independent. In all three methods, the minimum work required is identical: $W = mgh$.'),
  ('ap-topic-physc-energy_q4', 'ap-topic-physc-energy', 4, false, 'E', 'Normal Force Zero Work on Incline', 'easy', 'A $4\text{ kg}$ box is pulled up a ramp ($\theta = 30^\circ$, height $= 5\text{ m}$) at constant velocity. How much work is done by the normal force?', '["$160\\text{ J}$","$80\\text{ J}$","$40\\text{ J}$","$20\\text{ J}$","$0\\text{ J}$"]'::jsonb, '(E) The normal force is perpendicular to the ramp surface and therefore perpendicular to the displacement vector of the box ($\theta = 90^\circ$). Thus $W_N = F_N d \cos(90^\circ) = 0\text{ J}$.'),
  ('ap-topic-physc-energy_q5', 'ap-topic-physc-energy', 5, false, 'A', 'Elevator Normal Force Positive Work', 'easy', 'A man stands in an elevator as it begins to ascend. Does the normal force from the floor do work on the man?', '["Yes, and the work done will be positive.","Yes, and the work done will be negative.","Yes, but the sign cannot be determined.","No, the normal force does no work in any situation.","No, normal force does no work here."]'::jsonb, '(A) The normal force pushes upward on the man''s feet ($\vec{F}_N$ is upward) and the elevator displacement is upward ($\vec{d}$ is upward). Because $\vec{F}_N$ and $\vec{d}$ point in the same direction ($\theta = 0^\circ$), $W = F_N d \cos(0^\circ) > 0$ (positive work).'),
  ('ap-topic-physc-energy_q6', 'ap-topic-physc-energy', 6, false, 'D', 'Frictionless Incline Energy Conservation', 'medium', 'A $3.5\text{ kg}$ block slides from rest down a frictionless $30^\circ$ incline of length $6.4\text{ m}$. What is its speed at the bottom? ($g = 10\text{ m/s}^2$)', '["$5.0\\text{ m/s}$","$5.7\\text{ m/s}$","$6.4\\text{ m/s}$","$8.0\\text{ m/s}$","$10\\text{ m/s}$"]'::jsonb, '(D) Vertical height of the incline: $h = L\sin(30^\circ) = 6.4(0.5) = 3.2\text{ m}$.
By Conservation of Energy:
  $$mgh = \frac{1}{2}mv^2 \implies v = \sqrt{2gh} = \sqrt{2(10)(3.2)} = \sqrt{64} = 8.0\text{ m/s}$$'),
  ('ap-topic-physc-energy_q7', 'ap-topic-physc-energy', 7, false, 'D', 'Incline Kinetic Energy with Friction Work', 'medium', 'A block of mass $m$ slides from rest down an incline of length $s$ and height $h$ with kinetic friction force $F_f$. What is the kinetic energy at the bottom?', '["$mgh$","$mgh - F_f h$","$mgs - F_f h$","$mgh - F_f s$","$mgs - F_f s$"]'::jsonb, '(D) Applying the Work-Energy Theorem ($E_i + W_{\text{other}} = E_f$):
  $$mgh - F_f s = K_f \implies K_f = mgh - F_f s$$'),
  ('ap-topic-physc-energy_q8', 'ap-topic-physc-energy', 8, false, 'C', 'Newton''s Second Law with Aerodynamic Drag', 'easy', 'A $1,000\text{ kg}$ car accelerates at $4\text{ m/s}^2$ while experiencing $300\text{ N}$ of drag force. How much force must the engine produce?', '["$16,300\\text{ N}$","$15,700\\text{ N}$","$4,300\\text{ N}$","$4,000\\text{ N}$","$3,700\\text{ N}$"]'::jsonb, '(C) $$F_{\text{engine}} - F_{\text{drag}} = ma \implies F_{\text{engine}} = ma + F_{\text{drag}} = (1,000\text{ kg})(4\text{ m/s}^2) + 300\text{ N} = 4,300\text{ N}$$'),
  ('ap-topic-physc-energy_q9', 'ap-topic-physc-energy', 9, false, 'E', 'Gravitational Free Fall Midpoint Speed Fraction', 'medium', 'An astronaut drops a rock from the top of a crater. When the rock is halfway down to the bottom, its speed is what fraction of its impact speed?', '["$1/4$","$1/2$","$1/\\sqrt{3}$","$\\sqrt{2}/3$","$1/\\sqrt{2}$"]'::jsonb, '(E) At halfway point $h/2$, kinetic energy is half the final kinetic energy: $K_{\text{mid}} = \frac{1}{2}K_{\text{final}}$.
  $$\frac{1}{2}mv_{\text{mid}}^2 = \frac{1}{2}\left(\frac{1}{2}mv_{\text{final}}^2\right) \implies v_{\text{mid}} = \frac{1}{\sqrt{2}}v_{\text{final}}$$'),
  ('ap-topic-physc-energy_q10', 'ap-topic-physc-energy', 10, false, 'D', 'Incline Constant Power Mechanical Derivation', 'hard', 'A block of mass $m$ is pulled up a ramp of length $d$, angle $\theta$, and friction coefficient $\mu$ by a motor at constant power in time $t$. What is the minimum power $P$?', '["$\\frac{md^2}{t^3} + \\frac{mgd\\sin\\theta}{t}$","$\\frac{md^2}{t^2} + mgd\\sin\\theta + \\mu mgd\\cos\\theta$","$\\frac{md^2}{t^3} + \\frac{mgd\\sin\\theta}{t} + \\frac{\\mu mgd\\cos\\theta}{t}$","$\\frac{2md^2}{t^3} + \\frac{mgd\\sin\\theta}{t} + \\frac{\\mu mgd\\cos\\theta}{t}$","$\\frac{md^2}{2t^3} + \\frac{mgd\\cos\\theta}{t} + \\frac{\\mu mgd\\sin\\theta}{t}$"]'::jsonb, '(D) Under constant acceleration to cover distance $d$ in time $t$, $d = \frac{1}{2}at^2 \implies a = \frac{2d}{t^2}$ and $v_f = \frac{2d}{t}$.
Total work done:
  $$W = \Delta K + \Delta U + W_{\text{friction}} = \frac{1}{2}m\left(\frac{2d}{t}\right)^2 + mg(d\sin\theta) + (\mu mg\cos\theta)d$$
Power $P = W/t$:
  $$P = \frac{2md^2}{t^3} + \frac{mgd\sin\theta}{t} + \frac{\mu mgd\cos\theta}{t}$$'),
  ('ap-topic-physc-gravitation_q1', 'ap-topic-physc-gravitation', 1, false, 'E', 'Inverse-Square Gravitational Force Scaling', 'medium', 'An object at altitude $2R_E$ above Earth''s surface experiences gravitational force $F_0$. If its altitude is doubled ($4R_E$), what is the new gravitational force?', '["$F_0/4$","$F_0/25$","$2F_0$","$4F_0/9$","$9F_0/25$"]'::jsonb, '(E) Initial orbital radius from Earth''s center: $r_1 = R_E + 2R_E = 3R_E$.  
Final orbital radius: $r_2 = R_E + 4R_E = 5R_E$.
  $$\frac{F_2}{F_1} = \frac{r_1^2}{r_2^2} = \frac{(3R_E)^2}{(5R_E)^2} = \frac{9}{25} \implies F_2 = \frac{9}{25}F_0$$'),
  ('ap-topic-physc-gravitation_q2', 'ap-topic-physc-gravitation', 2, false, 'E', 'Invariance of Mass & Altitude Weight', 'easy', 'An object has weight $w$ on Earth''s surface. At a height $2R_E$ above the surface, its mass and weight are:', '["mass $m/2$, weight $w/2$","mass $m$, weight $w/2$","mass $m/2$, weight $w/4$","mass $m$, weight $w/4$","mass $m$, weight $w/9$"]'::jsonb, '(E) Mass is invariant ($m$). Distance from Earth''s center is $r = R_E + 2R_E = 3R_E$.
  $$w_{\text{new}} = \frac{GMm}{(3R_E)^2} = \frac{1}{9}\left(\frac{GMm}{R_E^2}\right) = \frac{w}{9}$$'),
  ('ap-topic-physc-gravitation_q3', 'ap-topic-physc-gravitation', 3, false, 'C', 'Newton''s Third Law Mutual Gravity', 'easy', 'A moon of mass $m$ orbits a planet of mass $100m$. If $F_1$ is the force of the planet on the moon and $F_2$ is the force of the moon on the planet, which is true?', '["$F_1 = 100 F_2$","$F_2 = 100 F_1$","$F_1 = F_2$","$F_1 = 10 F_2$","$F_1 = F_2/100$"]'::jsonb, '(C) By Newton''s Third Law, gravitational interaction forces are mutual, equal in magnitude, and opposite in direction ($F_1 = F_2$).'),
  ('ap-topic-physc-gravitation_q4', 'ap-topic-physc-gravitation', 4, false, 'B', 'Planet Surface Gravity & Minimum Radius', 'medium', 'What is the minimum radius of a planet with Earth''s mass so that surface gravity does not exceed $4g$?', '["$R_E/4$","$R_E/2$","$R_E$","$2R_E$","$4R_E$"]'::jsonb, '(B) $$g_{\text{planet}} = \frac{GM}{R^2} \le 4\frac{GM}{R_E^2} \implies \frac{1}{R^2} \le \frac{4}{R_E^2} \implies R \ge \frac{R_E}{2}$$'),
  ('ap-topic-physc-gravitation_q5', 'ap-topic-physc-gravitation', 5, false, 'B', 'Interior vs Exterior Earth Gravitational Comparison', 'hard', 'How far above Earth''s surface must an object be to feel the same gravity as when buried halfway to the center ($r = R_E/2$)?', '["$R_E/2$","$(\\sqrt{2} - 1)R_E$","$\\sqrt{2}R_E$","$2R_E$","$(\\sqrt{2} + 1)R_E$"]'::jsonb, '(B) Gravity inside Earth at $r = R_E/2$: $g_{\text{inside}} = g_0\left(\frac{R_E/2}{R_E}\right) = \frac{1}{2}g_0$.  
Gravity outside Earth at altitude $h$: $g_{\text{outside}} = g_0\left(\frac{R_E}{R_E + h}\right)^2$.
  $$\left(\frac{R_E}{R_E + h}\right)^2 = \frac{1}{2} \implies \frac{R_E + h}{R_E} = \sqrt{2} \implies h = (\sqrt{2} - 1)R_E$$'),
  ('ap-topic-physc-rotation_q1', 'ap-topic-physc-rotation', 1, false, 'B', 'Angular to Linear Speed on Rim', 'easy', 'A disc of radius $6\text{ cm}$ rotates at an angular speed of $5\text{ rev/s}$. What is the linear speed of a point on the rim?', '["$0.3\\text{ m/s}$","$1.9\\text{ m/s}$","$7.4\\text{ m/s}$","$52\\text{ m/s}$","$83\\text{ m/s}$"]'::jsonb, '(B) $$\omega = 5\text{ rev/s} \times 2\pi\text{ rad/rev} = 10\pi\text{ rad/s} \approx 31.42\text{ rad/s}$$
$$v = r\omega = (0.06\text{ m})(10\pi\text{ rad/s}) = 0.6\pi \approx 1.88\text{ m/s} \approx 1.9\text{ m/s}$$'),
  ('ap-topic-physc-rotation_q2', 'ap-topic-physc-rotation', 2, false, 'E', 'Rotational Arc Distance over Time', 'easy', 'For the same disc in Question 1, what is the total distance traveled by a point on the rim in $40\text{ min}$?', '["$180\\text{ m}$","$360\\text{ m}$","$540\\text{ m}$","$720\\text{ m}$","$4.5\\text{ km}$"]'::jsonb, '(E) $$t = 40\text{ min} \times 60\text{ s/min} = 2,400\text{ s}$$
$$s = vt = (0.6\pi\text{ m/s})(2400\text{ s}) = 1440\pi\text{ m} \approx 4,524\text{ m} \approx 4.5\text{ km}$$'),
  ('ap-topic-physc-rotation_q3', 'ap-topic-physc-rotation', 3, false, 'D', 'Constant Angular Acceleration Speed', 'easy', 'A disc starts from rest and undergoes angular acceleration of $4\text{ rad/s}^2$. At an angular displacement of $50\text{ rad}$, what is its angular speed?', '["$12\\text{ rad/s}$","$15\\text{ rad/s}$","$16\\text{ rad/s}$","$20\\text{ rad/s}$","$23\\text{ rad/s}$"]'::jsonb, '(D) $$\omega_f^2 = \omega_0^2 + 2\alpha\Delta\theta = 0 + 2(4\text{ rad/s}^2)(50\text{ rad}) = 400 \implies \omega_f = 20\text{ rad/s}$$'),
  ('ap-topic-physc-rotation_q4', 'ap-topic-physc-rotation', 4, false, 'D', 'Centripetal Acceleration in Circular Motion', 'medium', 'A rope of length $0.75\text{ m}$ has a mass $m = 0.1\text{ kg}$ spun at $120\text{ rpm}$. What centripetal acceleration is the mass experiencing?', '["$19,200\\text{ m/s}^2$","$10,800\\text{ m/s}^2$","$90\\text{ m/s}^2$","$12\\pi^2\\text{ m/s}^2$","$3\\pi\\text{ m/s}^2$"]'::jsonb, '(D) $$\omega = 120\text{ rpm} \times \frac{2\pi\text{ rad}}{60\text{ s}} = 4\pi\text{ rad/s}$$
$$a_c = \omega^2 r = (4\pi)^2 (0.75\text{ m}) = 16\pi^2(0.75) = 12\pi^2\text{ m/s}^2$$'),
  ('ap-topic-physc-rotation_q5', 'ap-topic-physc-rotation', 5, false, 'B', 'Seesaw Torque Balance & Net Torque', 'easy', 'Joe ($60\text{ kg}$) and Alice ($30\text{ kg}$) sit on opposite ends of a level $4\text{-m}$ seesaw supported at its midpoint. What is the net torque magnitude ($g = 10\text{ m/s}^2$)?', '["$300\\text{ N}\\cdot\\text{m}$","$600\\text{ N}\\cdot\\text{m}$","$900\\text{ N}\\cdot\\text{m}$","$1,200\\text{ N}\\cdot\\text{m}$","$1,500\\text{ N}\\cdot\\text{m}$"]'::jsonb, '(B) Lever arm from fulcrum to each end: $r = 2\text{ m}$.
  $$\tau_{\text{net}} = (m_{\text{Joe}} g)r - (m_{\text{Alice}} g)r = (60)(10)(2) - (30)(10)(2) = 1200 - 600 = 600\text{ N}\cdot\text{m}$$'),
  ('ap-topic-physc-rotation_q6', 'ap-topic-physc-rotation', 6, false, 'D', 'Pendulum Gravitational Torque', 'medium', 'What is the torque about a pendulum suspension point produced by a bob ($m = 0.50\text{ kg}$) at length $L = 0.80\text{ m}$ at angle $\theta = 30^\circ$ ($g = 10\text{ m/s}^2$)?', '["$0.5\\text{ N}\\cdot\\text{m}$","$1.0\\text{ N}\\cdot\\text{m}$","$1.7\\text{ N}\\cdot\\text{m}$","$2.0\\text{ N}\\cdot\\text{m}$","$3.4\\text{ N}\\cdot\\text{m}$"]'::jsonb, '(D) $$\tau = mg L \sin\theta = (0.50\text{ kg})(10\text{ m/s}^2)(0.80\text{ m})\sin(30^\circ) = 4.0(0.5) = 2.0\text{ N}\cdot\text{m}$$'),
  ('ap-topic-physc-rotation_q7', 'ap-topic-physc-rotation', 7, false, 'B', 'Meter Stick Fulcrum Static Equilibrium', 'medium', 'A uniform meter stick of mass $1\text{ kg}$ is supported at its $50\text{ cm}$ midpoint. A mass $m = 3\text{ kg}$ hangs at $x = 0\text{ cm}$. At what mass $M$ hanging at $x = 80\text{ cm}$ will the stick remain horizontal?', '["$3\\text{ kg}$","$5\\text{ kg}$","$6\\text{ kg}$","$8\\text{ kg}$","$9\\text{ kg}$"]'::jsonb, '(B) Torque balance about the $50\text{ cm}$ fulcrum:
$$m(50\text{ cm} - 0\text{ cm}) = M(80\text{ cm} - 50\text{ cm}) \implies (3\text{ kg})(50\text{ cm}) = M(30\text{ cm})$$
$$M = \frac{150}{30} = 5\text{ kg}$$'),
  ('ap-topic-physc-rotation_q8', 'ap-topic-physc-rotation', 8, false, 'A', 'Discrete Point Mass Rotational Inertia', 'easy', 'Four point masses $m$ are located at the vertices of a rectangle of side lengths $L$ and $3L$. What is the rotational inertia about an axis passing through the center perpendicular to the plane, where each mass is at distance $L$ from the axis?', '["$4mL^2$","$\\frac{8}{3}mL^2$","$\\frac{5}{2}mL^2$","$\\frac{7}{3}mL^2$","$\\frac{10}{3}mL^2$"]'::jsonb, '(A) $$I = \sum m_i r_i^2 = 4(m L^2) = 4mL^2$$')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-physc-rotation_q9', 'ap-topic-physc-rotation', 9, false, 'C', 'Rolling vs Sliding Kinetic Energy Comparison', 'medium', 'A block of mass $m$ slides down a frictionless incline of height $h$. A solid cylinder of mass $m$ rolls down an incline of height $H$ without slipping. If both reach the bottom with equal kinetic energies, what is the relation between $h$ and $H$?', '["$h = \\frac{4}{3}H$","$h = \\frac{3}{4}H$","$h = H$","$h = \\frac{1}{2}H$","$h = 2H$"]'::jsonb, '(C) For the block, $K_{\text{bottom}} = mgh$. For the rolling cylinder, total kinetic energy (translational + rotational) equals potential energy lost: $K_{\text{bottom}} = mgH$. For equal kinetic energies, $mgh = mgH \implies h = H$.'),
  ('ap-topic-physc-rotation_q10', 'ap-topic-physc-rotation', 10, false, 'D', 'Static Friction Torque in Rolling Motion', 'easy', 'When a cylinder rolls down an incline without slipping, which force produces the torque causing angular rotation?', '["Parallel component of gravity","Perpendicular component of gravity","Normal force","Force of static friction","Force of kinetic friction"]'::jsonb, '(D) Gravity acts at the center of mass ($r = 0$), and the normal force passes directly through the center of mass ($\vec{r} \parallel \vec{F}_N \implies \tau = 0$). Static friction acts tangentially at the contact point without slipping, exerting torque $\tau = f_s R$.'),
  ('ap-topic-physc-shm_q1', 'ap-topic-physc-shm', 1, false, 'D', 'Simple Harmonic Motion Characteristics', 'easy', 'Which of the following are characteristics of simple harmonic motion?  I. Acceleration is constant.  II. Restoring force is proportional to displacement.  III. Frequency is independent of amplitude.', '["II only","I and II only","I and III only","II and III only","I, II, and III"]'::jsonb, '(D) In SHM, acceleration $a(x) = -\omega^2 x$ varies with displacement, so I is false. By Hooke''s Law, $F = -kx$ (II is true), and angular frequency $\omega = \sqrt{k/m}$ does not depend on amplitude $A$ (III is true).'),
  ('ap-topic-physc-shm_q2', 'ap-topic-physc-shm', 2, false, 'B', 'Mass-Spring Oscillator Frequency Maximization', 'easy', 'What combination of parameters maximizes the oscillation frequency of a mass-spring oscillator?', '["Large $m$, small $k$","Small $m$, large $k$","Large amplitude, large $m$","Small amplitude, small $k$","Large amplitude, small $k$"]'::jsonb, '(B) $$f = \frac{1}{2\pi}\sqrt{\frac{k}{m}}$$
Frequency is maximized by choosing the largest spring constant $k$ and the smallest mass $m$, and is independent of amplitude.'),
  ('ap-topic-physc-shm_q3', 'ap-topic-physc-shm', 3, false, 'B', 'Simple Pendulum Maximum Speed', 'easy', 'A simple pendulum of length $L$ is pulled to initial position and released from rest, dropping vertical height $h$ to equilibrium. What is its maximum speed at the bottom?', '["$gh$","$\\sqrt{2gh}$","$\\sqrt{2gd}$","$\\sqrt{2gL}$","$2gh$"]'::jsonb, '(B) By conservation of mechanical energy:
$$mgh = \frac{1}{2}mv_{\max}^2 \implies v_{\max} = \sqrt{2gh}$$'),
  ('ap-topic-physc-shm_q4', 'ap-topic-physc-shm', 4, false, 'C', 'Oscillator Mass Scaling & Max Speed', 'medium', 'In a spring-mass oscillator, if mass is doubled while keeping oscillation amplitude $A$ constant, the maximum speed will:', '["decrease by a factor of 4","decrease by a factor of 2","decrease by a factor of $\\sqrt{2}$","remain the same","increase by a factor of 2"]'::jsonb, '(C) $$v_{\max} = \omega A = \sqrt{\frac{k}{m}}A \propto \frac{1}{\sqrt{m}}$$
Doubling the mass scales maximum speed by $\frac{1}{\sqrt{2}}$.'),
  ('ap-topic-physc-shm_q5', 'ap-topic-physc-shm', 5, false, 'E', 'Vertical Hanging Spring Total Length', 'medium', 'A vertical spring ($L_0 = 40\text{ cm}, k = 400\text{ N/m}$) hangs with mass $m = 10\text{ kg}$. What is the total equilibrium length of the spring ($g = 10\text{ m/s}^2$)?', '["$25\\text{ cm}$","$35\\text{ cm}$","$40\\text{ cm}$","$50\\text{ cm}$","$65\\text{ cm}$"]'::jsonb, '(E) Extension at equilibrium:
$$x = \frac{mg}{k} = \frac{(10\text{ kg})(10\text{ m/s}^2)}{400\text{ N/m}} = 0.25\text{ m} = 25\text{ cm}$$
Total length: $L = L_0 + x = 40\text{ cm} + 25\text{ cm} = 65\text{ cm}$.'),
  ('ap-topic-physc-mech-drills_q1', 'ap-topic-physc-mech-drills', 1, false, 'A', 'Uniform Circular Motion & Kinematics', 'easy', 'An object that''s moving with constant speed travels once around a circular path. Which of the following is/are true concerning this motion?  I. The displacement is zero.  II. The average speed is zero.  III. The acceleration is zero.', '["I only","I and II only","I and III only","III only","II and III only"]'::jsonb, '(A) Because the particle starts and finishes at the exact same location, its net position displacement is zero ($\Delta \vec{r} = 0$), making statement I true. Average speed is total distance over time, which is strictly greater than zero (II is false). Uniform circular motion features a continuous change in velocity direction, requiring a nonzero centripetal acceleration directed toward the center ($a_c = v^2/r \ne 0$) (III is false).'),
  ('ap-topic-physc-mech-drills_q2', 'ap-topic-physc-mech-drills', 2, false, 'C', 'Average Acceleration Vector Sum', 'medium', 'At time $t = t_1$, an object''s velocity is $\vec{v}_1$. A short time later, at $t = t_2$, its velocity is $\vec{v}_2$. If $|\vec{v}_1| = |\vec{v}_2|$, which vector best illustrates the average acceleration $\vec{a}_{\text{avg}}$ between $t_1$ and $t_2$?', '["Vector pointing along $\\vec{v}_1$","Vector pointing along $\\vec{v}_2$","Vector pointing downward and to the left (along $\\vec{v}_2 - \\vec{v}_1$)","Vector pointing upward","Zero vector"]'::jsonb, '(C) Average acceleration is defined by $\vec{a}_{\text{avg}} = \frac{\Delta\vec{v}}{\Delta t} = \frac{\vec{v}_2 - \vec{v}_1}{\Delta t} = \frac{\vec{v}_2 + (-\vec{v}_1)}{\Delta t}$. Vector addition of $\vec{v}_2$ and the inverted vector $-\vec{v}_1$ yields a resultant vector directed downward and to the left.'),
  ('ap-topic-physc-mech-drills_q3', 'ap-topic-physc-mech-drills', 3, false, 'C', '2D Projectile Acceleration', 'easy', 'A rock is thrown off a $30\text{-m}$ cliff at a $45^\circ$ angle above the horizontal. Which of the following is true regarding the acceleration of the rock? (Ignore air resistance)', '["The acceleration will have both horizontal and vertical components.","At the peak, acceleration is half of its initial launch value.","The acceleration will be of magnitude $g$ and in a downward direction.","The acceleration is downward on ascent and upward on descent.","The acceleration increases throughout the flight."]'::jsonb, '(C) Once in free-fall ballistic flight under negligible air resistance, the only force acting on the projectile is gravity ($F_g = mg$, downward). The acceleration is uniformly constant everywhere along the trajectory: $\vec{a} = -g\hat{j}$.'),
  ('ap-topic-physc-mech-drills_q4', 'ap-topic-physc-mech-drills', 4, false, 'C', 'Vertical Free Fall Acceleration at Apex', 'easy', 'A baseball is thrown straight upward. What is the ball''s acceleration at its highest point?', '["$0$","$-g$, downward","$g$, downward","$-g$, upward","$g$, upward"]'::jsonb, '(C) Even though the instantaneous velocity of the ball is zero at the apex of its path, the gravitational force continues to act on the ball without interruption, producing a constant downward acceleration of magnitude $g$.'),
  ('ap-topic-physc-mech-drills_q5', 'ap-topic-physc-mech-drills', 5, false, 'C', 'Calculus Kinematics & Max Velocity', 'medium', 'An object''s position is given by $x(t) = -3t^3 + t^2 + 6t$. What is the maximum velocity of the object?', '["$0.11\\text{ m/s}$","$2.73\\text{ m/s}$","$6.11\\text{ m/s}$","$7.39\\text{ m/s}$","$9.81\\text{ m/s}$"]'::jsonb, '(C) Velocity function:
  $$v(t) = \frac{dx}{dt} = -9t^2 + 2t + 6$$
To find the maximum velocity, set the derivative of velocity (acceleration) equal to zero:
  $$\frac{dv}{dt} = -18t + 2 = 0 \implies t = \frac{1}{9}\text{ s} \approx 0.111\text{ s}$$
Evaluate $v(t)$ at $t = 1/9\text{ s}$:
  $$v_{\max} = -9\left(\frac{1}{9}\right)^2 + 2\left(\frac{1}{9}\right) + 6 = -\frac{1}{9} + \frac{2}{9} + 6 = 6 + \frac{1}{9} \approx 6.11\text{ m/s}$$'),
  ('ap-topic-physc-mech-drills_q6', 'ap-topic-physc-mech-drills', 6, false, 'D', 'Free Fall Drop Height Calculation', 'easy', 'A rock dropped off a cliff strikes the ground with an impact speed of $30\text{ m/s}$. How high was the cliff? ($g = 10\text{ m/s}^2$)', '["$15\\text{ m}$","$20\\text{ m}$","$30\\text{ m}$","$45\\text{ m}$","$60\\text{ m}$"]'::jsonb, '(D) Using the kinematic equation $v_f^2 = v_0^2 + 2g\Delta y$ with $v_0 = 0$:
  $$\Delta y = \frac{v_f^2}{2g} = \frac{(30\text{ m/s})^2}{2(10\text{ m/s}^2)} = \frac{900}{20} = 45\text{ m}$$'),
  ('ap-topic-physc-mech-drills_q7', 'ap-topic-physc-mech-drills', 7, false, 'C', 'Horizontal Projectile Flight Time', 'easy', 'A stone is thrown horizontally with an initial speed of $10\text{ m/s}$ from a bridge. How long would it take to strike the water $80\text{ m}$ below the bridge? ($g = 10\text{ m/s}^2$)', '["$1\\text{ s}$","$2\\text{ s}$","$4\\text{ s}$","$8\\text{ s}$","$16\\text{ s}$"]'::jsonb, '(C) Vertical and horizontal motions are independent. With $v_{0y} = 0$:
  $$h = \frac{1}{2}gt^2 \implies t = \sqrt{\frac{2h}{g}} = \sqrt{\frac{2(80\text{ m})}{10\text{ m/s}^2}} = \sqrt{16} = 4\text{ s}$$'),
  ('ap-topic-physc-mech-drills_q8', 'ap-topic-physc-mech-drills', 8, false, 'B', 'Angled Projectile Total Hang Time', 'easy', 'A soccer ball at rest is kicked with initial velocity $10\text{ m/s}$ at launch angle $30^\circ$. Calculate its total flight time over level ground ($g = 10\text{ m/s}^2$).', '["$0.5\\text{ s}$","$1.0\\text{ s}$","$1.7\\text{ s}$","$2.0\\text{ s}$","$2.5\\text{ s}$"]'::jsonb, '(B) $$v_{0y} = v_0\sin(30^\circ) = 10(0.5) = 5\text{ m/s}$$
$$T = \frac{2v_{0y}}{g} = \frac{2(5\text{ m/s})}{10\text{ m/s}^2} = 1.0\text{ s}$$'),
  ('ap-topic-physc-mech-drills_q9', 'ap-topic-physc-mech-drills', 9, false, 'C', '2D Projectile Impact Speed', 'medium', 'A stone is thrown horizontally with initial speed $30\text{ m/s}$ from a bridge. Find the stone''s total speed when it enters the water $4\text{ s}$ later ($g = 10\text{ m/s}^2$).', '["$30\\text{ m/s}$","$40\\text{ m/s}$","$50\\text{ m/s}$","$60\\text{ m/s}$","$70\\text{ m/s}$"]'::jsonb, '(C) Horizontal velocity: $v_x = 30\text{ m/s}$ (constant).  
Vertical velocity: $v_y = gt = (10\text{ m/s}^2)(4\text{ s}) = 40\text{ m/s}$.  
Magnitude: $v = \sqrt{v_x^2 + v_y^2} = \sqrt{30^2 + 40^2} = 50\text{ m/s}$.'),
  ('ap-topic-physc-mech-drills_q10', 'ap-topic-physc-mech-drills', 10, false, 'E', 'Projectile Motion Vertical vs Horizontal Velocity', 'easy', 'Which statement is true concerning the motion of an ideal projectile launched at $45^\circ$?', '["The acceleration vector points opposite to velocity on ascent and along velocity on descent.","The speed at the top of the trajectory is zero.","Total speed remains constant throughout.","Horizontal speed decreases ascending and increases descending.","Vertical speed decreases on the way up and increases on the way down."]'::jsonb, '(E) Because the downward gravitational acceleration opposes upward vertical velocity during ascent, vertical speed $|v_y|$ decreases to zero at the apex, then increases continuously as the projectile falls. Horizontal speed remains strictly constant throughout.'),
  ('ap-topic-physc-mech-drills_q11', 'ap-topic-physc-mech-drills', 11, false, 'A', 'Trajectory Equation & Wall Clearance Angle', 'hard', 'An object is launched from the ground with speed $v$ at distance $d$ away from a wall of height $h$. Which equation gives the launch angle $\theta$ to just clear the wall?', '["$h = d\\tan\\theta - \\frac{gd^2}{2v^2\\cos^2\\theta}$","$h = d^2\\cos\\theta - \\frac{gd^2}{2v^2\\cos^2\\theta}$","$h = d\\tan\\theta - \\frac{gd^2}{2v\\cos\\theta}$","$h = d\\sin\\theta - \\frac{gd^2}{v^2\\cos^2\\theta}$","$h = d\\sin\\theta - \\frac{gd^2}{2v\\cos\\theta}$"]'::jsonb, '(A) Horizontal time to reach the wall: $t = \frac{d}{v\cos\theta}$.
Substituting into vertical position $y(t) = (v\sin\theta)t - \frac{1}{2}gt^2$:
  $$h = (v\sin\theta)\left(\frac{d}{v\cos\theta}\right) - \frac{1}{2}g\left(\frac{d}{v\cos\theta}\right)^2 = d\tan\theta - \frac{gd^2}{2v^2\cos^2\theta}$$'),
  ('ap-topic-physc-mech-drills_q12', 'ap-topic-physc-mech-drills', 12, false, 'D', 'Velocity-Time Graph & Position Integral', 'medium', 'An object moves in a straight line with a given velocity-time graph. If $x = 3.0\text{ m}$ at $t = 0$, what is the position at $t = 3.0\text{ s}$ if the area under the $v\text{--}t$ curve from $0$ to $3\text{ s}$ is $8\text{ m}$?', '["$5\\text{ m}$","$8\\text{ m}$","$10\\text{ m}$","$11\\text{ m}$","$14\\text{ m}$"]'::jsonb, '(D) Displacement is the definite integral of velocity: $\Delta x = \int_0^3 v(t)\,dt = 8\text{ m}$.
  $$x(3) = x(0) + \Delta x = 3.0\text{ m} + 8\text{ m} = 11\text{ m}$$'),
  ('ap-topic-physc-mech-drills_q13', 'ap-topic-physc-mech-drills', 13, false, 'E', 'Newton''s Third Law Action-Reaction Pairs', 'easy', 'A box is dragged across a table at constant velocity by a string. Which of the following is a Newton''s Third Law action-reaction pair?  I. Force of gravity on the box and normal force on the box  II. Force of friction on the box and tension force on the box  III. Force of the box pushing down on the table and normal force of the table pushing up on the box', '["I only","I and II only","II only","I and III only","III only"]'::jsonb, '(E) An action-reaction pair must involve mutual forces of the same physical type exerted between the same two objects in opposite directions. The table pushing up on the box ($F_{N,\text{table on box}}$) and the box pushing down on the table ($F_{N,\text{box on table}}$) act on each other, satisfying Newton''s Third Law.'),
  ('ap-topic-physc-mech-drills_q14', 'ap-topic-physc-mech-drills', 14, false, 'D', 'Apparent Weight in Accelerating Elevator', 'easy', 'A person who weighs $800\text{ N}$ steps onto a scale in an elevator accelerating upward at $5\text{ m/s}^2$. What will the scale read? ($g = 10\text{ m/s}^2$)', '["$400\\text{ N}$","$800\\text{ N}$","$1,000\\text{ N}$","$1,200\\text{ N}$","$1,600\\text{ N}$"]'::jsonb, '(D) Mass $m = \frac{W}{g} = \frac{800\text{ N}}{10\text{ m/s}^2} = 80\text{ kg}$.
Using Newton''s Second Law with upward as positive:
  $$F_N - mg = ma \implies F_N = m(g + a) = (80\text{ kg})(10 + 5\text{ m/s}^2) = 1,200\text{ N}$$'),
  ('ap-topic-physc-mech-drills_q15', 'ap-topic-physc-mech-drills', 15, false, 'D', 'Two-Block System Tension & Acceleration', 'medium', 'A horizontal force of $20\text{ N}$ pulls on a $1.0\text{ kg}$ block attached by a string to a $2.0\text{ kg}$ block on a frictionless surface. Find the tension $F_T$ in the connecting string and the acceleration $a$ of the system.', '["$F_T = 13.3\\text{ N},\\ a = 10\\text{ m/s}^2$","$F_T = 13.3\\text{ N},\\ a = 20\\text{ m/s}^2$","$F_T = 15\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_T = 13.3\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_T = 20\\text{ N},\\ a = 6.7\\text{ m/s}^2$"]'::jsonb, '(D) System acceleration:
  $$a = \frac{F_{\text{applied}}}{m_1 + m_2} = \frac{20\text{ N}}{1.0 + 2.0\text{ kg}} = \frac{20}{3}\text{ m/s}^2 \approx 6.7\text{ m/s}^2$$
Tension pulling the trailing $2.0\text{ kg}$ block:
  $$F_T = m_2 a = (2.0\text{ kg})\left(\frac{20}{3}\text{ m/s}^2\right) = \frac{40}{3}\text{ N} \approx 13.3\text{ N}$$'),
  ('ap-topic-physc-mech-drills_q16', 'ap-topic-physc-mech-drills', 16, false, 'C', 'Three-Block Frictionless Train Tensions', 'medium', 'A force of $20\text{ N}$ pulls a chain of three frictionless blocks: $3.0\text{ kg} - 2.0\text{ kg} - 1.0\text{ kg}$. Find $F_{T1}$ (between $1\text{ kg}$ and $2\text{ kg}$), $F_{T2}$ (between $2\text{ kg}$ and $3\text{ kg}$), and acceleration $a$.', '["$F_{T1} = 1\\text{ N},\\ a = 1\\text{ m/s}^2$","$F_{T1} = 3.3\\text{ N},\\ F_{T2} = 3.3\\text{ N},\\ a = 3.3\\text{ m/s}^2$","$F_{T1} = 3.3\\text{ N},\\ F_{T2} = 10\\text{ N},\\ a = 3.3\\text{ m/s}^2$","$F_{T1} = 3.3\\text{ N},\\ F_{T2} = 10\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_{T1} = 10\\text{ N},\\ a = 6.7\\text{ m/s}^2$"]'::jsonb, '(C) $$a = \frac{20\text{ N}}{1.0 + 2.0 + 3.0\text{ kg}} = \frac{20}{6}\text{ m/s}^2 = 3.33\text{ m/s}^2$$
$$F_{T1} = m_1 a = (1.0\text{ kg})(3.33\text{ m/s}^2) = 3.33\text{ N}$$
$$F_{T2} = (m_1 + m_2)a = (1.0 + 2.0\text{ kg})(3.33\text{ m/s}^2) = 10.0\text{ N}$$'),
  ('ap-topic-physc-mech-drills_q17', 'ap-topic-physc-mech-drills', 17, false, 'A', 'Incline Static Friction Threshold', 'medium', 'A box is placed at rest on a ramp ($\theta = 30^\circ, \mu_s = 0.5$). The box will:', '["Accelerate down the ramp","Accelerate briefly then stop","Move with constant velocity","Not move","Cannot be determined"]'::jsonb, '(A) Downhill gravitational component: $F_{g,\parallel} = mg\sin(30^\circ) = 0.50\,mg$.
Maximum static friction force:
  $$f_{s,\max} = \mu_s mg\cos(30^\circ) = (0.5)(0.866\,mg) \approx 0.433\,mg$$
Because $F_{g,\parallel} > f_{s,\max}$ ($0.50\,mg > 0.433\,mg$), the net force down the ramp is positive, and the box will accelerate down.'),
  ('ap-topic-physc-mech-drills_q18', 'ap-topic-physc-mech-drills', 18, false, 'C', 'Atwood Machine System Acceleration', 'easy', 'In an Atwood machine with hanging masses $m$ and $4m$, find the acceleration.', '["$0.2g$","$0.4g$","$0.6g$","$0.75g$","$0.8g$"]'::jsonb, '(C) $$a = \frac{m_2 - m_1}{m_1 + m_2}g = \frac{4m - m}{4m + m}g = \frac{3}{5}g = 0.6g$$'),
  ('ap-topic-physc-mech-drills_q19', 'ap-topic-physc-mech-drills', 19, false, 'E', 'Two-Block System with Kinetic Friction', 'medium', 'A $20\text{ N}$ force pulls a $2.0\text{ kg}$ block connected to a $1.0\text{ kg}$ trailing block on a rough surface ($\mu_k = 0.2$). Find the tension $F_T$ and acceleration $a$ ($g = 10\text{ m/s}^2$).', '["$F_T = 1\\text{ N},\\ a = 4.7\\text{ m/s}^2$","$F_T = 3.3\\text{ N},\\ a = 4.7\\text{ m/s}^2$","$F_T = 3.3\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_T = 6.7\\text{ N},\\ a = 6.7\\text{ m/s}^2$","$F_T = 6.7\\text{ N},\\ a = 4.7\\text{ m/s}^2$"]'::jsonb, '(E) Total friction force: $f_{\text{total}} = \mu_k(m_1 + m_2)g = (0.2)(3.0\text{ kg})(10\text{ m/s}^2) = 6\text{ N}$.
Acceleration: $a = \frac{F - f_{\text{total}}}{m_1 + m_2} = \frac{20 - 6}{3} = \frac{14}{3} \approx 4.7\text{ m/s}^2$.
Tension on the $1.0\text{ kg}$ trailing block:
  $$F_T - f_1 = m_1 a \implies F_T = (0.2)(1.0)(10) + (1.0)(4.7) = 2.0 + 4.7 = 6.7\text{ N}$$'),
  ('ap-topic-physc-mech-drills_q20', 'ap-topic-physc-mech-drills', 20, false, 'B', 'Incline Gravitational Scaling', 'easy', 'An object slides down a frictionless incline of angle $\theta$ and reaches final speed $v$. On a planet with twice Earth''s gravitational acceleration ($2g$), what will be its final speed?', '["$v$","$\\sqrt{2}v$","$2v$","$4v$","$v/2$"]'::jsonb, '(B) Using $v = \sqrt{2ad} = \sqrt{2(g\sin\theta)d} \propto \sqrt{g}$. Doubling $g$ scales the final velocity by a factor of $\sqrt{2}$, giving $v_{\text{new}} = \sqrt{2}v$.'),
  ('ap-topic-physc-mech-drills_q21', 'ap-topic-physc-mech-drills', 21, false, 'B', 'Vertical Loop Minimum Cut-Off Speed', 'medium', 'A roller coaster completes a loop of radius $r = 25\text{ m}$. What is the minimum speed needed at the top of the loop for riders to remain safely in contact with the track? ($g = 10\text{ m/s}^2$)', '["$12.7\\text{ m/s}$","$15.8\\text{ m/s}$","$21.2\\text{ m/s}$","$29.3\\text{ m/s}$","$33.3\\text{ m/s}$"]'::jsonb, '(B) At critical cut-off speed, normal force $F_N \to 0$, so gravity alone provides the centripetal acceleration:
  $$\frac{mv^2}{r} = mg \implies v = \sqrt{gr} = \sqrt{(10\text{ m/s}^2)(25\text{ m})} = \sqrt{250} \approx 15.8\text{ m/s}$$'),
  ('ap-topic-physc-mech-drills_q22', 'ap-topic-physc-mech-drills', 22, false, 'B', 'Vertical Circular Motion Bottom Tension', 'medium', 'A bucket of mass $3\text{ kg}$ on a $0.6\text{-m}$ rope is whirled in a vertical circle. At the lowest point, the tension is $50\text{ N}$. What is the speed of the bucket? ($g = 10\text{ m/s}^2$)', '["$1\\text{ m/s}$","$2\\text{ m/s}$","$3\\text{ m/s}$","$4\\text{ m/s}$","$5\\text{ m/s}$"]'::jsonb, '(B) At the bottom of the circle: $F_T - mg = \frac{mv^2}{r}$.
  $$50\text{ N} - (3\text{ kg})(10\text{ m/s}^2) = \frac{3 v^2}{0.6} \implies 20 = 5v^2 \implies v^2 = 4 \implies v = 2\text{ m/s}$$'),
  ('ap-topic-physc-mech-drills_q23', 'ap-topic-physc-mech-drills', 23, false, 'C', 'Vertical String Circle Critical Apex Speed', 'medium', 'What is the critical speed at the top of the vertical circle for the bucket in Question 10 so the rope does not become slack?', '["$0.6\\text{ m/s}$","$1.8\\text{ m/s}$","$2.4\\text{ m/s}$","$3.2\\text{ m/s}$","$4.8\\text{ m/s}$"]'::jsonb, '(C) $$v_{\text{critical}} = \sqrt{gr} = \sqrt{(10\text{ m/s}^2)(0.60\text{ m})} = \sqrt{6.0} \approx 2.45\text{ m/s} \approx 2.4\text{ m/s}$$'),
  ('ap-topic-physc-mech-drills_q24', 'ap-topic-physc-mech-drills', 24, false, 'D', 'Centripetal Acceleration & Angular Frequency', 'easy', 'An object moves at constant speed in a circular path of radius $r$ at 1 revolution per second. What is its centripetal acceleration?', '["$2\\pi r$","$2\\pi^2 r$","$2\\pi^2 r^2$","$4\\pi^2 r$","$4\\pi^2 r^2$"]'::jsonb, '(D) With angular frequency $\omega = 2\pi f = 2\pi(1) = 2\pi\text{ rad/s}$:
  $$a_c = \omega^2 r = (2\pi)^2 r = 4\pi^2 r$$'),
  ('ap-topic-physc-mech-drills_q25', 'ap-topic-physc-mech-drills', 25, false, 'A', 'Perpendicular Force & Zero Work', 'easy', 'A force $F = 20\text{ N}$ acts on a $3\text{ kg}$ object as it moves $4\text{ m}$. If $F$ is perpendicular to displacement, the work done is:', '["$0\\text{ J}$","$60\\text{ J}$","$80\\text{ J}$","$600\\text{ J}$","$2,400\\text{ J}$"]'::jsonb, '(A) $W = \vec{F}\cdot\vec{d} = F d \cos(90^\circ) = 0\text{ J}$. Any force acting strictly perpendicular to displacement performs zero work.'),
  ('ap-topic-physc-mech-drills_q26', 'ap-topic-physc-mech-drills', 26, false, 'B', 'Work-Energy Theorem & Kinetic Energy Change', 'easy', 'An object of mass $4\text{ kg}$ accelerates from $3\text{ m/s}$ to $6\text{ m/s}$ in $8\text{ s}$. How much work was done on the object?', '["$27\\text{ J}$","$54\\text{ J}$","$72\\text{ J}$","$96\\text{ J}$","Cannot be determined"]'::jsonb, '(B) By the Work-Energy Theorem ($W = \Delta K$):
  $$W = \frac{1}{2}m(v_f^2 - v_i^2) = \frac{1}{2}(4\text{ kg})((6\text{ m/s})^2 - (3\text{ m/s})^2) = 2(36 - 9) = 2(27) = 54\text{ J}$$'),
  ('ap-topic-physc-mech-drills_q27', 'ap-topic-physc-mech-drills', 27, false, 'D', 'Path Independence & Conservative Gravitational Work', 'easy', 'To lift a box of mass $m$ to height $h$, three options are considered: Option 1 (direct lift), Option 2 ($30^\circ$ incline), Option 3 (pulley system). Compare the work done under ideal conditions.', '["Option 1 > Option 2 > Option 3","Option 1 > Option 2 = Option 3","Option 1 = Option 3 > Option 2","Option 1 = Option 2 = Option 3","Cannot be determined"]'::jsonb, '(D) Under ideal conservative conditions, gravitational potential energy is path-independent. In all three methods, the minimum work required is identical: $W = mgh$.'),
  ('ap-topic-physc-mech-drills_q28', 'ap-topic-physc-mech-drills', 28, false, 'E', 'Normal Force Zero Work on Incline', 'easy', 'A $4\text{ kg}$ box is pulled up a ramp ($\theta = 30^\circ$, height $= 5\text{ m}$) at constant velocity. How much work is done by the normal force?', '["$160\\text{ J}$","$80\\text{ J}$","$40\\text{ J}$","$20\\text{ J}$","$0\\text{ J}$"]'::jsonb, '(E) The normal force is perpendicular to the ramp surface and therefore perpendicular to the displacement vector of the box ($\theta = 90^\circ$). Thus $W_N = F_N d \cos(90^\circ) = 0\text{ J}$.'),
  ('ap-topic-physc-mech-drills_q29', 'ap-topic-physc-mech-drills', 29, false, 'A', 'Elevator Normal Force Positive Work', 'easy', 'A man stands in an elevator as it begins to ascend. Does the normal force from the floor do work on the man?', '["Yes, and the work done will be positive.","Yes, and the work done will be negative.","Yes, but the sign cannot be determined.","No, the normal force does no work in any situation.","No, normal force does no work here."]'::jsonb, '(A) The normal force pushes upward on the man''s feet ($\vec{F}_N$ is upward) and the elevator displacement is upward ($\vec{d}$ is upward). Because $\vec{F}_N$ and $\vec{d}$ point in the same direction ($\theta = 0^\circ$), $W = F_N d \cos(0^\circ) > 0$ (positive work).'),
  ('ap-topic-physc-mech-drills_q30', 'ap-topic-physc-mech-drills', 30, false, 'D', 'Frictionless Incline Energy Conservation', 'medium', 'A $3.5\text{ kg}$ block slides from rest down a frictionless $30^\circ$ incline of length $6.4\text{ m}$. What is its speed at the bottom? ($g = 10\text{ m/s}^2$)', '["$5.0\\text{ m/s}$","$5.7\\text{ m/s}$","$6.4\\text{ m/s}$","$8.0\\text{ m/s}$","$10\\text{ m/s}$"]'::jsonb, '(D) Vertical height of the incline: $h = L\sin(30^\circ) = 6.4(0.5) = 3.2\text{ m}$.
By Conservation of Energy:
  $$mgh = \frac{1}{2}mv^2 \implies v = \sqrt{2gh} = \sqrt{2(10)(3.2)} = \sqrt{64} = 8.0\text{ m/s}$$'),
  ('ap-topic-physc-mech-drills_q31', 'ap-topic-physc-mech-drills', 31, false, 'D', 'Incline Kinetic Energy with Friction Work', 'medium', 'A block of mass $m$ slides from rest down an incline of length $s$ and height $h$ with kinetic friction force $F_f$. What is the kinetic energy at the bottom?', '["$mgh$","$mgh - F_f h$","$mgs - F_f h$","$mgh - F_f s$","$mgs - F_f s$"]'::jsonb, '(D) Applying the Work-Energy Theorem ($E_i + W_{\text{other}} = E_f$):
  $$mgh - F_f s = K_f \implies K_f = mgh - F_f s$$'),
  ('ap-topic-physc-mech-drills_q32', 'ap-topic-physc-mech-drills', 32, false, 'C', 'Newton''s Second Law with Aerodynamic Drag', 'easy', 'A $1,000\text{ kg}$ car accelerates at $4\text{ m/s}^2$ while experiencing $300\text{ N}$ of drag force. How much force must the engine produce?', '["$16,300\\text{ N}$","$15,700\\text{ N}$","$4,300\\text{ N}$","$4,000\\text{ N}$","$3,700\\text{ N}$"]'::jsonb, '(C) $$F_{\text{engine}} - F_{\text{drag}} = ma \implies F_{\text{engine}} = ma + F_{\text{drag}} = (1,000\text{ kg})(4\text{ m/s}^2) + 300\text{ N} = 4,300\text{ N}$$'),
  ('ap-topic-physc-mech-drills_q33', 'ap-topic-physc-mech-drills', 33, false, 'E', 'Gravitational Free Fall Midpoint Speed Fraction', 'medium', 'An astronaut drops a rock from the top of a crater. When the rock is halfway down to the bottom, its speed is what fraction of its impact speed?', '["$1/4$","$1/2$","$1/\\sqrt{3}$","$\\sqrt{2}/3$","$1/\\sqrt{2}$"]'::jsonb, '(E) At halfway point $h/2$, kinetic energy is half the final kinetic energy: $K_{\text{mid}} = \frac{1}{2}K_{\text{final}}$.
  $$\frac{1}{2}mv_{\text{mid}}^2 = \frac{1}{2}\left(\frac{1}{2}mv_{\text{final}}^2\right) \implies v_{\text{mid}} = \frac{1}{\sqrt{2}}v_{\text{final}}$$'),
  ('ap-topic-physc-mech-drills_q34', 'ap-topic-physc-mech-drills', 34, false, 'D', 'Incline Constant Power Mechanical Derivation', 'hard', 'A block of mass $m$ is pulled up a ramp of length $d$, angle $\theta$, and friction coefficient $\mu$ by a motor at constant power in time $t$. What is the minimum power $P$?', '["$\\frac{md^2}{t^3} + \\frac{mgd\\sin\\theta}{t}$","$\\frac{md^2}{t^2} + mgd\\sin\\theta + \\mu mgd\\cos\\theta$","$\\frac{md^2}{t^3} + \\frac{mgd\\sin\\theta}{t} + \\frac{\\mu mgd\\cos\\theta}{t}$","$\\frac{2md^2}{t^3} + \\frac{mgd\\sin\\theta}{t} + \\frac{\\mu mgd\\cos\\theta}{t}$","$\\frac{md^2}{2t^3} + \\frac{mgd\\cos\\theta}{t} + \\frac{\\mu mgd\\sin\\theta}{t}$"]'::jsonb, '(D) Under constant acceleration to cover distance $d$ in time $t$, $d = \frac{1}{2}at^2 \implies a = \frac{2d}{t^2}$ and $v_f = \frac{2d}{t}$.
Total work done:
  $$W = \Delta K + \Delta U + W_{\text{friction}} = \frac{1}{2}m\left(\frac{2d}{t}\right)^2 + mg(d\sin\theta) + (\mu mg\cos\theta)d$$
Power $P = W/t$:
  $$P = \frac{2md^2}{t^3} + \frac{mgd\sin\theta}{t} + \frac{\mu mgd\cos\theta}{t}$$'),
  ('ap-mock-physc-mech-1_q1', 'ap-mock-physc-mech-1', 1, false, 'E', '1D Kinematics & Free Fall', 'medium', 'A rock is dropped off a cliff and falls the first half of the distance to the ground in $t_1$ seconds. If it falls the second half of the distance in $t_2$ seconds, what is the value of $t_2/t_1$? (Ignore air resistance.)', '["$\\frac{1}{2\\sqrt{2}}$","$\\sqrt{2}$","$\\frac{1}{2}$","$1 - \\frac{1}{\\sqrt{2}}$","$\\sqrt{2} - 1$"]'::jsonb, '(E) Let the total height fallen be $H$. The time to fall the first half of the distance ($H/2$) is:
  $$\frac{H}{2} = \frac{1}{2}gt_1^2 \implies t_1 = \sqrt{\frac{H}{g}}$$
The total time $T$ to fall the entire height $H$ is:
  $$H = \frac{1}{2}gT^2 \implies T = \sqrt{\frac{2H}{g}}$$
The time required to fall the second half is $t_2 = T - t_1$:
  $$t_2 = \sqrt{\frac{2H}{g}} - \sqrt{\frac{H}{g}} = \sqrt{\frac{H}{g}}(\sqrt{2} - 1)$$
Taking the ratio $t_2/t_1$:
  $$\frac{t_2}{t_1} = \frac{\sqrt{\frac{H}{g}}(\sqrt{2} - 1)}{\sqrt{\frac{H}{g}}} = \sqrt{2} - 1$$'),
  ('ap-mock-physc-mech-1_q2', 'ap-mock-physc-mech-1', 2, false, 'E', '1D Kinematics & Acceleration', 'medium', 'A bubble starting at the bottom of a soda bottle experiences constant acceleration, $a$, as it rises to the top of the bottle in some time, $t$. How much farther does it travel in the last second of its journey than in the first second? Assume that the journey takes longer than 2 seconds.', '["$a(t + 1\\text{ s})^2$","$a(t - 1\\text{ s})^2$","$at^2$","$a(t + 1\\text{ s})(1\\text{ s})$","$a(t - 1\\text{ s})(1\\text{ s})$"]'::jsonb, '(E) The distance traveled in the first second ($t = 0$ to $t = 1\text{ s}$) starting from rest is:
  $$d_1 = \frac{1}{2}a(1)^2 = \frac{1}{2}a$$
The velocity at time $t - 1\text{ s}$ is $v(t-1) = a(t-1)$. The distance traveled during the final second (from $t-1$ to $t$) is:
  $$d_{\text{last}} = v(t-1)(1) + \frac{1}{2}a(1)^2 = a(t - 1) + \frac{1}{2}a$$
The difference between the two distances is:
  $$\Delta d = d_{\text{last}} - d_1 = \left(a(t-1) + \frac{1}{2}a\right) - \frac{1}{2}a = a(t - 1\text{ s})(1\text{ s})$$'),
  ('ap-mock-physc-mech-1_q3', 'ap-mock-physc-mech-1', 3, false, 'A', 'Calculus-Based Kinematics & Integration', 'medium', 'An object initially at rest experiences a time-varying acceleration given by $a = (2\text{ m/s}^3)t$ for $t \ge 0$. How far does the object travel in the first 3 seconds?', '["$9\\text{ m}$","$12\\text{ m}$","$18\\text{ m}$","$24\\text{ m}$","$27\\text{ m}$"]'::jsonb, '(A) Integrate acceleration with respect to time to get velocity ($v_0 = 0$):
  $$v(t) = \int 2t\,dt = t^2$$
Integrate velocity to find the position displacement over the interval $t = 0$ to $t = 3\text{ s}$:
  $$\Delta x = \int_0^3 t^2\,dt = \left[\frac{t^3}{3}\right]_0^3 = \frac{27}{3} = 9\text{ m}$$'),
  ('ap-mock-physc-mech-1_q4', 'ap-mock-physc-mech-1', 4, false, 'A', 'Work, Energy & Inclines', 'easy', 'What is the benefit of raising an object using an inclined plane instead of simply lifting the object? Assume ideal conditions.', '["The amount of force needed to move the object is reduced.","The amount of time needed to move the object is reduced.","The distance the object must be moved is reduced.","The amount of work needed to move the object is reduced.","The power that must be exerted will be reduced."]'::jsonb, '(A) Gravity is a conservative force, so the total work required to raise an object to height $h$ ($W = mgh$) is identical regardless of the path chosen. By increasing the displacement along the ramp, the required input force is reduced ($F = mg\sin\theta$).'),
  ('ap-mock-physc-mech-1_q5', 'ap-mock-physc-mech-1', 5, false, 'C', 'Conical Pendulum & Circular Dynamics', 'hard', 'In the figure shown, a tension force $F_T$ causes a particle of mass $m$ to move with constant angular speed $\omega$ in a horizontal circular path of radius $R$. Which of the following expressions gives the magnitude of $F_T$? (Ignore air resistance.)', '["$m\\omega^2 R$","$m\\sqrt{\\omega^4 R^2 - g^2}$","$m\\sqrt{g^2 + \\omega^4 R^2}$","$m(\\omega^2 R - g)$","$m(\\omega^2 R + g)$"]'::jsonb, '(C) The vertical component of tension balances gravity: $F_{T,y} = F_T \cos\theta = mg$. The horizontal component provides the centripetal force: $F_{T,x} = F_T \sin\theta = m\omega^2 R$. Applying the Pythagorean identity:
  $$F_T^2 = F_{T,x}^2 + F_{T,y}^2 = (m\omega^2 R)^2 + (mg)^2 \implies F_T = m\sqrt{g^2 + \omega^4 R^2}$$'),
  ('ap-mock-physc-mech-1_q6', 'ap-mock-physc-mech-1', 6, false, 'A', 'Planetary Gravitation & Escape Velocity', 'medium', 'An object (mass = $m$) above the surface of the Moon (mass = $M$) is dropped from an altitude $h$ equal to the Moon''s radius ($R$). With what speed will the object strike the lunar surface?', '["$\\sqrt{\\frac{GM}{R}}$","$\\sqrt{\\frac{GM}{2R}}$","$\\sqrt{\\frac{2GM}{R}}$","$\\sqrt{\\frac{GMm}{R}}$","$\\sqrt{\\frac{2GMm}{R}}$"]'::jsonb, '(A) The initial distance from the lunar center is $r_i = R + h = 2R$. The final distance at impact is $r_f = R$. Using Conservation of Mechanical Energy:
  $$E_i = E_f \implies -\frac{GMm}{2R} = \frac{1}{2}mv^2 - \frac{GMm}{R}$$
  $$\frac{1}{2}mv^2 = \frac{GMm}{R} - \frac{GMm}{2R} = \frac{GMm}{2R} \implies v = \sqrt{\frac{GM}{R}}$$'),
  ('ap-mock-physc-mech-1_q7', 'ap-mock-physc-mech-1', 7, false, 'A', 'Simple Harmonic Motion & Pendulums', 'medium', 'Two pendulums are constructed in such a way that they are identical except that one has a hanging mass of $m$ and the other has a hanging mass of $2m$. Both hanging masses are set into motion such that each system has the same total mechanical energy. Assume that the motion approximates simple harmonic motion. Comparatively, the system with the lesser mass will have greater', '["maximum speed and maximum angle of displacement","frequency and maximum angle of displacement","period and maximum speed","frequency only","maximum angle of displacement only"]'::jsonb, '(A) The period $T = 2\pi\sqrt{L/g}$ and frequency $f$ depend only on $L$ and $g$, making them identical for both pendulums. For equal total mechanical energy $E$:
Maximum kinetic energy: $E = \frac{1}{2}m v_{\max}^2 \implies v_{\max} = \sqrt{2E/m}$, so the smaller mass has the greater maximum speed.
Maximum potential energy: $E = mgh_{\max} \implies h_{\max} = E/(mg)$, so the smaller mass reaches a greater vertical height, which requires a larger maximum angular displacement.'),
  ('ap-mock-physc-mech-1_q8', 'ap-mock-physc-mech-1', 8, false, 'D', 'Rolling Motion & Rotational Dynamics', 'hard', 'A uniform cylinder of mass $m$ and radius $r$ unrolls without slipping from two strings tied to a vertical support. If the rotational inertia of the cylinder is $\frac{1}{2}mr^2$, find the acceleration of its center of mass.', '["$\\frac{1}{3}g$","$\\frac{1}{2}g$","$\\frac{3}{5}g$","$\\frac{2}{3}g$","$g$"]'::jsonb, '(D) Let $F_T$ be the tension in each of the two strings.
Translational motion: $mg - 2F_T = ma$
Rotational motion about CM: $\tau = (2F_T)r = I\alpha = \left(\frac{1}{2}mr^2\right)\left(\frac{a}{r}\right) \implies 2F_T = \frac{1}{2}ma$
Substituting into the translational equation:
  $$mg - \frac{1}{2}ma = ma \implies mg = \frac{3}{2}ma \implies a = \frac{2}{3}g$$'),
  ('ap-mock-physc-mech-1_q9', 'ap-mock-physc-mech-1', 9, false, 'B', 'Work, Power & Constant Velocity', 'easy', 'A space shuttle is launched from Earth. As it travels up, it moves at a constant velocity of $150\text{ m/s}$ straight up. If its engines provide $1.5 \times 10^8\text{ W}$ of power, what is the shuttle''s mass? You may assume that the shuttle''s mass and the acceleration due to gravity are constant ($g = 10\text{ m/s}^2$).', '["$6.7 \\times 10^2\\text{ kg}$","$1.0 \\times 10^5\\text{ kg}$","$6.7 \\times 10^5\\text{ kg}$","$1.0 \\times 10^6\\text{ kg}$","$2.3 \\times 10^6\\text{ kg}$"]'::jsonb, '(B) At constant velocity, engine thrust equals gravitational weight: $F = mg$.
  $$P = Fv = mgv \implies m = \frac{P}{gv} = \frac{1.5 \times 10^8\text{ W}}{(10\text{ m/s}^2)(150\text{ m/s})} = \frac{1.5 \times 10^8}{1500} = 1.0 \times 10^5\text{ kg}$$')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-mock-physc-mech-1_q10', 'ap-mock-physc-mech-1', 10, false, 'B', 'Newton''s 2nd Law & Force Graphs', 'easy', 'A uniform cylinder, initially at rest on a frictionless, horizontal surface, is pulled by a constant force $F$ from time $t = 0$ to time $t = T$. From time $t = T$ on, this force is removed. Which graph best illustrates the speed, $v$, of the cylinder''s center of mass from $t = 0$ onwards?', '["Velocity increases linearly to $T$, then decreases linearly to zero","Velocity increases linearly from $0$ to $T$, then remains constant","Velocity increases parabolically from $0$ to $T$, then remains constant","Velocity stays constant from $0$ to $T$, then drops to zero","Velocity increases exponentially"]'::jsonb, '(B) For $0 \le t \le T$, the constant net force causes a constant acceleration $a = F/m$, meaning $v(t) = at$ increases linearly. For $t > T$, $F = 0 \implies a = 0$, so velocity remains at a constant horizontal value.'),
  ('ap-mock-physc-mech-1_q11', 'ap-mock-physc-mech-1', 11, false, 'A', 'Gravitational Potential & Orbital Energy', 'hard', 'A satellite is in circular orbit around Earth (radius = $R$). If the work required to lift the satellite to its orbital height is equal to the satellite''s kinetic energy while in this orbit, how high above the surface of Earth is the satellite?', '["$R/2$","$R$","$3R/2$","$2R$","$4R$"]'::jsonb, '(A) Work to lift the satellite to altitude $h$:
  $$W = \Delta U = -\frac{GMm}{R+h} - \left(-\frac{GMm}{R}\right) = \frac{GMmh}{R(R+h)}$$
For a circular orbit at radius $r = R+h$, the orbital speed satisfies $v^2 = \frac{GM}{R+h}$, so kinetic energy is:
  $$K = \frac{1}{2}mv^2 = \frac{GMm}{2(R+h)}$$
Equating $W = K$:
  $$\frac{GMmh}{R(R+h)} = \frac{GMm}{2(R+h)} \implies \frac{h}{R} = \frac{1}{2} \implies h = \frac{R}{2}$$'),
  ('ap-mock-physc-mech-1_q12', 'ap-mock-physc-mech-1', 12, false, 'E', 'Inelastic Collisions & Center of Mass', 'hard', 'A block of length $l_1 = 10\text{ cm}$, mass $m_1 = 10\text{ kg}$, and $v_1 = 2\text{ m/s}$ moves toward a second block of length $l_2 = 20\text{ cm}$, $m_2 = 2\text{ kg}$, and $v_2 = 8\text{ m/s}$ moving toward the first. The blocks'' closest edges are $1\text{ m}$ apart. The blocks experience a perfectly inelastic collision. How long after the collision does it take for the center of mass of the combined object to cross the point midway between the blocks'' starting positions?', '["$0.225\\text{ s}$","$0.325\\text{ s}$","$0.525\\text{ s}$","$0.900\\text{ s}$","$0.975\\text{ s}$"]'::jsonb, '(E) Time to collision: $t_{\text{coll}} = \frac{1.0\text{ m}}{2\text{ m/s} + 8\text{ m/s}} = 0.1\text{ s}$. The collision point is $0.2\text{ m}$ from block 1''s starting position.  
Velocity of combined mass:
  $$v_f = \frac{(10\text{ kg})(2\text{ m/s}) + (2\text{ kg})(-8\text{ m/s})}{10\text{ kg} + 2\text{ kg}} = \frac{4}{12} = \frac{1}{3}\text{ m/s}$$
Midpoint of the initial separation is $0.5\text{ m}$ from block 1''s starting position.  
The distance from the collision point to the midpoint is $0.5 - 0.2 = 0.3\text{ m}$. Taking the center of mass position offset within the combined block into account adds $0.025\text{ m}$, giving a total travel distance of $d = 0.325\text{ m}$.  
Time: $t = \frac{0.325\text{ m}}{1/3\text{ m/s}} = 0.975\text{ s}$.'),
  ('ap-mock-physc-mech-1_q13', 'ap-mock-physc-mech-1', 13, false, 'C', 'Impulse-Momentum Theorem', 'medium', 'A rubber ball (mass = $0.08\text{ kg}$) is dropped from a height of $3.2\text{ m}$ and rebounds almost to its original height. If the impact time with the floor is $0.04\text{ s}$, what average force did the floor exert on the ball?', '["$0.16\\text{ N}$","$16\\text{ N}$","$32\\text{ N}$","$36\\text{ N}$","$64\\text{ N}$"]'::jsonb, '(C) Impact speed: $v = \sqrt{2gh} = \sqrt{2(10)(3.2)} = 8\text{ m/s}$.
Change in momentum taking upward as positive:
  $$\Delta p = m(v_f - v_i) = 0.08(8 - (-8)) = 1.28\text{ kg}\cdot\text{m/s}$$
Average force:
  $$F_{\text{avg}} = \frac{\Delta p}{\Delta t} = \frac{1.28\text{ N}\cdot\text{s}}{0.04\text{ s}} = 32\text{ N}$$'),
  ('ap-mock-physc-mech-1_q14', 'ap-mock-physc-mech-1', 14, false, 'D', 'Rotational Kinematics & Arc Length', 'easy', 'A disk of radius $0.1\text{ m}$ initially at rest undergoes an angular acceleration of $2.0\text{ rad/s}^2$. If the disk only rotates, find the total distance traveled by a point on the rim in $4.0\text{ s}$.', '["$0.4\\text{ m}$","$0.8\\text{ m}$","$1.2\\text{ m}$","$1.6\\text{ m}$","$2.0\\text{ m}$"]'::jsonb, '(D) Angular displacement:
  $$\Delta\theta = \frac{1}{2}\alpha t^2 = \frac{1}{2}(2.0\text{ rad/s}^2)(4.0\text{ s})^2 = 16\text{ rad}$$
Arc distance on rim:
  $$s = r\Delta\theta = (0.1\text{ m})(16\text{ rad}) = 1.6\text{ m}$$'),
  ('ap-mock-physc-mech-1_q15', 'ap-mock-physc-mech-1', 15, false, 'C', 'Energy Conservation & Projectile Launch', 'medium', 'A small object slides down a frictionless quarter-circular slide of radius $R$ starting from rest at a height equal to $2R$ above a horizontal surface. Find its horizontal displacement, $x$, from the starting point at the moment it strikes the surface.', '["$R$","$2R$","$3R$","$4R$","$5R$"]'::jsonb, '(C) The object leaves the slide horizontally at height $R$ with speed $v = \sqrt{2gR}$.
Time to fall the remaining height $R$: $t = \sqrt{2R/g}$.
Horizontal distance traveled in air:
  $$\Delta x_{\text{air}} = v t = \sqrt{2gR}\sqrt{\frac{2R}{g}} = 2R$$
Total horizontal displacement from the starting position: $x_{\text{total}} = R + 2R = 3R$.'),
  ('ap-mock-physc-mech-1_q16', 'ap-mock-physc-mech-1', 16, false, 'A', 'Uniform Circular Motion & Projections', 'hard', 'A particle executes uniform circular motion in a circle of radius $R$. When the shadow on Screen 1 is at position $x = -0.5R$ and moving in the $+x$ direction, what is true about the position and velocity of the shadow on Screen 2 at that same instant?', '["$y = -0.866R$; velocity in $-y$ direction","$y = -0.866R$; velocity in $+y$ direction","$y = -0.5R$; velocity in $-y$ direction","$y = +0.866R$; velocity in $-y$ direction","$y = +0.866R$; velocity in $+y$ direction"]'::jsonb, '(A) Position along $x$: $x = R\cos\theta = -0.5R \implies \theta = 120^\circ$ or $240^\circ$.
Because the shadow moves in $+x$ direction, $v_x = -\omega R\sin\theta > 0 \implies \sin\theta < 0$, placing the angle at $\theta = 240^\circ$.
Therefore:
  $$y = R\sin(240^\circ) = -R\frac{\sqrt{3}}{2} \approx -0.866R$$
  $$v_y = \omega R\cos(240^\circ) = -0.5\omega R < 0 \quad (\text{directed along }-y)$$'),
  ('ap-mock-physc-mech-1_q17', 'ap-mock-physc-mech-1', 17, false, 'C', 'Rotational Inertia & Torque', 'hard', 'Two objects of masses $m$ and $2m$ are attached to the ends of a rigid massless rod of length $L$ at rest on a frictionless table. When a force $F$ is applied perpendicularly at mass $2m$, the resulting rotational acceleration of the rod about its center of mass is $kF/(mL)$. What is $k$?', '["$1/4$","$1/3$","$1/2$","$2/3$","$1$"]'::jsonb, '(C) Distance of CM from mass $m$: $y_{\text{cm}} = \frac{m(0) + 2m(L)}{3m} = \frac{2}{3}L$.
Distance from CM to mass $2m$: $L - \frac{2}{3}L = \frac{1}{3}L$.
Rotational inertia about CM:
  $$I_{\text{cm}} = m\left(\frac{2}{3}L\right)^2 + 2m\left(\frac{1}{3}L\right)^2 = \frac{4}{9}mL^2 + \frac{2}{9}mL^2 = \frac{2}{3}mL^2$$
Torque about CM: $\tau = F\left(\frac{1}{3}L\right)$.
Angular acceleration:
  $$\alpha = \frac{\tau}{I_{\text{cm}}} = \frac{F L / 3}{\frac{2}{3}mL^2} = \frac{1}{2}\frac{F}{mL} \implies k = \frac{1}{2}$$'),
  ('ap-mock-physc-mech-1_q18', 'ap-mock-physc-mech-1', 18, false, 'E', 'Impulse, Momentum & Collision Safety', 'medium', 'Old cars were made with rigid frames; modern cars are made with frames that crumple in a collision. If each vehicle crashes into a wall and comes to a complete stop from the same initial mass and speed, which of the following would NOT be true?', '["The modern vehicle would experience less force.","The modern vehicle would experience less impulse.","The modern vehicle''s magnitude of acceleration would be less.","The modern vehicle''s collision would take less time.","More than one of the above would not be true."]'::jsonb, '(E) Because both vehicles have the same mass and initial speed and both come to rest, $\Delta p$ is identical for both. Since Impulse $J = \Delta p$, both experience the same impulse (making B false). The crumpling frame extends the stopping distance and increases collision time, so it takes more time (making D false). Because both B and D are false, (E) is the correct choice.'),
  ('ap-mock-physc-mech-1_q19', 'ap-mock-physc-mech-1', 19, false, 'D', 'Static Equilibrium & Torque', 'easy', 'A homogeneous bar lying on a flat table is acted upon by exactly two external horizontal forces, $F_1$ and $F_2$. If the net force on the rod is zero, which of the following is true?', '["The net torque on the bar must also be zero.","The bar cannot accelerate translationally or rotationally.","The bar can accelerate translationally if $F_1$ and $F_2$ are not applied at the same point.","The net torque will be zero if $F_1$ and $F_2$ are applied at the same point.","None of the above"]'::jsonb, '(D) Since $\vec{F}_{\text{net}} = \vec{F}_1 + \vec{F}_2 = 0$, we have $\vec{F}_2 = -\vec{F}_1$. If both forces are applied at the same point, their position vectors $\vec{r}$ from any chosen pivot are identical, resulting in $\vec{\tau}_{\text{net}} = \vec{r}\times\vec{F}_1 + \vec{r}\times(-\vec{F}_1) = 0$.'),
  ('ap-mock-physc-mech-1_q20', 'ap-mock-physc-mech-1', 20, false, 'B', 'Universal Gravitation & Weight', 'easy', 'An astronaut lands on a planet whose mass and radius are each twice that of Earth. If the astronaut weighs $800\text{ N}$ on Earth, how much will he weigh on this planet?', '["$200\\text{ N}$","$400\\text{ N}$","$800\\text{ N}$","$1,600\\text{ N}$","$3,200\\text{ N}$"]'::jsonb, '(B) $$g_{\text{planet}} = \frac{G(2M)}{(2R)^2} = \frac{2}{4}\frac{GM}{R^2} = \frac{1}{2}g_{\text{Earth}}$$
$$W_{\text{planet}} = m g_{\text{planet}} = \frac{1}{2}W_{\text{Earth}} = \frac{1}{2}(800\text{ N}) = 400\text{ N}$$'),
  ('ap-mock-physc-mech-1_q21', 'ap-mock-physc-mech-1', 21, false, 'C', 'Work-Energy Theorem & Variable Forces', 'medium', 'A particle of mass $m = 1.0\text{ kg}$ is acted upon by a variable force $F(x)$. The area under the $F(x)$ curve from $x = 0$ to $x = 10\text{ m}$ is $50\text{ N}\cdot\text{m}$. If the particle''s speed was zero at $x = 0$, what is its speed at $x = 10\text{ m}$?', '["$5.0\\text{ m/s}$","$8.7\\text{ m/s}$","$10\\text{ m/s}$","$14\\text{ m/s}$","$20\\text{ m/s}$"]'::jsonb, '(C) By the Work-Energy Theorem:
  $$W = \Delta K \implies 50\text{ J} = \frac{1}{2}mv^2 - 0 \implies v = \sqrt{\frac{2(50)}{1.0}} = 10\text{ m/s}$$'),
  ('ap-mock-physc-mech-1_q22', 'ap-mock-physc-mech-1', 22, false, 'B', 'Angular Momentum Conservation & Collapse', 'medium', 'The radius of a collapsing spinning star decreases to $\frac{1}{4}$ of its initial value. What is the ratio of the final rotational kinetic energy to the initial rotational kinetic energy ($K_f / K_i$)?', '["$4$","$16$","$64$","$256$","$1/16$"]'::jsonb, '(B) Angular momentum is conserved: $L = I_i\omega_i = I_f\omega_f \implies \omega_f = \omega_i(I_i/I_f)$.
For a sphere, $I \propto R^2$. Since $R_f = R_i/4$, $I_f = I_i/16$, which yields $\omega_f = 16\omega_i$.
The rotational kinetic energy ratio is:
  $$\frac{K_f}{K_i} = \frac{\frac{1}{2}I_f\omega_f^2}{\frac{1}{2}I_i\omega_i^2} = \left(\frac{1}{16}\right)(16)^2 = 16$$'),
  ('ap-mock-physc-mech-1_q23', 'ap-mock-physc-mech-1', 23, false, 'C', '2D Projectile Motion', 'easy', 'A ball is projected with an initial velocity of magnitude $v_0 = 40\text{ m/s}$ at an angle of $60^\circ$ toward a vertical wall $20\text{ m}$ away. How long does the ball take to reach the wall?', '["$0.25\\text{ s}$","$0.50\\text{ s}$","$1.0\\text{ s}$","$2.0\\text{ s}$","$3.0\\text{ s}$"]'::jsonb, '(C) The horizontal velocity is constant:
$$v_x = v_0 \cos 60^\circ = 40(0.5) = 20\text{ m/s}$$
$$t = \frac{x}{v_x} = \frac{20\text{ m}}{20\text{ m/s}} = 1.0\text{ s}$$'),
  ('ap-mock-physc-mech-1_q24', 'ap-mock-physc-mech-1', 24, false, 'B', 'Dimensional Analysis', 'easy', 'If $C, M, L,$ and $T$ represent the dimensions of charge, mass, length, and time respectively, what are the dimensions of the permittivity of free space ($\varepsilon_0$)?', '["$T^2C^2 / (M^2L^2)$","$T^2C^2 / (ML^3)$","$ML^3 / (T^2C^2)$","$C^2M / (T^2L^2)$","$T^2L^2 / (C^2M)$"]'::jsonb, '(B) From Coulomb''s Law $F = \frac{1}{4\pi\varepsilon_0}\frac{q^2}{r^2} \implies \varepsilon_0 = \frac{q^2}{F r^2}$.
Using base dimensions $[q] = C$, $[r] = L$, and $[F] = MLT^{-2}$:
$$[\varepsilon_0] = \frac{C^2}{(MLT^{-2})(L^2)} = \frac{T^2C^2}{ML^3}$$'),
  ('ap-mock-physc-mech-1_q25', 'ap-mock-physc-mech-1', 25, false, 'D', '2D Inelastic Collisions & Vectors', 'hard', 'Two clay balls moving toward each other on a frictionless surface collide perfectly inelastically. Ball 1 has mass $m_1$ and moves at $45^\circ$; ball 2 has mass $m_2$ and moves at $60^\circ$. If $m_1 = 2m_2$ and the post-collision velocity is parallel to the negative $y$-axis, what is $v_2$?', '["$v_1(\\sin 60^\\circ)$","$v_1(\\cos 60^\\circ)$","$v_1(2\\cos 60^\\circ)$","$v_1(2\\sin 45^\\circ)/(\\sin 60^\\circ)$","$v_1(\\tan 60^\\circ)$"]'::jsonb, '(D) Since the combined mass moves purely along the $-y$ axis, horizontal momentum must sum to zero:
  $$m_1 v_1 \sin 45^\circ - m_2 v_2 \sin 60^\circ = 0$$
Substituting $m_1 = 2m_2$:
  $$(2m_2)v_1 \sin 45^\circ = m_2 v_2 \sin 60^\circ \implies v_2 = \frac{2v_1 \sin 45^\circ}{\sin 60^\circ}$$'),
  ('ap-mock-physc-mech-1_q26', 'ap-mock-physc-mech-1', 26, false, 'B', 'SHM & Static Friction Threshold', 'hard', 'The coefficient of static friction between two blocks is $0.80$. If the blocks oscillate horizontally with a frequency of $2.0\text{ Hz}$, what is the maximum amplitude of the oscillations if the small block is not to slip on the large block?', '["$3.1\\text{ cm}$","$5.0\\text{ cm}$","$6.2\\text{ cm}$","$7.5\\text{ cm}$","$9.4\\text{ cm}$"]'::jsonb, '(B) Maximum acceleration in SHM is $a_{\max} = \omega^2 A = (2\pi f)^2 A$. To prevent slipping, static friction must provide this acceleration:
  $$\mu_s g \ge (2\pi f)^2 A \implies A \le \frac{\mu_s g}{4\pi^2 f^2} = \frac{(0.80)(9.8)}{4\pi^2 (2.0)^2} \approx 0.050\text{ m} = 5.0\text{ cm}$$'),
  ('ap-mock-physc-mech-1_q27', 'ap-mock-physc-mech-1', 27, false, 'D', 'Coefficient of Restitution', 'medium', 'When two objects collide, the coefficient of restitution is $e = v_{\text{rel,after}} / v_{\text{rel,before}}$. If a ball dropped from height $H_1$ rebounds to height $H_2$, what is $e$?', '["$H_1/H_2$","$H_2/H_1$","$\\sqrt{H_1/H_2}$","$\\sqrt{H_2/H_1}$","$(H_1/H_2)^2$"]'::jsonb, '(D) Impact speed is $v_1 = \sqrt{2gH_1}$ and rebound speed is $v_2 = \sqrt{2gH_2}$.
  $$e = \frac{v_2}{v_1} = \frac{\sqrt{2gH_2}}{\sqrt{2gH_1}} = \sqrt{\frac{H_2}{H_1}}$$'),
  ('ap-mock-physc-mech-1_q28', 'ap-mock-physc-mech-1', 28, false, 'D', 'Torque & Lever Arm', 'easy', 'A square metal plate of side length $40\text{ cm}$ lies flat on a table. A force $F$ of magnitude $10\text{ N}$ is applied along one of the corners. Determine the torque produced by $F$ relative to the center of rotation (center of mass).', '["$0\\text{ N}\\cdot\\text{m}$","$1.0\\text{ N}\\cdot\\text{m}$","$1.4\\text{ N}\\cdot\\text{m}$","$2.0\\text{ N}\\cdot\\text{m}$","$4.0\\text{ N}\\cdot\\text{m}$"]'::jsonb, '(D) The lever arm from the geometric center to the line of action along any side of the square is $r_\perp = s/2 = 0.40/2 = 0.20\text{ m}$.
  $$\tau = F r_\perp = (10\text{ N})(0.20\text{ m}) = 2.0\text{ N}\cdot\text{m}$$'),
  ('ap-mock-physc-mech-1_q29', 'ap-mock-physc-mech-1', 29, false, 'A', 'Conservative Gravitational Work', 'easy', 'A block of mass $m = 2.0\text{ kg}$ is pushed upward from $(0,0)$ to $(3\text{ m}, 3\text{ m})$. How much work is done by gravity during this displacement?', '["$-60\\text{ J}$","$-80\\text{ J}$","$-90\\text{ J}$","$-100\\text{ J}$","$-120\\text{ J}$"]'::jsonb, '(A) Gravity is conservative and depends only on vertical displacement $\Delta z = 3\text{ m}$:
  $$W_g = -mg\Delta z = -(2.0\text{ kg})(10\text{ m/s}^2)(3\text{ m}) = -60\text{ J}$$'),
  ('ap-mock-physc-mech-1_q30', 'ap-mock-physc-mech-1', 30, false, 'C', 'SHM Spring-Block Collision', 'hard', 'A horizontal spring with constant $k$ oscillates between $-A$ and $+A$ with mass $M$. A bullet of mass $m$ with speed $v$ collides inelastically with $M$ at $x = -A$. How far beyond $x = -A$ will the spring compress?', '["$\\frac{mv}{\\sqrt{kM}}$","$\\frac{mv}{k(M+m)}$","$\\frac{mv}{\\sqrt{k(M+m)}}$","$\\frac{Mv}{\\sqrt{k(M+m)}}$","$\\frac{mv}{\\sqrt{km}}$"]'::jsonb, '(C) At $x = -A$, the block was momentarily at rest. Immediately after the collision, the combined velocity is $v'' = \frac{mv}{M+m}$. The additional kinetic energy is converted into extra compression $x_{\text{extra}}$:
  $$\frac{1}{2}k x_{\text{extra}}^2 = \frac{1}{2}(M+m)(v'')^2 = \frac{1}{2}\frac{m^2v^2}{M+m} \implies x_{\text{extra}} = \frac{mv}{\sqrt{k(M+m)}}$$'),
  ('ap-mock-physc-mech-1_q31', 'ap-mock-physc-mech-1', 31, false, 'D', 'Calculus Moment of Inertia Integration', 'hard', 'A rod pivoting about $x = 0$ has linear density $\lambda(x) = kx$. Determine the rod''s moment of inertia in terms of length $L$ and total mass $M$.', '["$\\frac{1}{3}ML^2$","$\\frac{1}{4}ML^2$","$\\frac{2}{5}ML^2$","$\\frac{1}{2}ML^2$","$2ML^2$"]'::jsonb, '(D) Total mass: $M = \int_0^L kx\,dx = \frac{1}{2}kL^2 \implies k = \frac{2M}{L^2}$.
Moment of inertia:
  $$I = \int_0^L x^2\,dm = \int_0^L x^2(kx\,dx) = \frac{1}{4}kL^4 = \frac{1}{4}\left(\frac{2M}{L^2}\right)L^4 = \frac{1}{2}ML^2$$'),
  ('ap-mock-physc-mech-1_q32', 'ap-mock-physc-mech-1', 32, false, 'D', 'Potential Energy Curves & Stability', 'medium', 'A conservative force has potential energy $U(x) = x^3 - 12x$. Which position represents a point of stable equilibrium?', '["$x = -4\\text{ m}$","$x = -2\\text{ m}$","$x = 0\\text{ m}$","$x = 2\\text{ m}$","$x = 4\\text{ m}$"]'::jsonb, '(D) Equilibrium requires $\frac{dU}{dx} = 3x^2 - 12 = 0 \implies x = \pm 2\text{ m}$.
Stable equilibrium requires a local minimum ($\frac{d^2U}{dx^2} > 0$):
  $$\frac{d^2U}{dx^2} = 6x \implies \text{At } x = 2\text{ m}, \frac{d^2U}{dx^2} = 12 > 0\text{ (Stable)}$$'),
  ('ap-mock-physc-mech-1_q33', 'ap-mock-physc-mech-1', 33, false, 'D', 'Atwood Machine & Inertial Frames', 'medium', 'A light frictionless pulley attached to an elevator ceiling supports masses $m$ and $M$ ($M > m$). The elevator car descends at a constant velocity. Determine the acceleration of the masses relative to the elevator.', '["$(M - m)g$","$(M + m)g$","$\\frac{M + m}{M - m}g$","$\\frac{M - m}{M + m}g$","$\\frac{2Mm}{M + m}g$"]'::jsonb, '(D) Because the elevator travels at constant velocity, it acts as an inertial frame of reference ($a_{\text{frame}} = 0$). The Atwood acceleration is:
  $$a = \frac{M - m}{M + m}g$$'),
  ('ap-mock-physc-mech-1_q34', 'ap-mock-physc-mech-1', 34, false, 'E', 'Variable Friction Ramp Energy Tracking', 'hard', 'A block ($m = 2\text{ kg}$) starts at rest on a ramp ($\sin\theta = 0.45, \cos\theta = 0.9$). The ramp consists of alternating frictionless sections of $1\text{ m}$ and rough sections ($\mu = 2/3$) of increasing length ($1\text{ m}, 2\text{ m}, 3\text{ m}, \dots$). How far along the ramp does the block travel before stopping?', '["$4\\text{ m}$","$8\\text{ m}$","$12\\text{ m}$","$19\\text{ m}$","$24\\text{ m}$"]'::jsonb, '(E) $\Delta PE$ gained per meter: $mg\sin\theta = (2)(10)(0.45) = +9\text{ J/m}$.  
Friction work per rough meter: $-\mu mg\cos\theta = -(2/3)(2)(10)(0.9) = -12\text{ J/m}$.  
Net change on rough segments: $+9 - 12 = -3\text{ J/m}$.
Tracking energy across the sequence:
0–1 m (smooth): $+9\text{ J}$
1–2 m (rough 1m): $9 - 3 = 6\text{ J}$
2–3 m (smooth): $6 + 9 = 15\text{ J}$
3–5 m (rough 2m): $15 - 6 = 9\text{ J}$
5–6 m (smooth): $9 + 9 = 18\text{ J}$
6–9 m (rough 3m): $18 - 9 = 9\text{ J}$
9–10 m (smooth): $9 + 9 = 18\text{ J}$
10–14 m (rough 4m): $18 - 12 = 6\text{ J}$
14–15 m (smooth): $6 + 9 = 15\text{ J}$
15–20 m (rough 5m): $15 - 15 = 0\text{ J}$  
20–21 m (smooth): $+9\text{ J}$  
Next rough segment: travels $9/3 = 3\text{ m}$ before stopping.
Total distance = $21 + 3 = 24\text{ m}$.'),
  ('ap-mock-physc-mech-1_q35', 'ap-mock-physc-mech-1', 35, false, 'E', 'Vector Force Sums & Newton''s 2nd Law', 'easy', 'An object of mass $2\text{ kg}$ is acted upon by three external forces, each of magnitude $4\text{ N}$. Which of the following could NOT be the resulting acceleration of the object?', '["$0\\text{ m/s}^2$","$2\\text{ m/s}^2$","$4\\text{ m/s}^2$","$6\\text{ m/s}^2$","$8\\text{ m/s}^2$"]'::jsonb, '(E) The maximum possible net force occurs when all three forces act in the same direction: $F_{\text{net,max}} = 4 + 4 + 4 = 12\text{ N}$.
  $$a_{\max} = \frac{12\text{ N}}{2\text{ kg}} = 6\text{ m/s}^2$$
An acceleration of $8\text{ m/s}^2$ is impossible.'),
  ('ap-mock-physc-mech-2_q1', 'ap-mock-physc-mech-2', 1, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A variable force exerted during time interval \Delta t changes the velocity of mass m from v0 to vf. What is the average power exerted during this time interval?', '["(vf − v0)/\\Delta t","mvf − mv0","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(D) Average power is given by the equation . What is the work done? Because there are no other forces acting on the block, (according to the work-energy theorem). Dividing by the time increment to calculate the average power yields choice (D). Note that the correct answer can be obtained using only dimensional analysis.'),
  ('ap-mock-physc-mech-2_q2', 'ap-mock-physc-mech-2', 2, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A point charge −q is released from rest at the center of a parallel plate capacitor, as shown. Note that the plates have small holes that allow the charge to exit the capacitor. Which of the following statements describes the charge’s behavior a long time after it exits the capacitor?', '["It is moving to the right with a kinetic energy of KE = qV.","It is moving to the left with a kinetic energy of KE = qV.","It is moving to the right with a kinetic energy of KE = qV/2.","It is moving to the left with a kinetic energy of KE = qV/2.","It never reaches a constant velocity but instead continually oscillates in and out of the capacitor."]'::jsonb, '(D) Average power is given by the equation . What is the work done? Because there are no other forces acting on the block, (according to the work-energy theorem). Dividing by the time increment to calculate the average power yields choice (D). Note that the correct answer can be obtained using only dimensional analysis.'),
  ('ap-mock-physc-mech-2_q3', 'ap-mock-physc-mech-2', 3, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'A particle moves with constant speed v counterclockwise around a circle of radius r in the xy-plane. Which of the following correctly describes the x-component of the velocity?', '["It is constant and equal to v.","It is constant but not equal to v.","It varies between zero and v.","It varies between zero and .","It varies between −v and v."]'::jsonb, '(E) Consider the figure. At points A and C, the x-component of velocity is zero, at point B it is equal to −v, and at point D it is equal to +v. This range of values is consistent only with choice (E).'),
  ('ap-mock-physc-mech-2_q4', 'ap-mock-physc-mech-2', 4, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'Describe the potential V as a function of r inside a spherical shell with uniform surface charge density.', '["V = 0.","V is constant.","V has a constant slope.","V is proportional to 1/r.","V is proportional to 1/r2."]'::jsonb, '(E) Consider the figure. At points A and C, the x-component of velocity is zero, at point B it is equal to −v, and at point D it is equal to +v. This range of values is consistent only with choice (E).'),
  ('ap-mock-physc-mech-2_q5', 'ap-mock-physc-mech-2', 5, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'A baseball is falling toward Earth. If ab is the acceleration of the baseball due to the gravitational pull of Earth and ae is the acceleration of Earth due to the baseball, which of the following is true?', '["ae = 0","ab = ae","ab >> ae, and the accelerations are parallel.","ae >> ab, and the accelerations are parallel.","ab >> ae, and the accelerations are antiparallel."]'::jsonb, '(E) According to Newton’s third law, the baseball and Earth exert equal and opposite forces on each other. Therefore, the accelerations they experience must be in opposite directions. Because F = meae = mbab, the larger object (Earth) experiences a smaller acceleration (which is imperceptible).'),
  ('ap-mock-physc-mech-2_q6', 'ap-mock-physc-mech-2', 6, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'While discharging a capacitor through a resistor, how many of the following functions are exponentially decreasing? I. the current through the circuit II. the energy stored in the capacitor III. the voltage across the resistor IV. the power dissipated in the resistor V. the electric field within the capacitor VI. the charge on the capacitor', '["two","three","four","five","six"]'::jsonb, '(E) According to Newton’s third law, the baseball and Earth exert equal and opposite forces on each other. Therefore, the accelerations they experience must be in opposite directions. Because F = meae = mbab, the larger object (Earth) experiences a smaller acceleration (which is imperceptible).'),
  ('ap-mock-physc-mech-2_q7', 'ap-mock-physc-mech-2', 7, false, 'A', 'Practice Test 2 – Mechanics', 'medium', 'If the angular position of a disk is given by the equation \theta(t) = 2 + 4t − 3t2, what is the angular velocity of the disk as a function of time?', '["4 − 6t","6t − 4","2t + 2t2 − 3t3","3t3 − 2t2 − 2t","3t3 − 2t2 − 2t + C"]'::jsonb, '(A) The angular velocity is simply the derivative of the angular position:'),
  ('ap-mock-physc-mech-2_q8', 'ap-mock-physc-mech-2', 8, false, 'A', 'Practice Test 2 – Mechanics', 'medium', 'The figure shows two coaxial cylinders that have charge distributed uniformly on their surfaces, with a linear charge density of −\lambda and +\lambda', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The angular velocity is simply the derivative of the angular position:'),
  ('ap-mock-physc-mech-2_q9', 'ap-mock-physc-mech-2', 9, false, 'A', 'Practice Test 2 – Mechanics', 'medium', 'When an object moving in the circular track as shown has a velocity in the +y-direction, its acceleration has components in the +x- and +y- directions. Which of the following statements is true?', '["The object is moving clockwise with increasing speed.","The object is moving counterclockwise with increasing speed.","The object is moving clockwise with decreasing speed.","The object is moving counterclockwise with decreasing speed.","The object is moving clockwise with constant speed."]'::jsonb, '(A) Because the object has a tangential acceleration parallel to its velocity, its speed is increasing. Because the centripetal acceleration (perpendicular to the velocity) always points toward the center of the circle, the object must move clockwise so that the centripetal acceleration points in the +x-direction while the object is instantaneously moving in the +y-direction.'),
  ('ap-mock-physc-mech-2_q10', 'ap-mock-physc-mech-2', 10, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'A force F exerted on a block parallel to an inclined slope as shown causes the block’s speed to increase from zero to v as it moves a distance d along the incline. If the coefficient of friction is \muK, how much work does gravity do during this time interval?', '["\\muKmg(cos \\theta)d","\\muKmg(cos \\theta)d + mg(sin \\theta)d","(D) mgd sin \\theta","2E_0","−mgd sin \\theta"]'::jsonb, '(E) The gravitational force is constant, so the work it does is given by the equation . The y-coordinate increases by an amount d sin \theta, so the work done by gravity is given by choice (E). (Check: The work done by gravity must come out negative because the force of gravity is antiparallel to the vertical displacement of the object.)'),
  ('ap-mock-physc-mech-2_q11', 'ap-mock-physc-mech-2', 11, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A point mass is released from rest as shown. If the inclined planes are frictionless, which of the following statements is correct?', '["The mass is undergoing simple harmonic motion with a period of T = (2d/g sin \\theta)1/2.","The mass is undergoing simple harmonic motion with a period of T = 2(2d/g sin \\theta)1/2.","The mass is undergoing simple harmonic motion with a period of T = 4(2d/g sin \\theta)1/2.","As the mass slides down the slope, the component of the momentum perpendicular to the slope is constant.","The mass is in static equilibrium."]'::jsonb, '(D) Choices (A)−(C): The mass is not undergoing SHM because the restoring force is not proportional to the displacement (instead, it is constant and equal to mg sin \theta). Choice (E): The mass would be in static equilibrium if placed at the bottom of the incline with zero initial velocity, but in the present case the object oscillates back and forth along the inclines. Choice (D): The component of the momentum perpendicular to the slope is zero as the mass initially slides down the slope, and it remains zero. (There is zero net force in this direction because the normal force cancels the component of the gravitational force perpendicular to the incline.)'),
  ('ap-mock-physc-mech-2_q12', 'ap-mock-physc-mech-2', 12, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'An object of mass m has its position given by the equation x(t) = at4 − bt3 + c. What is the force on the object as a function of time?', '["F(t) = (4at3 − 3bt2)","F(t) = (4at3 − 3bt2)m","F(t) = (12at2 − 6bt)","F(t) = (12at2 − 6bt)m","F(t) = −(12at2 − 6bt)m"]'::jsonb, '(D) Differentiating twice to calculate the acceleration from the position yields a(t) = (12at2 − 6bt). Applying Newton’s second law then gives F = ma = ma(t) = m(12at2 − 6bt).'),
  ('ap-mock-physc-mech-2_q13', 'ap-mock-physc-mech-2', 13, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'A mass is suspended by two ropes as shown. What is the ratio of the tension forces in the two ropes?', '["T1/T2 = sin \\theta1/sin \\theta2","T1/T2 = sin \\theta2/sin \\theta1","T1/T2 = cos \\theta1/cos \\theta2","T1/T2 = cos \\theta2/cos \\theta1","T1/T2 = tan \\theta1/tan \\theta2"]'::jsonb, '(B) For the object to be in static equilibrium, the net force in the x- direction must be zero: Fnet,x = 0 = T1 sin \theta1 − T2 sin \theta2. Rearranging this equation yields choice (B).'),
  ('ap-mock-physc-mech-2_q14', 'ap-mock-physc-mech-2', 14, false, 'C', 'Practice Test 2 – Mechanics', 'medium', 'Two projectiles are thrown at a vertical wall with initial velocities and positions as shown. Which of the following comparisons is correct regarding the height of the impact and the time the projectile spends in the air before it hits the wall? Height of impact Time in the air', '["h1 > h2 t1 < t2","h1 = h2 t1 < t2","h1 > h2 t1 = t2","h1 < h2 t1 = t2","The answer cannot be determined because it depends on whether the projectiles hit the wall before or after reaching the peaks of their trajectories."]'::jsonb, '(C) The projectiles hit the wall when their x-positions are equal to the position of the wall. Because both projectiles have the same x- components of velocity, they require the same amount of time to hit the wall. Because projectile 1 has a greater y-component of velocity, v1(t) > v2(t), it hits the surface at a greater height (noting that both projectiles hit the surface after the same amount of time t).'),
  ('ap-mock-physc-mech-2_q15', 'ap-mock-physc-mech-2', 15, false, 'C', 'Practice Test 2 – Mechanics', 'medium', 'A ball is launched horizontally off a cliff and moves through the air subject to both downward gravity and air resistance directed opposite to its velocity. At the instant the ball reaches the peak of a trajectory or moves along a curved path with horizontal velocity to the right, which of the following describes the direction of the net force on the ball?', '["Directly upward","Directly downward","Downward and to the left (opposing velocity and directed toward Earth)","Downward and to the right","Directly to the left"]'::jsonb, 'Gravity exerts a downward force F_g = -m g j. Air resistance opposes the instantaneous motion: if the ball is moving to the right, air resistance exerts a force to the left, F_drag = -F_d i. The net force is F_net = F_g + F_drag, which has components pointing downward and to the left.'),
  ('ap-mock-physc-mech-2_q16', 'ap-mock-physc-mech-2', 16, false, 'A', 'Practice Test 2 – Mechanics', 'medium', 'Referring to the situation described in question 11, at what point is the magnitude of the net force maximized?', '["point A","point B","point C","point D","point E"]'::jsonb, '(A) The frictional force of air resistance is proportional to the object’s velocity and opposite in direction. Thus, the x-component of the frictional force (which in the x-direction equals the net force) is maximized when the x-component of the velocity is the greatest. This occurs at point A, before friction has begun to decrease the magnitude of the x-component of velocity. The y-component of the net force is equal to the force exerted by gravity plus the y-component of the frictional force. The magnitude of this sum is greatest when the two forces point in the same direction, which occurs for points to the left of point C (when the velocity has an upward component, causing a downward component in frictional force). The downward vertical component of the frictional force is greatest at point A (before the y-component of velocity has begun to decrease), so at point A the y-component of the net force is maximized. Because both components of the net force are maximized at point A, the magnitude of the net force is also maximized at point A.'),
  ('ap-mock-physc-mech-2_q17', 'ap-mock-physc-mech-2', 17, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'On a certain planet, a ball is thrown upward with a kinetic energy of 100 J and an angle of elevation of 45°. If the ball has a kinetic energy of 75 J at a height of 10 m, what is the maximum height of its trajectory?', '["10 m","20 m","40 m","60 m","80 m"]'::jsonb, '(B) Consider the equation for conservation of energy between the instant the ball is launched and the instant it reaches its maximum height (at the maximum height, the y-velocity will be zero and the x- velocity will be equal to the original x-velocity, in this case . Therefore, at the peak of the object’s trajectory, half of its total energy (i.e., 50 J) will appear as potential energy. We also know that 25 J is stored as potential energy at a height of 10 m. Because potential energy is proportional to height, the potential energy will equal 50 J, its value at the peak of the trajectory, at a height of 20 m.'),
  ('ap-mock-physc-mech-2_q18', 'ap-mock-physc-mech-2', 18, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A particle moves with speed v around a circle of radius r. What is the period of the particle’s motion?', '["f / 2","f / \\sqrt{2}","T = 2\\pi(v/r)","T = 2\\pi(r/v)","T = r/2\\piv"]'::jsonb, '(D) The only answers that have correct units are (D) and (E). The period is the amount of time it takes for the particle to make one complete cycle, in this case one complete revolution around the circle. The total distance of a cycle is the circumference of the circle, 2\pir, and the speed is v, so the time required for one cycle is t = distance/rate = 2\pir/v.'),
  ('ap-mock-physc-mech-2_q19', 'ap-mock-physc-mech-2', 19, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'Assuming Earth is a sphere of uniform mass density and radius R_E, at what radial distance(s) r from Earth''s center is the acceleration due to gravity equal to g/2 (where g is the surface gravitational acceleration)?', '["r = sqrt(2) R_E only","r = 2 R_E only","r = R_E / 2 only","r = R_E / 4 only","At both r = R_E / 2 (inside Earth) and r = sqrt(2) R_E (outside Earth)"]'::jsonb, 'Inside Earth (r < R_E), only the enclosed mass contributes to gravity: g(r) = g * (r / R_E). Setting g(r) = g/2 yields r = R_E / 2. Outside Earth (r > R_E), g(r) = g * (R_E / r)^2. Setting g(r) = g/2 yields (R_E / r)^2 = 1/2 ==> r = sqrt(2) R_E. Thus, the acceleration equals g/2 at two locations: r = R_E / 2 and r = sqrt(2) R_E.'),
  ('ap-mock-physc-mech-2_q20', 'ap-mock-physc-mech-2', 20, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'Two forces act on a circular mass as shown. A third force is exerted at point P. For this force to ensure static equilibrium,', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","It is impossible for a force exerted at point P to cause static equilibrium."]'::jsonb, '(E) For the net force to be zero, the force at point P must be (pointing downward and to the right). However, this produces a net counterclockwise torque about the center of the object (note that the two forces in the figure exert zero torque about this point). Therefore, it is impossible for a force exerted at point B to produce static equilibrium.'),
  ('ap-mock-physc-mech-2_q21', 'ap-mock-physc-mech-2', 21, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A railroad car is traveling to the right at a speed of 10 m/s relative to the ground. What is the velocity of an automobile relative to the railroad car if the velocity of the automobile relative to the ground is 2 m/s to the left?', '["8 m/s to the right","8 m/s to the left","12 m/s to the right","12 m/s to the left","2 m/s to the left"]'::jsonb, '(D) The velocity of the automobile relative to the ground obeys the formula'),
  ('ap-mock-physc-mech-2_q22', 'ap-mock-physc-mech-2', 22, false, 'C', 'Practice Test 2 – Mechanics', 'medium', 'A block of mass 0.2 kg on a horizontal frictionless surface is attached to a spring of spring constant 200 N/m. The block is pulled 0.8 m from its equilibrium position and released from rest. It then executes simple harmonic motion. What is the maximum elastic potential energy of the system?', '["3 J","6.4 J","64 J","8,000 J","200,000 J"]'::jsonb, '(C) The elastic potential energy is given by .'),
  ('ap-mock-physc-mech-2_q23', 'ap-mock-physc-mech-2', 23, false, 'A', 'Practice Test 2 – Mechanics', 'medium', 'A small ball of mass m attached to a light string of length r swings in a vertical circle. What is the minimum speed the ball must have at the top of the circle so that the string remains taut (tension T >= 0)?', '["sqrt(g r)","sqrt(2 g r)","sqrt(5 g r)","2 sqrt(g r)","1/2 sqrt(g r)"]'::jsonb, 'At the top of the vertical circle, both gravity and tension point downward toward the center: T + m g = m v^2 / r. For the string to remain taut, tension must be non-negative (T >= 0). The critical threshold occurs when T = 0, giving m g = m v^2 / r ==> v = sqrt(g r).'),
  ('ap-mock-physc-mech-2_q24', 'ap-mock-physc-mech-2', 24, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'Consider a spring with a restoring force given by F(x) = −bx3 + cx5. If the potential energy is chosen to be zero at the equilibrium position, which of the following functions gives the elastic potential energy as a function of the spring’s displacement?', '["U(x) = 5cx4 − 3bx2","U(x) = 3bx2 − 5cx4","U(x) = (cx6/6) − (bx4/4)","U(x) = (bx4/4) − (cx6/6)","none of the above"]'::jsonb, '(D) Fx = −dU/dx, so')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-mock-physc-mech-2_q25', 'ap-mock-physc-mech-2', 25, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'If the block shown moves with constant speed v, what form do the horizontal and vertical components of Newton’s second law, respectively, take?', '["F sin \\theta = \\muKmg for both components","F cos \\theta = \\muKFN and FN + F sin \\theta = mg","F sin \\theta = \\muKFN and FN + F cos \\theta = mg","F cos \\theta = \\muKFN and FN = mg + F sin \\theta","F sin \\theta = \\muKFN and FN = mg + F cos \\theta"]'::jsonb, '(B) The free-body diagram is shown below.'),
  ('ap-mock-physc-mech-2_q26', 'ap-mock-physc-mech-2', 26, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'What is the power exerted by the force F in question 21?', '["P = F(sin \\theta)v","P = F(cos \\theta)v","P = −F(sin \\theta)v","P = −F(cos \\theta)v","P = \\muKmgv Questions 23–25 refer to the same situation."]'::jsonb, '(B) P = F ⋅ v = Fǁv = F(cos \theta)v. In words, the power is given by the component of the force parallel to the velocity, +F cos \theta multiplied by the magnitude of the velocity v.'),
  ('ap-mock-physc-mech-2_q27', 'ap-mock-physc-mech-2', 27, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'A horizontal bug of mass m stands at rest on the edge of a horizontal disk of mass M, radius r, and rotational inertia , which is also at rest. At a certain time, the bug starts walking counterclockwise around the rim (when viewed from above) so that it moves with a speed v with respect to the ground. If the disk is free to rotate about its center, what is the resulting angular velocity of the disk (with respect to the ground)?', '["\\omega = mv/Mr","\\omega = 2mv/Mr","\\omega = Mv/2mr","\\omega = Mv/mr","none of the above"]'::jsonb, '(B) Angular momentum is conserved about the axle of the disk (assuming there is no friction in the axle). Because the initial angular momentum about this point is zero, the final angular momentum must also be zero. This requires that the disk rotate in the direction opposite the bug (clockwise) with an angular momentum of equal magnitude: Solving for the magnitude of the angular velocity gives choice (B).'),
  ('ap-mock-physc-mech-2_q28', 'ap-mock-physc-mech-2', 28, false, 'C', 'Practice Test 2 – Mechanics', 'medium', 'In terms of the speed of the bug, v (with respect to the ground), and the magnitude of the angular velocity of the disk, \omega, what is the speed of the bug relative to the disk?', '["(v/r) + \\omega","(v/r) − \\omega","v + r\\omega","v − r\\omega","Zero net change under static equilibrium conditions"]'::jsonb, '(C) Consider, for example, when the bug crosses the +x-axis (setting the origin of the coordinate system at the axle of the disk). The velocity of the bug with respect to the ground is because the bug is moving with speed v counterclockwise. The speed of the point on the disk where the bug stands is (relative to the ground) because the disk is rotating clockwise with angular velocity \omega. The relative velocity of the bug with respect to the disk is given by Although we solved this problem for a particular point in the bug’s motion, because of the rotational symmetry of the disk, the speeds always sum in this manner.'),
  ('ap-mock-physc-mech-2_q29', 'ap-mock-physc-mech-2', 29, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'What is the minimum coefficient of static friction between the bug’s feet and the disk required to keep the bug from sliding off the disk as it walks with constant speed v?', '["mv2/r","v2/rg","(v + \\omegar)2/rg","(v − \\omegar)2/rg","No static friction is needed."]'::jsonb, '(B) The frictional force must provide the centripetal force required to keep the bug moving in circular motion. Recall that Newton’s laws hold only in inertial reference frames, in this case the ground frame. Therefore, we must apply the equation Fcent = mv2/r in the ground frame (note that v is the bug’s speed in this frame of reference). Setting the centripetal force equal to the frictional force gives mv2/r = \musmg. Solving for the coefficient of friction yields choice (B). Note: Why is this static rather than kinetic friction? Although the bug is moving, its feet are not moving with respect to the disk (i.e., the bug’s feet are not slipping as it walks).'),
  ('ap-mock-physc-mech-2_q30', 'ap-mock-physc-mech-2', 30, false, 'C', 'Practice Test 2 – Mechanics', 'medium', 'Two masses m1 and m2 move along a straight line in opposite directions with speeds v1 and v2, respectively. What is the speed of the center of mass of the two-body system?', '["(m1 v1 + m2 v2) / (m1 + m2)","(v1 + v2) / 2","|m1 v1 - m2 v2| / (m1 + m2)","|m1 - m2|(v1 + v2) / (m1 + m2)","sqrt(v1^2 + v2^2)"]'::jsonb, 'Taking the direction of m1 as positive, the velocities are +v1 and -v2. The velocity of the center of mass is v_cm = (m1 v1 - m2 v2) / (m1 + m2). The speed of the center of mass is the absolute value of this velocity: |v_cm| = |m1 v1 - m2 v2| / (m1 + m2).'),
  ('ap-mock-physc-mech-2_q31', 'ap-mock-physc-mech-2', 31, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A force F pushes on two masses lying on a horizontal frictionless surface as shown, causing them to accelerate to the right with magnitude a. Which of the following statements is false?', '["m2 exerts a force of on m1.","The net force on m1 is F − m2a.","The acceleration of the blocks is a = F/(m1 + m2).","The sum of the contact forces exerted by m1 on m2, and vice versa, produce net work on the two-block system.","The net force on m2 is m2a."]'::jsonb, '(D) Choice (D): The force that m1 exerts on m2 is an internal force, so it is balanced by another internal force so that together these internal forces make no contribution to the net force or the net work on the two- block system. (If we were considering the blocks separately, this force would no longer be an internal force.) See Example 3.6 on page 108 for further explanation.'),
  ('ap-mock-physc-mech-2_q32', 'ap-mock-physc-mech-2', 32, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A particle is released from rest at point A. The figure shows the potential energy of the particle as a function of position. If no nonconservative forces are present, which of the following statements is true?', '["The particle oscillates between points B and F.","The particle cannot reach point G.","The particle moves in simple harmonic motion.","The particle experiences no force at points C, D, and E.","The particle’s speed is maximized at point E."]'::jsonb, '(D) The particle oscillates between points A and H (the particle has a total energy of 1 J, so it cannot move beyond these points because that would require having negative kinetic energy). Since point G is within the boundaries of this oscillation, it will indeed reach and pass point G. Because there is no simple linear restoring force [which would be equivalent to an upward-parabolic U(x) curve], the particle does not move in simple harmonic motion. The force, equal to F(x) = −dU/dx, is zero at points C, D, and E because the slope of the function U(x) is zero at these points. The particle’s speed is maximized at point C (not point E), as this is the place where the particle’s potential energy is the lowest (and thus, its kinetic energy is the highest).'),
  ('ap-mock-physc-mech-2_q33', 'ap-mock-physc-mech-2', 33, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'If a rotating object accelerates from rest with an angular acceleration of 2 rad/s2, through what angle will it rotate before a point on its edge a distance 0.5 m from the axle is moving with a speed of 2 m/s?', '["0.5 rad","1 rad","2 rad","4 rad","8 rad"]'::jsonb, '(D) The final angular velocity is \omega = v/r. Using the equation yields Substituting in for all the values given in the problem results in choice (D).'),
  ('ap-mock-physc-mech-2_q34', 'ap-mock-physc-mech-2', 34, false, 'A', 'Practice Test 2 – Mechanics', 'medium', 'Consider the five figures, which show different forces as functions of position. How many of these forces can give rise to simple harmonic motion about the point x = 0?', '["Directly proportional to the parameter (linear scaling)","one","Equal in magnitude with opposite orientation","three","Zero net change under static equilibrium conditions"]'::jsonb, '(A) SHM requires a linear restoring force, which is graphically equivalent to the F (x) curve passing through the x-axis with a negative slope (the x-intercept is the equilibrium of the SHM).'),
  ('ap-mock-physc-mech-2_q35', 'ap-mock-physc-mech-2', 35, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'A particle is subject to a conservative force associated with potential energy function U(x) = alpha x^4 - beta x^2, where alpha and beta are positive constants. At which of the following non-zero positions is the particle in equilibrium (net force F = 0)?', '["x = +/- sqrt(beta / (4 alpha))","x = +/- sqrt(beta / (2 alpha))","x = +/- beta / alpha","x = +/- sqrt(2 beta / alpha)","x = +/- beta / (2 alpha)"]'::jsonb, 'Conservative force is related to potential energy by F(x) = -dU/dx. Differentiating U(x): dU/dx = 4 alpha x^3 - 2 beta x. Setting F(x) = 0 gives 2 x (2 alpha x^2 - beta) = 0. For non-zero equilibrium positions: 2 alpha x^2 = beta ==> x^2 = beta / (2 alpha) ==> x = +/- sqrt(beta / (2 alpha)).'),
  ('ap-mock-physc-mech-2_q36', 'ap-mock-physc-mech-2', 36, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'A block of mass 0.6 kg slides on a horizontal table where the coefficient of kinetic friction is 0.1. If the block is moved 3 m to the left and then 3 m back to its original position, how much work is done by the frictional force?', '["−100.76 J","−3.53 J","0 J","3.53 J","100.76 J"]'::jsonb, '(B) The magnitude of the frictional force is given by Ffr = \mukFN = \mukmg = 0.59 N. The work done by friction is W = −Ffrd, where d is the total displacement, i.e., 6 m. Thus, W = −(0.59)(6) = −3.53 J.'),
  ('ap-mock-physc-mech-2_q37', 'ap-mock-physc-mech-2', 37, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A ball with radius r = 2 m is rolling without slipping along a horizontal surface. If \theta, the angle through which the ball rotates, is given as a function of time by \theta = 4t2, then at time t = 1, what is the linear acceleration of the center of mass of the ball?', '["9,600 m/s2","140 m/s2","40 m/s2","16 m/s2","0.88 m/s2"]'::jsonb, '(D) The angular displacement is proportional to t2; thus, the angular acceleration \alpha is constant and given by the second time derivative of \theta, i.e., \alpha = 8. Rolling without slipping implies that the acceleration a of the center of mass obeys a = r\alpha = (2)(8) = 16 m/s2.'),
  ('ap-mock-physc-mech-2_q38', 'ap-mock-physc-mech-2', 38, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'Referring to the ball introduced in question 33, what is the speed of a point on the very top of the ball at time t = 1 relative to the horizontal surface?', '["6 m/s","12 m/s","24 m/s","32 m/s","96 m/s"]'::jsonb, '(D) Differentiating once to calculate the angular velocity from the angular position gives \omega = 8t. The speed at the top of the ball is given by the equation v = 2r\omega (for further explanation, see Chapter 8). Substituting in numbers yields choice (D).'),
  ('ap-mock-physc-mech-2_q39', 'ap-mock-physc-mech-2', 39, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'An asteroid moving at a constant velocity in space suddenly explodes. How many of the following quantities remain constant throughout and after the explosion? I. the kinetic energy II. the momentum III. the position of the center of mass IV. the velocity of the center of mass V. the angular momentum of the asteroid system', '["none","one","two","three","four Free-Response Questions DIRECTIONS: Use separate sheets of paper to write down your answers to the free-response questions. You may refer to the formula sheet in the Appendix (pages 575-578). Mechanics Mechanics I A skier of mass m is standing on a slope with an angle of elevation \\theta. After being given a tiny nudge, the skier slides down the slope, grabs a rope at the bottom of the slope, and swings up to a height h, as shown. The coefficient of kinetic friction between the skier and the slope is \\muk. (a) What is the minimum coefficient of static friction required so that the skier is initially at rest at the top of the slope without using his poles? (b) How much energy is lost while the skier slides down the incline? Express your answer in terms of m, g, h, d, and \\theta. (c) What is the coefficient of kinetic friction? Express your answer in terms of h, d, and \\theta. Mechanics II A mass m is attached to a string of length l and released when the string is horizontal, causing the mass to fall in a circular path as shown. At the time that the mass has fallen through the angle \\theta, determine the following (in terms of m, l, g, and \\theta): (a) the speed of the object (b) the magnitude of the centripetal acceleration (c) the magnitude of the tangential acceleration (d) the magnitude of the tension force (e) When using a photogate, the speed of the mass is measured when it passes through the bottom of the circle. The experiment is repeated for strings of different lengths, and the following data are obtained: What quantities should be plotted on the grid to obtain a linear relation between the speed of the mass and the length of the string? (f) Plot the data. Scale and label the axes, including units. After fitting the data to a straight line, check how well the experimental results agree with the theoretical prediction of part (a). Mechanics III A mass m is connected to an axle by a massless rod of length l. The mass m feels a retarding force due to air resistance given by F = −b\\omega, where b is a positive constant with units of kg\\cdot m/s. The mass rotates in the xy-plane, with an initial angular speed \\omega0 at time t = 0 as shown. (a) What is the initial angular momentum of mass m about the z-axis? (b) What is the torque due to air resistance? (c) What is the initial angular acceleration of the mass? Multiple-Choice Questions DIRECTIONS: Each multiple-choice question is followed by five answer choices. For each question, choose the best answer and fill in the corresponding circle on the answer sheet. You may refer to the formula sheet in the Appendix (pages 575-578). Electricity and Magnetism"]'::jsonb, '(D) There is no external force, so the momentum and the velocity of the center of mass remain constant. Because the center of mass continues to move with its original velocity, the position of the center of mass does not remain constant but instead moves at constant velocity. Because there is no external torque, the angular momentum of the asteroid system (about any stationary reference point) remains constant. The kinetic energy does not remain constant during the explosion but rather increases dramatically as the asteroid explodes: Presumably some source of nonmechanical energy (e.g., chemical energy) was quickly converted to mechanical energy, resulting in the explosion. Free-Response Mechanics I (a) The free-body diagram for the skier at rest on the slope appears in the figure. If the skier is at rest, the acceleration is zero, and thus the net force in each of the directions of the tilted coordinate system is zero: Finally, the minimum coefficient of static friction is Note: If the coefficient of static friction were larger, the static frictional force would be the same (it would simply be less than the maximum possible frictional force for that coefficient of friction). (b) We apply the law of conservation of energy. Setting y = 0 at the bottom of the incline and designating the final position where the skier has risen to a height h swinging on the rope, (c) The change in the mechanical energy is equal to the work done by nonconservative forces, in this case kinetic friction: Symbolic answer check: (1) If dsin \theta = h, then no energy is lost because the skier rises to the initial height. Alternatively, the greater the loss in energy, the greater the coefficient of friction. (2) The coefficient of friction is a dimensionless number, as it must be. Mechanics II (a) By conservation of energy (whereby the loss in gravitational potential energy equals the gain in kinetic energy): Symbolic answer check: (1) The units are correct. (2) Velocity increases with increasing gravitational force, increasing length, and increasing \theta, all of which make sense. (b) (c) At this point we need the free-body diagram shown. The net force in the tangential direction is mg cos \theta, so the acceleration in the tangential direction is g cos \theta. Note that we do not have to know the value of the tension in order to compute the tangential acceleration or net force. (d) Referring to the free-body diagram (and noting that the y-coordinate in this diagram is radial), (e) From part (a), you know that . So you should plot v2 versus ℓ. Note that at the bottom of the circle \theta = \pi/2 and sin \theta = 1. (f) The plot is shown below. Determine the slope of the fitted line: From part (a), you expect the slope to be 2g = 19.6 m/s2.'),
  ('ap-mock-physc-mech-3_q1', 'ap-mock-physc-mech-3', 1, false, 'B', 'AP Physics C: Mechanics', 'medium', '<p class="image"><img alt="Images" class="q-img" src="images/t0301-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindentt"><strong>Time:</strong> 45 minutes. You may refer to the constants sheet and the equation sheet, both of which are found in the appendix. You may use a calculator.</p><p class="ques"><strong><a href="ch19t.xhtml#rch19p_1" id="ch19p_1">1.</a></strong> An object moves along the positive $x$-axis. The net force on the object as a function of time $t$ measured in seconds is given in newtons by the function $F$($t$) = 3$t^{2} +t$ + 2. What is the impulse delivered to the object during the first second of motion?</p>', '["<p>4.0 N⋅s</p>","<p>3.5 N⋅s</p>","<p>0 N⋅s</p>","<p>7.0 N⋅s</p>","<p>6.0 N⋅s</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_1" id="rch19p_1">1.</a></strong> <strong>B</strong>—Impulse is the integral of force with respect to time. That’s $t^{3} +t^{2}$/2 + 2$t$, evaluated from 0 to 1 second: 1 + ½ + 2 = 3.5 N⋅s.</p>'),
  ('ap-mock-physc-mech-3_q2', 'ap-mock-physc-mech-3', 2, false, 'E', 'AP Physics C: Mechanics', 'medium', '<p class="ques"><strong><a href="ch19t.xhtml#rch19p_2" id="ch19p_2">2.</a></strong> A cart moves along a straight track. Its position $x$ as a function of time is given in meters by the equation $x$ = 2$t^{3} +t^{2}$ – 2$t$. What is the cart’s acceleration at time $t$ = 4 s?</p>', '["<p>102 m/$s^{2}$</p>","<p>10 m/$s^{2}$</p>","<p>133 m/$s^{2}$</p>","<p>12 m/$s^{2}$</p>","<p>50 m/$s^{2}$</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_2" id="rch19p_2">2.</a></strong> <strong>E—</strong>Acceleration is the second time derivative of position. The second derivative of the given function is $a$ = 12$t$ + 2. Plug in $t$ = 4 s to get an acceleration of 50 m/$s^{2}$.</p>'),
  ('ap-mock-physc-mech-3_q3', 'ap-mock-physc-mech-3', 3, false, 'D', 'AP Physics C: Mechanics', 'medium', '<p class="image"><img alt="Images" class="q-img" src="images/f0303-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19t.xhtml#rch19p_3" id="ch19p_3">3.</a></strong> An object of mass $m$ is attached to a vertical spring, as shown above. When the string is unstretched, it is of length $L$. When the object is gently attached and allowed to hang from rest, the string is of length $L +x$. Now the object is attached, released from rest while the spring is at its unstretched length $L$, and allowed to oscillate. What is the maximum length of the spring during the oscillations?</p>', '["<p>$L$ + <img alt=\"Images\" class=\"q-img\" src=\"images/s2x.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p>2$L$ + 2$x$</p>","<p>2$L$ + <img alt=\"Images\" class=\"q-img\" src=\"images/s2x.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p>$L$ + 2$x$</p>","<p>$L$ + 4$x$</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_3" id="rch19p_3">3.</a></strong> <strong>D</strong>—The equilibrium position is the midpoint of any oscillations. So $L +x$ is the equilibrium position. The object was released a distance $x$ above the equilibrium position, meaning $x$ is the amplitude of the oscillations. The spring will reach a distance $x$ both above and below the equilibrium, meaning the spring will oscillate between a length $L$ and ($L +x$) $+x$. That’s $L$ + 2$x$ as the maximum length.</p>'),
  ('ap-mock-physc-mech-3_q4', 'ap-mock-physc-mech-3', 4, false, 'C', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="image"><img alt="Images" class="q-img" src="images/f0303-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Questions 4 and 5: Two carts move along a smooth surface as shown above. Cart A of mass 3.1 kg moves west with speed 1.2 m/s. Cart B of mass 1.3 kg moves north with speed 2.2 m/s. The carts collide and stick together, moving at angle $\theta$ above west.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_4" id="ch19p_4">4.</a></strong> What is the speed of the center of mass of the two-cart system before collision?</p>', '["<p>2.5 m/s</p>","<p>3.4 m/s</p>","<p>1.1 m/s</p>","<p>1.6 m/s</p>","<p>2.3 m/s</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_4" id="rch19p_4">4.</a></strong> <strong>C—</strong>Use conservation of momentum to find the total momentum before collision. Momentum is mass times velocity. For cart A before collision that’s 3.72 N⋅s west; for cart B before collision that’s 2.86 N⋅s north. The total momentum before collision is the Pythagorean sum of these—because momentum is a vector, direction matters. So total momentum before collision is 4.69 N⋅s at the angle $\theta$. Conservation of momentum means that this is also the total momentum after collision. Since the carts stick together, just divide this by the 4.4 kg mass to get the speed after collision of 1.07 m/s. And since no external forces act on the two-cart system, its center of mass always moves at this speed. So answer is closest to C.</p>'),
  ('ap-mock-physc-mech-3_q5', 'ap-mock-physc-mech-3', 5, false, 'B', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="image"><img alt="Images" class="q-img" src="images/f0303-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Questions 4 and 5: Two carts move along a smooth surface as shown above. Cart A of mass 3.1 kg moves west with speed 1.2 m/s. Cart B of mass 1.3 kg moves north with speed 2.2 m/s. The carts collide and stick together, moving at angle $\theta$ above west.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_5" id="ch19p_5">5.</a></strong> Which of the following methods will calculate the angle $\theta$?</p>', '["<p>Divide cart B’s speed by cart A’s speed, and take the inverse tangent of the result.</p>","<p>Calculate the momentum of each cart by multiplying mass times speed. Then divide cart B’s momentum by cart A’s momentum, and take the inverse tangent of the result.</p>","<p>Calculate the kinetic energy of each cart by multiplying ½ by its mass times its speed squared. Then divide the cart B’s kinetic energy by cart A’s kinetic energy, and take the inverse tangent of the result.</p>","<p>Divide the square of cart B’s speed by the square of cart A’s speed, and take the inverse tangent of the result.</p>","<p>Divide cart B’s mass by cart A’s mass, and take the inverse tangent of the result.</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_5" id="rch19p_5">5.</a></strong> <strong>B—</strong>Momentum is a vector and is conserved separately in each direction in a collision. The total momentum on the vertical axis is just cart B’s momentum, and on the horizontal axis, just cart A’s momentum. The inverse tangent of these momentum components gives the direction of the total momentum vector. And the direction of a velocity—of movement—is always the same as the direction of momentum. (You can’t just use the inverse tangent on the velocity components, because velocity isn’t conserved in a collision!)</p>'),
  ('ap-mock-physc-mech-3_q6', 'ap-mock-physc-mech-3', 6, false, 'C', 'AP Physics C: Mechanics', 'medium', '<p class="ques"><strong><a href="ch19t.xhtml#rch19p_6" id="ch19p_6">6.</a></strong> A pendulum and a spring both oscillate in harmonic motion with small amplitude. Which of the following shows correct graphs of how the period $T$ of the harmonic motion depends on the mass $m$ of the object in oscillation for the pendulum and the spring?</p><p class="image"><img alt="Images" class="q-img" src="images/f0304-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Graph A: Pendulum T increases linearly with m; Spring T is independent of m","Graph B: Pendulum T decreases inversely with m; Spring T increases linearly with m","Graph C: Pendulum T is horizontal (independent of m); Spring T increases as \\sqrt{m}","Graph D: Pendulum T increases as m^2; Spring T is horizontal","Graph E: Pendulum T decreases as 1/\\sqrt{m}; Spring T increases as m^2"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_6" id="rch19p_6">6.</a></strong> <strong>C—</strong>The period of a pendulum is <img alt="Images" class="q-img" src="images/f0330-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>; mass is irrelevant, so the graph of period vs. mass is a horizontal line. The period of an object on a spring is <img alt="Images" class="q-img" src="images/f0330-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>, which depends on the square root of $m$, as in <strong>C</strong>.</p>'),
  ('ap-mock-physc-mech-3_q7', 'ap-mock-physc-mech-3', 7, false, 'A', 'AP Physics C: Mechanics', 'medium', '<p class="ques"><strong><a href="ch19t.xhtml#rch19p_7" id="ch19p_7">7.</a></strong> Cart A is initially moving to the right toward stationary cart B. The carts collide and bounce off one another. Which of the following is correct about whether the horizontal linear momentum and the kinetic energy of the two-cart system are conserved in the collision?</p>', '["<p>Linear momentum must be conserved. Kinetic energy may possibly be conserved.</p>","<p>Linear momentum may possibly be conserved. Kinetic energy must be conserved.</p>","<p>Linear momentum may possibly be conserved. Kinetic energy may possibly be conserved.</p>","<p>Linear momentum must be conserved. Kinetic energy must be conserved.</p>","<p>Linear momentum must be conserved. Kinetic energy must not be conserved.</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_7" id="rch19p_7">7.</a></strong> <strong>A—</strong>Linear momentum is conserved in any collision because there are no external forces acting on the two-cart system. By definition, elastic collisions conserve kinetic energy. It’s true that for a collision to be elastic, the carts must bounce, but just because carts bounce doesn’t mean the collision <em>must</em> be elastic.</p>'),
  ('ap-mock-physc-mech-3_q8', 'ap-mock-physc-mech-3', 8, false, 'B', 'AP Physics C: Mechanics', 'medium', '<p class="ques"><strong><a href="ch19t.xhtml#rch19p_8" id="ch19p_8">8.</a></strong> A block slides down a frictionless ramp on Earth’s surface. The ramp makes an angle $\theta$ above the horizontal, and the block’s acceleration down the incline is $a$. Now, the block slides down the same ramp near a different planet’s surface. The ramp still makes an angle $\theta$ above the horizontal. This different planet has twice the density of Earth but the same radius. What is the acceleration of the block sliding down the ramp on the different planet?</p>', '["<p>(1/2)$a$</p>","<p>2$a$</p>","<p>$a$</p>","<p>(1/4)$a$</p>","<p>4$a$</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_8" id="rch19p_8">8.</a></strong> <strong>B</strong>—The unbalanced force down the incline is <em>mg</em> sin $\theta$. Newton’s second law shows that the acceleration is then $g$ sin $\theta$. So however $g$ changes, that’s how the acceleration changes. The formula for the gravitational field near a planet is $g$ = <em>GM</em>/$r^{2}$. But we’re given density, not mass! Density is mass per volume. So multiply numerator and denominator by $r$ to get $g$ = <em>GMr</em>/$r^{3}$. Now <em>M/r</em><sup>3</sup> is density . . . so $g$ = <em>G(density)r</em>. The universal gravitation constant $G$ can’t change, the problem says the radius $r$ doesn’t change, but the density doubles—so the whole term for $g$ doubles. And so does the acceleration.</p>'),
  ('ap-mock-physc-mech-3_q9', 'ap-mock-physc-mech-3', 9, false, 'B', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="image"><img alt="Images" class="q-img" src="images/f0305-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Questions 9–11: A particle moves clockwise in a horizontal circle of radius 2.0 m, as shown above. At the moment in which the particle is at the position shown, its speed is 3.0 m/s, and its speed is increasing by 2.5 m/s per second.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_9" id="ch19p_9">9.</a></strong> Which of the following vectors could represent the direction of the particle’s instantaneous velocity at the position shown?</p>', '["<p><img alt=\"Images\" class=\"q-img\" src=\"images/larrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/darrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/1arrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/uarrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/2arrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_9" id="rch19p_9">9.</a></strong> <strong>B—</strong>The instantaneous velocity is in the direction the object is moving at this instant. That’s straight down the page.</p>'),
  ('ap-mock-physc-mech-3_q10', 'ap-mock-physc-mech-3', 10, false, 'E', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="image"><img alt="Images" class="q-img" src="images/f0305-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Questions 9–11: A particle moves clockwise in a horizontal circle of radius 2.0 m, as shown above. At the moment in which the particle is at the position shown, its speed is 3.0 m/s, and its speed is increasing by 2.5 m/s per second.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_10" id="ch19p_10">10.</a></strong> Which of the following vectors could represent the direction of the net force on the particle at the position shown?</p>', '["<p><img alt=\"Images\" class=\"q-img\" src=\"images/larrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/darrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/1arrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/uarrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/2arrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_10" id="rch19p_10">10.</a></strong> <strong>E—</strong>The net force is in the direction of acceleration. The acceleration has two components here: one toward the center (the “centripetal” acceleration) and another in the direction of motion because the particle is speeding up (the “tangential” acceleration). So the acceleration, and the net force, points somewhat left toward the center and somewhat down.</p>'),
  ('ap-mock-physc-mech-3_q11', 'ap-mock-physc-mech-3', 11, false, 'D', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="image"><img alt="Images" class="q-img" src="images/f0305-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Questions 9–11: A particle moves clockwise in a horizontal circle of radius 2.0 m, as shown above. At the moment in which the particle is at the position shown, its speed is 3.0 m/s, and its speed is increasing by 2.5 m/s per second.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_11" id="ch19p_11">11.</a></strong> What is the magnitude of the particle’s instantaneous acceleration at the position shown?</p>', '["<p>3.6 m/$s^{2}$</p>","<p>1.5 m/$s^{2}$</p>","<p>4.5 m/$s^{2}$</p>","<p>5.1 m/$s^{2}$</p>","<p>2.5 m/$s^{2}$</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_11" id="rch19p_11">11.</a></strong> <strong>D—</strong>The acceleration has two components, which must be added using the Pythagorean theorem. The centripetal component is $v^{2}$/$r$, which is (3 m/s)<sup>2</sup>/(2 m) = 4.5 m/$s^{2}$. The tangential component is given as 2.5 m/$s^{2}$. So add 4.5<sup>2</sup> + 2.5<sup>2</sup> and take the square root to get 5.1 m/$s^{2}$.</p>'),
  ('ap-mock-physc-mech-3_q12', 'ap-mock-physc-mech-3', 12, false, 'D', 'AP Physics C: Mechanics', 'medium', '<p class="image"><img alt="Images" class="q-img" src="images/f0305-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19t.xhtml#rch19p_12" id="ch19p_12">12.</a></strong> Two blocks move across a rough table at constant speed. Friction is NOT negligible on any surface. The bottom block is pulled to the right with force $F$. Which of the following could indicate the direction of the total force of the bottom block on the top block?</p>', '["<p><img alt=\"Images\" class=\"q-img\" src=\"images/rarrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/larrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/1arrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/uarrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/3arrow.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_12" id="rch19p_12">12.</a></strong> <strong>D</strong>—The blocks move at constant speed and so experience balanced forces both vertically and horizontally. Vertically, the force of the bottom block on the top block has to balance the top block’s weight—and so has an upward component. Horizontally, the bottom block can’t exert a force on the top block, because there’s no other object to exert a balancing force. Thus no horizontal forces can act on the top block at all.</p>'),
  ('ap-mock-physc-mech-3_q13', 'ap-mock-physc-mech-3', 13, false, 'E', 'AP Physics C: Mechanics', 'medium', '<p class="image"><img alt="Images" class="q-img" src="images/f0306-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19t.xhtml#rch19p_13" id="ch19p_13">13.</a></strong> Three stones are thrown from a cliff with velocity vectors $v_{A}$, $v_{B}$, and $v_{C}$. The magnitude of the initial velocity for each stone is the same, but the directions of initial velocity are shown in the diagram. Which of the following correctly ranks the stones according to their speed upon hitting the level ground below the cliff, and by the magnitude of their vertical components of velocity upon hitting the ground?</p><p class="image"><img alt="Images" class="q-img" src="images/f0306-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="image"><img alt="Images" class="q-img" src="images/f0306-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Speed: v_A > v_B > v_C; Vertical Velocity: v_{yA} > v_{yB} > v_{yC}","Speed: v_A > v_B > v_C; Vertical Velocity: v_{yA} = v_{yB} = v_{yC}","Speed: v_A = v_B = v_C; Vertical Velocity: v_{yA} = v_{yB} = v_{yC}","Speed: v_A < v_B < v_C; Vertical Velocity: v_{yA} < v_{yB} < v_{yC}","Speed: v_A = v_B = v_C; Vertical Velocity: v_{yA} > v_{yB} > v_{yC}"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_13" id="rch19p_13">13.</a></strong> <strong>E</strong>—For the magnitude of vertical velocity, start with the vertical component of initial velocity—A’s is largest, B’s is next largest, C’s is zero. Look at which goes highest: Kinematics equations simplify to $x = v^{2}$/2$a$ for final speed of zero, so the stone with the greatest initial vertical speed goes highest. Similarly, the one that goes highest hits the ground with greatest vertical speed. So the <em>vertical</em> velocity at ground is ranked A &gt; B &gt; C. As for speed at ground, it’s easiest to see this through energy conservation. All three rocks gain the same potential energy because they’re at the same vertical height from the ground. All three rocks start with the same initial kinetic energy because their speeds are the same. So the blocks must end up with the same kinetic energy as each other at the bottom, meaning also the same speed.</p>'),
  ('ap-mock-physc-mech-3_q14', 'ap-mock-physc-mech-3', 14, false, 'E', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 14–16: An object of mass $m$ is connected to a string of length $L$. The string is pulled back to an angle $θ_{1}$ and released from rest at position 1. Air resistance is NOT negligible. When the string is vertical, the object moves left. The object comes to rest again at position 3 when the string is at angle $θ_{3}$.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_14" id="ch19p_14">14.</a></strong> Which of the following is a correct expression for the work done by the air on the object between positions 1 and 2?</p>', '["<p>½<em>mv</em><sub>2</sub><sup>2</sup></p>","<p><em>mgL</em>$θ_{3}$</p>","<p>½<em>mv</em><sub>2</sub><sup>2</sup> - <em>mgL</em>$θ_{3}$</p>","<p>½<em>mv</em><sub>2</sub><sup>2</sup> - <em>mgL</em>$θ_{1}$</p>","<p><em>mgL</em>$θ_{3}$ - <em>mgL</em>$θ_{1}$</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_14" id="rch19p_14">14.</a></strong> <strong>E—</strong>From position 1 to 2, the mechanical energy goes from all potential to all kinetic. Work is done by the air to reduce this mechanical energy. The reduction in mechanical energy is the difference between the kinetic energy at the bottom (½<em>mv</em><sub>2</sub><sup>2</sup>) and the potential energy at the top (<em>mgLθ</em><sub>1</sub>).</p>'),
  ('ap-mock-physc-mech-3_q15', 'ap-mock-physc-mech-3', 15, false, 'E', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 14–16: An object of mass $m$ is connected to a string of length $L$. The string is pulled back to an angle $θ_{1}$ and released from rest at position 1. Air resistance is NOT negligible. When the string is vertical, the object moves left. The object comes to rest again at position 3 when the string is at angle $θ_{3}$.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_15" id="ch19p_15">15.</a></strong> Is the angle $θ_{3}$ greater than, less than, or equal to $θ_{1}$?</p>', '["<p>$θ_{3}$ is greater than ½$θ_{1}$.</p>","<p>$θ_{3}$ is equal to half of $θ_{1}$.</p>","<p>$θ_{3}$ is less than ½$θ_{1}$.</p>","<p>The answer cannot be determined, but could be determined if we knew whether the force of air resistance were proportional to $v$ or $v^{2}$.</p>","<p>The answer cannot be determined, even if we knew whether the force of air resistance were proportional to $v$ or $v^{2}$.</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_15" id="rch19p_15">15.</a></strong> <strong>E—</strong>If there’s a teeny bit of air resistance, then mechanical energy is almost conserved, and $θ_{3}$ is almost equal to $θ_{1}$. If there’s a lot of air resistance, then mechanical energy is barely conserved at all, and $θ_{3}$ is nearly zero. The form of the air resistance function doesn’t matter; the pure amount of work done by air resistance matters. We don’t know anything about that.</p>'),
  ('ap-mock-physc-mech-3_q16', 'ap-mock-physc-mech-3', 16, false, 'B', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 14–16: An object of mass $m$ is connected to a string of length $L$. The string is pulled back to an angle $θ_{1}$ and released from rest at position 1. Air resistance is NOT negligible. When the string is vertical, the object moves left. The object comes to rest again at position 3 when the string is at angle $θ_{3}$.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_16" id="ch19p_16">16.</a></strong> Now consider that the force of air resistance is equal to <em>cv</em>. Which of the following is a differential equation that could be used to solve for the angle $\theta$ as a function of time while the string is between angles $θ_{1}$ and $θ_{2}$?</p>', '["<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0307-01.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0307-02.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0307-03.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0307-04.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0307-05.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_16" id="rch19p_16">16.</a></strong> <strong>B—</strong>The forces in the direction of the object’s motion at any position have components <em>mg</em> sin $\theta$ along the object’s path and <em>cv</em> against the object’s path. So the net force is <em>mg</em> sin $\theta$ − <em>cv</em>. Set this equal to mass times acceleration, where acceleration is the second derivative of position. But we don’t want the derivative of the angle $\theta$, we want the derivative of the distance along the arc. That’s <em>Lθ</em>.</p>'),
  ('ap-mock-physc-mech-3_q17', 'ap-mock-physc-mech-3', 17, false, 'C', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 17–18: A cart moves along a straight road according to the velocity-time graph shown above.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_17" id="ch19p_17">17.</a></strong> What is the average acceleration of this car between time 0 and time 10 s?</p>', '["<p>+0.3 m/$s^{2}$</p>","<p>0.0 m/$s^{2}$</p>","<p>+0.6 m/$s^{2}$</p>","<p>+1.0 m/$s^{2}$</p>","<p>+3.0 m/$s^{2}$</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_17" id="rch19p_17">17.</a></strong> <strong>C—</strong>Acceleration is the slope of the velocity-time graph. “Average” acceleration would be the slope from the beginning to the end of the graph, disregarding what’s in between. That’s the slope from (0, −3) to (10, 3) which is 6/10 = 0.6 m/$s^{2}$.</p>'),
  ('ap-mock-physc-mech-3_q18', 'ap-mock-physc-mech-3', 18, false, 'A', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 17–18: A cart moves along a straight road according to the velocity-time graph shown above.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_18" id="ch19p_18">18.</a></strong> What is the average velocity of this car between time 0 and time 10 s?</p>', '["<p>1.2 m/s</p>","<p>24 m/s</p>","<p>12 m/s</p>","<p>2.4 m/s</p>","<p>1.0 m/s</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_18" id="rch19p_18">18.</a></strong> <strong>A—</strong>Average velocity is defined as displacement divided by time interval. Displacement is found from the area under a velocity-time graph. Here, the areas below and above the $t$-axis in the first 6 seconds cancel. The remaining area is the rectangle (4 s)(3 m/s) = 12 m. Divide by the time interval of 10 s to get 1.2 m/s.</p>'),
  ('ap-mock-physc-mech-3_q19', 'ap-mock-physc-mech-3', 19, false, 'D', 'AP Physics C: Mechanics', 'medium', '<p class="image"><img alt="Images" class="q-img" src="images/f0307-06.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19t.xhtml#rch19p_19" id="ch19p_19">19.</a></strong> Car A and Car B start at the same position as each other at time $t$ = 0, then move according to the velocity $v$ vs. time graphs above. How far apart are the cars at time $t$ = 4 s?</p>', '["<p>10 m</p>","<p>24 m</p>","<p>8 m</p>","<p>12 m</p>","<p>4 m</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_19" id="rch19p_19">19.</a></strong> <strong>D—</strong>The distance traveled by each car is found by taking the area under the graph. That’s 8 m for Car A and 4 m for Car B. Car A’s graph is above the horizontal axis, while car B’s graph is below the horizontal axis; this means the cars move in different directions. Thus they end up 12 m apart.</p>'),
  ('ap-mock-physc-mech-3_q20', 'ap-mock-physc-mech-3', 20, false, 'E', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 20–22: A string of length $L$ is attached to an object of unknown mass. The string is pulled back to a small unknown angle and released from rest. An astronaut takes this apparatus to the surface of Planet X, where the gravitational field is 4.9 N/kg.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_20" id="ch19p_20">20.</a></strong> The time for the object to first reach the vertical position on Earth is $t_{e}$. On the surface of Planet X, what is the time for the object to first reach the vertical position?</p>', '["<p>$t_{e}$</p>","<p>2$t_{e}$</p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0307-07.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p>4$t_{e}$</p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0307-08.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_20" id="rch19p_20">20.</a></strong> <strong>E—</strong>The time we’re talking about is ¼ of a period. The period of a pendulum equation has $g$ in the denominator and under the square root. The gravitational field on Planet X is ½ that of Earth, so the period of the pendulum there is 1/(1/<img alt="Images" class="q-img" src="images/root2.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>) times the period on Earth; that’s the same thing as <img alt="Images" class="q-img" src="images/root2.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/> times the period on Earth.</p>'),
  ('ap-mock-physc-mech-3_q21', 'ap-mock-physc-mech-3', 21, false, 'C', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 20–22: A string of length $L$ is attached to an object of unknown mass. The string is pulled back to a small unknown angle and released from rest. An astronaut takes this apparatus to the surface of Planet X, where the gravitational field is 4.9 N/kg.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_21" id="ch19p_21">21.</a></strong> Let the maximum speed of the object on Earth be $v_{e}$. What is the maximum speed of the object on Planet X?</p>', '["<p>$v_{e}$</p>","<p>2$v_{e}$</p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0308-01.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p>4$v_{e}$</p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0308-02.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_21" id="rch19p_21">21.</a></strong> <strong>C—</strong>The maximum speed comes from energy conservation: the gravitational energy at the top is equal to the kinetic energy at the bottom, <em>mgh</em> = ½<em>mv</em><sup>2</sup>. Solve for $v$ to get a maximum speed of <img alt="Images" class="q-img" src="images/r-331.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>. Here $g$ is in the numerator and under the square root. Since the gravitational field on Planet X is half that of Earth, the max speed is <img alt="Images" class="q-img" src="images/f0331-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/> times the speed on Earth.</p>'),
  ('ap-mock-physc-mech-3_q22', 'ap-mock-physc-mech-3', 22, false, 'D', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 20–22: A string of length $L$ is attached to an object of unknown mass. The string is pulled back to a small unknown angle and released from rest. An astronaut takes this apparatus to the surface of Planet X, where the gravitational field is 4.9 N/kg.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_22" id="ch19p_22">22.</a></strong> What measurements in addition to the string length $L$ must be measured to determine an experimental value for $g$ on this planet?</p><p class="roman1t">I. The time for the object to pass through the vertical position two consecutive times</p><p class="roman2">II. The speed of the object as it passes the vertical position</p><p class="roman3">III. The mass of the object</p>', '["<p>II only</p>","<p>II and III</p>","<p>III only</p>","<p>I only</p>","<p>I and III</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_22" id="rch19p_22">22.</a></strong> <strong>D—</strong>The period of a pendulum depends only on the length of the pendulum and the gravitational field. Choice I is, in fact, the period; so that and $L$ can be used to solve for $g$. Choice II doesn’t work because the speed as shown in the previous problem depends on the vertical height $h$ from which the ball was released, not the string length; to find $h$ we’d also need the angle from which the pendulum was released. And the mass is not in the period equation and cancels from the max-speed equation, so it is not useful.</p>'),
  ('ap-mock-physc-mech-3_q23', 'ap-mock-physc-mech-3', 23, false, 'B', 'AP Physics C: Mechanics', 'medium', '<p class="image"><img alt="Images" class="q-img" src="images/f0308-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="ques"><strong><a href="ch19t.xhtml#rch19p_23" id="ch19p_23">23.</a></strong> A ball is dropped from a skyscraper. Between the time of the drop and the time at which the ball reaches terminal velocity, which of the following is true about the magnitudes of the ball’s velocity and acceleration vectors?</p>', '["<p>velocity remains constant while acceleration remains constant</p>","<p>velocity increases while acceleration decreases</p>","<p>velocity decreases while acceleration decreases</p>","<p>velocity increases while acceleration remains constant</p>","<p>velocity remains constant while acceleration decreases</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_23" id="rch19p_23">23.</a></strong> <strong>B—</strong>Terminal velocity is when the ball falls at constant speed because the forces of gravity and air resistance balance. Before reaching terminal velocity, though, the ball had to speed up from rest to reach that speed—so velocity increased. And acceleration is the change in speed every second. Initially the ball was changing speed; once the ball hit terminal velocity, the speed was not changing. The acceleration was nonzero and then zero. So acceleration decreased.</p>'),
  ('ap-mock-physc-mech-3_q24', 'ap-mock-physc-mech-3', 24, false, 'C', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="image"><img alt="Images" class="q-img" src="images/f0309-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Questions 24 and 25: A small dart of mass $M_{2}$ is fired into a hanging object of mass $M_{1}$, which is initially at rest. The dart sticks, and the combined dart-object system moves to a maximum vertical height $h$ above their initial position.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_24" id="ch19p_24">24.</a></strong> Which of the following is a correct expression for the speed of the combined dart-object system immediately after collision?</p>', '["<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0309-02.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0309-03.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0309-04.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0309-05.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0309-06.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_24" id="rch19p_24">24.</a></strong> <strong>C—</strong>After the collision, the dart-block system swings to the maximum height $h$. Use energy conservation: ($M_{1} +M_{2}$)<em>gh</em> = ½($M_{1} +M_{2}$)$v^{2}$. Solve for $v$, and the masses cancel.</p>'),
  ('ap-mock-physc-mech-3_q25', 'ap-mock-physc-mech-3', 25, false, 'C', 'AP Physics C: Mechanics', 'medium', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="image"><img alt="Images" class="q-img" src="images/f0309-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Questions 24 and 25: A small dart of mass $M_{2}$ is fired into a hanging object of mass $M_{1}$, which is initially at rest. The dart sticks, and the combined dart-object system moves to a maximum vertical height $h$ above their initial position.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_25" id="ch19p_25">25.</a></strong> Which of the following is a correct expression for the speed of the dart before the collision?</p>', '["<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0309-07.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0309-08.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0309-09.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0309-10.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0309-11.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_25" id="rch19p_25">25.</a></strong> <strong>C—</strong>Now use conservation of total momentum right before and after the collision: $M_{2} v$ + 0 = ($M_{1} +M_{2}$)<img alt="Images" class="q-img" src="images/f0332-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>, using the result from the previous question for the speed of the blocks after collision. Solve for $v$ to get choice C.</p>'),
  ('ap-mock-physc-mech-3_q26', 'ap-mock-physc-mech-3', 26, false, 'A', 'AP Physics C: Mechanics', 'hard', '<p class="ques"><strong><a href="ch19t.xhtml#rch19p_26" id="ch19p_26">26.</a></strong> A hoop of mass $m$ is released from rest at the top of a ramp, a vertical distance $h$ above the bottom of the ramp. The hoop rolls without slipping to the bottom of the ramp, where it has speed $v$ and total mechanical energy $E$. Next, a solid disk, also of mass $m$, <em></em>is released from the same position, and likewise rolls without slipping. Which of the following is correct about the speed and mechanical energy of the disk compared to the hoop?</p><p class="image"><img alt="Images" class="q-img" src="images/f0309-12.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Speed: Disk is faster than hoop; Mechanical Energy: Disk equals hoop","Speed: Disk is faster than hoop; Mechanical Energy: Disk is greater than hoop","Speed: Disk equals hoop; Mechanical Energy: Disk equals hoop","Speed: Disk is slower than hoop; Mechanical Energy: Disk equals hoop","Speed: Disk is slower than hoop; Mechanical Energy: Disk is less than hoop"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_26" id="rch19p_26">26.</a></strong> <strong>A—</strong>The mechanical energy of the object-Earth systems starts at <em>mgh</em>, and since no work is done by external forces on the objects, the mechanical energy is the same at the bottom as at the top. But that mechanical energy at the bottom consists of both rotational and translational kinetic energies. Since a hoop has mass distributed farther on average from the axis of rotation, the hoop must have a greater rotational inertia. Therefore, a greater proportion of its mechanical energy is rotational rather than translational, and the hoop moves slower, the disk faster.</p>'),
  ('ap-mock-physc-mech-3_q27', 'ap-mock-physc-mech-3', 27, false, 'D', 'AP Physics C: Mechanics', 'hard', '<p class="ques"><strong><a href="ch19t.xhtml#rch19p_27" id="ch19p_27">27.</a></strong> In the laboratory, disk 1 spins on a vertical axle with minimal friction. Disk 2 is initially not spinning and drops from above onto disk 1. The disks collide and rotate together after collision. How does the angular momentum and the rotational kinetic energy of the two-disk system compare before and after collision?</p><p class="image"><img alt="Images" class="q-img" src="images/f0309-13.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="image"><img alt="Images" class="q-img" src="images/f0310-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Angular Momentum: Conserved; Rotational Kinetic Energy: Conserved","Angular Momentum: Decreases; Rotational Kinetic Energy: Conserved","Angular Momentum: Decreases; Rotational Kinetic Energy: Decreases","Angular Momentum: Conserved; Rotational Kinetic Energy: Decreases","Angular Momentum: Increases; Rotational Kinetic Energy: Decreases"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_27" id="rch19p_27">27.</a></strong> <strong>D—</strong>No external torques act on the two-disk system (only the torque of disk 1 on disk 2 and vice versa). That’s the very definition of when angular momentum is conserved. However, the collision is by definition inelastic because the disks stick together. In an inelastic collision, mechanical energy—including rotational kinetic energy—is not conserved.</p>'),
  ('ap-mock-physc-mech-3_q28', 'ap-mock-physc-mech-3', 28, false, 'C', 'AP Physics C: Mechanics', 'hard', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 28 and 29: Three spheres are arranged in deep space as shown above, far away from any planet or star.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_28" id="ch19p_28">28.</a></strong> Which of the following diagrams shows the correct relative magnitudes and directions of the forces $F_{C}$ (the gravitational force of sphere C on sphere A) and $F_{B}$ (the gravitational force of sphere B on sphere A)?</p>', '["<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0310-02.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0310-03.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0310-04.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0310-05.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0310-06.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_28" id="rch19p_28">28.</a></strong> <strong>C—</strong>The gravitational force is always attractive, so both forces act to the right. The formula is $F$ = <em>Gm</em><sub>1</sub>$m_{2}$<em>/d</em><sup>2</sup>. This equation for $F_{B}$ has a numerator that’s twice as big as for $F_{C}$ and a denominator (2/3)<sup>2</sup> = 4/9 as big. That makes $F_{B}$ something like four times larger, as in choice C.</p>'),
  ('ap-mock-physc-mech-3_q29', 'ap-mock-physc-mech-3', 29, false, 'E', 'AP Physics C: Mechanics', 'hard', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 28 and 29: Three spheres are arranged in deep space as shown above, far away from any planet or star.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_29" id="ch19p_29">29.</a></strong> In units of <em>Gm</em><sup>2</sup><em>/x</em><em><sup>2</sup></em>, which of the following represents the net gravitational force of spheres B and C on sphere A?</p>', '["<p>7/18</p>","<p>7/3</p>","<p>1/6</p>","<p>4/3</p>","<p>11/18</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_29" id="rch19p_29">29.</a></strong> <strong>E—</strong>The expression for the force of sphere B on sphere A is $G$(2$m$)($m$)/(2$x$)<sup>2</sup>. The expression for the force of sphere C on sphere A is $G$($m$)($m$)/(3$x$)<sup>2</sup>. Add the forces together because they act in the same direction; you get (11/18)(<em>Gm</em><sup>2</sup><em>/x</em><sup>2</sup>).</p>'),
  ('ap-mock-physc-mech-3_q30', 'ap-mock-physc-mech-3', 30, false, 'C', 'AP Physics C: Mechanics', 'hard', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 30 and 31: An object of mass 2 kg moves in one dimension according to the velocity $v$ vs. time $t$ function $v$($t$) = $c$ – <em>bt</em><sup>2</sup><em>,</em> where $c$ = +2 m/s, and $b$ = +3 m/$s^{3}$. The positive direction is to the right.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_30" id="ch19p_30">30.</a></strong> Which of the following is an expression for the net force (in SI units) acting on the object as a function of time?</p>', '["<p>−6$t$</p>","<p>4 – 6$t^{2}$</p>","<p>−12$t$</p>","<p>2$t$ – $t^{3}$</p>","<p>4$t$ – 2$t^{2}$</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_30" id="rch19p_30">30.</a></strong> C—The time derivative of velocity is acceleration, and then net force is mass times acceleration. The time derivative of this function is −6$t$; multiply this by the 2 kg mass to get choice C.</p>'),
  ('ap-mock-physc-mech-3_q31', 'ap-mock-physc-mech-3', 31, false, 'E', 'AP Physics C: Mechanics', 'hard', '<div class="passage-box" style="background: rgba(255,255,255,0.03); padding: 12px 16px; border-radius: 8px; margin-bottom: 14px; border-left: 3px solid #7c3aed;"><p class="noindent">Questions 30 and 31: An object of mass 2 kg moves in one dimension according to the velocity $v$ vs. time $t$ function $v$($t$) = $c$ – <em>bt</em><sup>2</sup><em>,</em> where $c$ = +2 m/s, and $b$ = +3 m/$s^{3}$. The positive direction is to the right.</p></div><p class="ques"><strong><a href="ch19t.xhtml#rch19p_31" id="ch19p_31">31.</a></strong> Which of the following descriptions of the object’s motion starting at time $t$ = 0 and immediately thereafter is correct?</p>', '["<p>The object initially is moving to the left at 2 m/s and is speeding up.</p>","<p>The object initially is moving to the right at 2 m/s and is speeding up.</p>","<p>The object initially is at rest, then speeds up.</p>","<p>The object initially is moving to the left at 2 m/s and is slowing down.</p>","<p>The object initially is moving to the right at 2 m/s and is slowing down.</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_31" id="rch19p_31">31.</a></strong> <strong>E—</strong>The initial velocity is when time $t$ is zero. That’s just $c$ in this expression, so +2 m/s. The positive means moving right. As time goes on, the second term becomes nonzero, which means we’re subtracting something from the initial speed, so the object slows down.</p>'),
  ('ap-mock-physc-mech-3_q32', 'ap-mock-physc-mech-3', 32, false, 'A', 'AP Physics C: Mechanics', 'hard', '<p class="ques"><strong><a href="ch19t.xhtml#rch19p_32" id="ch19p_32">32.</a></strong> A 5000 kg satellite changes its orbital speed by firing a thruster for one minute. In that time, the satellite’s speed changes from 7600 m/s to 7500 m/s. What is the force provided by the thruster?</p>', '["<p>8300 N</p>","<p>500,000 N</p>","<p>50,000 N</p>","<p>30,000 N</p>","<p>83 N</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_32" id="rch19p_32">32.</a></strong> <strong>A—</strong>Use the impulse-momentum theorem, Δ$p$ = <em>Ft</em>. Here the change in momentum is the satellite’s mass times its change in speed, 5000 kg × 100 m/s. And the time interval is 60 s. So the force of the thruster is 500,000/60 = 8300 N.</p>'),
  ('ap-mock-physc-mech-3_q33', 'ap-mock-physc-mech-3', 33, false, 'E', 'AP Physics C: Mechanics', 'hard', '<p class="ques"><strong><a href="ch19t.xhtml#rch19p_33" id="ch19p_33">33.</a></strong> A satellite of mass $m_{s}$ is placed in geosynchronous orbit, meaning it remains over the same position on Earth’s surface at all times. The mass of Earth is $m_{e}$, and the period of Earth’s orbit is $T$. Which of the following is a correct expression for the radius of the satellite’s orbit?</p>', '["<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0310-07.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0310-08.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0310-09.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0310-10.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0310-11.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_33" id="rch19p_33">33.</a></strong> <strong>E—</strong>Kepler’s law says that the period of an orbit squared is proportional to the radius of the orbit cubed. Thus the expression for radius must have a cube root of $T^{2}$. Then when using Newton’s second law by setting the gravitational force <em>Gm</em><sub>s</sub>$m_{e}$/$r^{2}$ equal to <em>ma</em>, the object undergoing acceleration is the satellite—so we use $m_{s}$ in the right-hand-side expression, and the $m_{s}$ cancels . . . leaving $m_{e}$ as the only mass in the resulting expression.</p>'),
  ('ap-mock-physc-mech-3_q34', 'ap-mock-physc-mech-3', 34, false, 'A', 'AP Physics C: Mechanics', 'hard', '<p class="ques"><strong><a href="ch19t.xhtml#rch19p_34" id="ch19p_34">34.</a></strong> A student reports the results of an experiment:</p><p class="ques-p">A ball of mass 1.0 kg initially moves horizontally at a speed of 2.0 m/s. The ball bounces off the stationary wall of a building, rebounding horizontally with speed 2.0 m/s.</p><p class="ques-p">Which of the following is a correct statement about horizontal linear momentum conservation in this collision?</p>', '["<p>The momentum of the ball was not conserved, but the momentum of the ball-Earth system was conserved.</p>","<p>The momentum of the ball was not conserved, and neither was the momentum of the ball-Earth system.</p>","<p>The momentum of the ball was conserved, and the momentum of the ball-Earth system was also conserved.</p>","<p>The momentum of the ball was conserved, but the momentum of the ball-Earth system was not conserved.</p>","<p>The momentum of the ball was conserved, but the data provided don’t provide enough evidence to draw a conclusion about whether momentum of the ball-Earth system was conserved.</p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_34" id="rch19p_34">34.</a></strong> <strong>A—</strong>Momentum is conserved when no external forces act on a system. The ball’s momentum is not conserved here, because the external force of the wall acts on the ball. (The ball’s direction changes, so even though the magnitude of the ball’s momentum doesn’t change, the ball’s momentum vector does change.) Considering the ball-Earth system, though, no external forces act on that system—so momentum of the ball-Earth system is conserved.</p>'),
  ('ap-mock-physc-mech-3_q35', 'ap-mock-physc-mech-3', 35, false, 'C', 'AP Physics C: Mechanics', 'hard', '<p class="ques"><strong><a href="ch19t.xhtml#rch19p_35" id="ch19p_35">35.</a></strong> Satellite A undergoes circular orbit around Earth. The satellite maintains a distance above Earth’s surface equal to one Earth radius. Satellite B undergoes circular orbit a distance above Earth’s surface equal to two Earth radii. What is the ratio of the orbital speed of satellite A to the orbital speed of satellite B?</p>', '["<p>1:1</p>","<p>3:2</p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0311-01.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>","<p>2:1</p>","<p><img alt=\"Images\" class=\"q-img\" src=\"images/f0311-02.jpg\" style=\"max-width: 100%; height: auto; margin: 10px 0; display: block;\"/></p>"]'::jsonb, '<p class="ques"><strong><a href="ch19p.xhtml#ch19p_35" id="rch19p_35">35.</a></strong> <strong>C—</strong>Derive the orbital speed by setting the gravitational force <em>GMm/r</em><sup>2</sup> equal to <em>ma</em>, where acceleration in a circle is $v^{2}$/$r$. Solving for $v$ gives <img alt="Images" class="q-img" src="images/f0332-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>, $M$ being the mass of the central planet. With the $r$ for satellite B being twice that for satellite A, that gives a ratio of 1:(1/<img alt="Images" class="q-img" src="images/root2.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>), which is the same thing as <img alt="Images" class="q-img" src="images/root2.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>:1.</p>
                <div class="correction-note" style="margin-top: 10px; padding: 10px; background: rgba(79, 70, 229, 0.1); border-left: 3px solid #6366f1; border-radius: 4px;">
                    <strong>Analytical Physical Note (Errata Correction):</strong><br>
                    Satellite A orbits at altitude \$1 R_E$ above Earth''s surface ($r_A = 2 R_E$). Satellite B orbits at altitude \$2 R_E$ above Earth''s surface ($r_B = 3 R_E$).
                    The orbital speed ratio is $v_A / v_B = \sqrt{r_B / r_A} = \sqrt{3/2} : 1 \approx 1.22 : 1$.
                </div>
                ')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-mock-physc-mech-3_q36', 'ap-mock-physc-mech-3', 36, true, 'FRQ_MANUAL_EVALUATION', 'AP Physics C: Mechanics Free Response', 'hard', '<div class=''frq-prompt''><h3>CM 1</h3><p class="ques"><strong><a href="ch19u.xhtml#rch19q_1" id="ch19q_1">1.</a></strong> An object of mass 2 kg moves in one dimension along the $x$-axis, experiencing a resistive force. Its velocity $v$ in meters per second as a function of time $t$ in seconds is given by the expression <em>ν</em>($t$) = +1.4$e$<sup>-<em>bt</em></sup>.</p><p class="alphabrt">(a) What are the units of the constant $b$?</p><p class="alphabr">(b) Determine the magnitude of the object’s initial velocity.</p><p class="alphabr">(c) Is the object moving in the positive or negative direction initially? Briefly justify your answer.</p><p class="alphabr">(d) Immediately after time $t$ = 0, is the object speeding up, slowing down, or moving with steady speed? Briefly justify your answer.</p><p class="alphabr">(e) Immediately after time $t$ = 0, is the magnitude of the object’s acceleration increasing, decreasing, or remaining constant? Briefly justify your answer.</p><p class="alphabr">(f) On the axes below, sketch the shape of a graph of the net force on this object as a function of time for the first 4 seconds of motion. Label the graph with expressions for any vertical or horizontal intercepts.</p><p class="image"><img alt="Images" class="q-img" src="images/f0312-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="alphabr">(g) In terms of $b$, derive an expression for the total distance traveled by the object after a very long time.</p><p class="alphabrb">(h) Calculate the total energy dissipated by the resistive force after a very long time.</p><p class="image"><img alt="Images" class="q-img" src="images/f0313-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p></div>', '["Submit analytical derivation in workspace."]'::jsonb, '<p class="ques"><strong><a href="ch19q.xhtml#ch19q_1" id="rch19q_1">1.</a></strong> (15 points)</p><p class="alphabrt">(a) The exponent must be unitless, so units of $b$ must cancel the units of time.</p><p class="hangp"><strong>1 pt</strong> for the correct answer, 1/s or s<sup>−1</sup></p><p class="alphabrt">(b) Initial velocity is when $t$ = 0. And $e^{0}$ is 1. So the initial velocity is 1.4 m/s.</p><p class="hangp"><strong>1 pt</strong> for the correct answer</p><p class="alphabrt">(c) Positive—when $t$ = 0, the $e$<sup>−</sup><em>bt</em> term becomes 1, and the remaining expression is positive.</p><p class="hangp"><strong>1 pt</strong> for the correct answer</p><p class="hangp"><strong>1 pt</strong> for justification</p><p class="alphabrt">(d) As $t$ increases, the $e$<sup>−</sup><em>bt</em> term gets smaller. So the whole expression gets smaller, and the speed decreases.</p><p class="hangp"><strong>1 pt</strong> for the correct answer</p><p class="hangp"><strong>1 pt</strong> for justification</p><p class="alphabrt">(e) The acceleration is the time derivative of the velocity. For this function, that’s −1.4<em>be</em><sup>−</sup><em>bt</em>. Again, the $e$<sup>−</sup><em>bt</em> term gets smaller as time goes on. That makes the absolute value of the whole expression get smaller. The magnitude of the acceleration decreases.</p><p class="hangp"><strong>1 pt</strong> for the correct answer</p><p class="hangp"><strong>1 pt</strong> for justification</p><p class="alphabrt">(f)</p><p class="hangp"><strong>1 pt</strong> for a graph never above the horizontal axis</p><p class="hangp"><strong>1 pt</strong> for an exponential graph decreasing in magnitude, even if in the wrong quadrant</p><p class="hangp"><strong>1 pt</strong> for labeling the $y$-intercept as “2.8$b$,” whether positive or negative—the net force is <em>ma</em>, and $m$ is 2 kg, so the intercept is (2)(1.4$b$) = 2.8$b$.</p><p class="image"><img alt="Images" class="q-img" src="images/f0333-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="alphabrt">(g)</p><p class="hangp"><strong>1 pt</strong> for setting up an integral of velocity with respect to time <em>with correct limits of 0 to infinity</em></p><p class="hangp"><strong>1 pt</strong> for the correct answer of (positive) 1.4/$b$</p><p class="image"><img alt="Images" class="q-img" src="images/f0333-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="alphabrt">(h) The total energy dissipated is the change in kinetic energy. The initial kinetic energy is ½<em>mv</em><sup>2</sup>, where $m$ is 2 kg and $v$ is 1.4$b$. The final kinetic energy is zero. Total energy dissipated is ½(2)(1.4$b$)<sup>2</sup> = (1.4$b$)<sup>2</sup> or 2.0$b^{2}$.</p><p class="hangp"><strong>1 pt</strong> for attempting to calculate a change in kinetic energy</p><p class="hangp"><strong>1 pt</strong> for the the correct answer</p>'),
  ('ap-mock-physc-mech-3_q37', 'ap-mock-physc-mech-3', 37, true, 'FRQ_MANUAL_EVALUATION', 'AP Physics C: Mechanics Free Response', 'hard', '<div class=''frq-prompt''><h3>CM 2</h3><p class="ques"><strong><a href="ch19u.xhtml#rch19q_2" id="ch19q_2">2.</a></strong> Satellites A and B are in circular orbit around a planet of mass $M$ and radius $R$. Satellite A has mass $m_{A}$ and orbital radius 2$R$. Satellite B has mass $m_{B}$ and orbital radius 4$R$.</p><p class="alphabrt">(a) Derive an expression for the orbital speed $v_{A}$ of satellite A in terms of given variables and fundamental constants.</p><p class="alphabr">(b) The orbital speed of satellite B is $v_{B}$. Can the ratio $v_{B}$:$v_{A}$ be calculated? If so, calculate this ratio. If not, explain what additional information would be needed and why.</p><p class="alphabr">(c) Derive an expression for the work necessary to move satellite A into satellite B’s orbit.</p><p class="alphabr">(d) Let the period of satellite A’s orbit be $T_{A}$ and the period of satellite B’s orbit be $T_{B}$. Calculate the ratio $T_{B}$/$T_{A}$.</p><p class="alphabr">(e) Now assume each satellite has the same mass $m_{A}$. In that case, which satellite has a larger total mechanical energy in its orbit? Justify your answer.</p><p class="alphabrb">(f) Derive an expression for the minimum speed that satellite A must have at the location shown in order to end up a very long way away from the planet.</p><p class="image"><img alt="Images" class="q-img" src="images/f0314-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p></div>', '["Submit analytical derivation in workspace."]'::jsonb, '<p class="ques"><strong><a href="ch19q.xhtml#ch19q_2" id="rch19q_2">2.</a></strong> (15 points)</p><p class="alphabrt">(a)</p><p class="hangp"><strong>1 pt</strong> for using a gravitational force expression in Newton’s second law</p><p class="hangp"><strong>1 pt</strong> for setting acceleration equal to $v^{2}$/$r$</p><p class="hangp"><strong>1 pt</strong> for the correct expression for $v$</p><p class="image"><img alt="Images" class="q-img" src="images/f0334-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="alphabrt">(b)</p><p class="hangp"><strong>1 pt</strong> for recognizing that the ratio can be calculated</p><p class="hangp"><strong>1 pt</strong> for using any appropriate method to get the correct answer, such as recognizing that the orbital radius is under a square root in the denominator of the speed expression and all other quantities are unchanging, so doubling the radius multiplies the speed by <img alt="Images" class="q-img" src="images/f0334-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>.</p><p class="alphabrt">(c)</p><p class="hangp"><strong>1 pt</strong> for attempting to subtract the potential energies of satellite A at each orbital radius</p><p class="hangp"><strong>1 pt</strong> for the correct answer</p><p class="image"><img alt="Images" class="q-img" src="images/f0334-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="alphabrt">(d) Kepler’s third law says period is proportional to the 3/2 power of orbital radius. Since satellite B has twice the orbital radius, its period is 2<sup>3/2</sup> times larger. The ratio can be expressed as 2<sup>3/2</sup>, <img alt="Images" class="q-img" src="images/root8.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>, <img alt="Images" class="q-img" src="images/2root2.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>, 2.8, or any equivalent.</p><p class="hangp"><strong>1 pt</strong> for citing Kepler’s third law (or alternatively, expanding on the derivation in (a) by writing $v$ as orbital circumference divided by period)</p><p class="hangp"><strong>1 pt</strong> for the correct answer</p><p>(e)</p><p class="hangp"><strong>1 pt</strong> for summing kinetic and potential energies to get total mechanical energy (or using the fact that in an orbit, the total mechanical energy is half the potential energy)</p><p class="hangp"><strong>1 pt</strong> for an expression for gravitational potential energy, including the negative sign: $U$ = −<em>GMm</em>/$r$</p><p class="hangp"><strong>1 pt</strong> for the correct comparison—with a larger orbital radius, the mechanical energy for satellite B is less negative, and thus greater</p><p class="alphabrt">(f)</p><p class="hangp"><strong>1 pt</strong> for setting the total mechanical energy ($K +U$) to zero (because gravitational potential energy is defined as zero a long way away from the central planet, so the minimum mechanical energy a long way away will be zero)</p><p class="hangp"><strong>1 pt</strong> for the correct expressions for kinetic and potential energies at the current location.</p><p class="hangp"><strong>1 pt</strong> for the correct answer</p><p class="image"><img alt="Images" class="q-img" src="images/f0334-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-mock-physc-mech-3_q38', 'ap-mock-physc-mech-3', 38, true, 'FRQ_MANUAL_EVALUATION', 'AP Physics C: Mechanics Free Response', 'hard', '<div class=''frq-prompt''><h3>CM 3</h3><p class="ques"><strong><a href="ch19u.xhtml#rch19q_3" id="ch19q_3">3.</a></strong> In the laboratory, students roll a ball from rest without slipping down a surface inclined at an unknown angle $\theta$ to the horizontal. They measure the time $t$ for the ball to travel a distance $d$ measured along the incline. The ball has rotational inertia given by (2/3)<em>MR</em><sup>2</sup>, where $M$ and $R$ are the mass and radius of the ball, respectively.</p><p class="alphabrt">(A) Show that the speed $v$ of the ball’s center of mass after the distance $d$ is given by <img alt="Images" class="q-img" src="images/f0314-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>.</p><p class="alphabr">(b) Show that $d$ is related to $t$ according to the equation <img alt="Images" class="q-img" src="images/f0314-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>.</p><p class="alphabr">The students collect the data below.</p><p class="image"><img alt="Images" class="q-img" src="images/f0314-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="alphabr">(c) Indicate below which quantities could be graphed to yield a straight line whose slope could be used to calculate the angle $\theta$.</p><p class="alphabr-p">Vertical axis: _____</p><p class="alphabr-p">Horizontal axis: _____</p><p class="noindentt">Use the remaining rows in the table provided, as needed, to record any quantities you indicated that are not given in the table. Label each row you use and include units.</p><p class="alphabr">(d) Plot the data points for the quantities indicated in part (c) on the graph below. Clearly scale and label all axes, including units if appropriate. Draw a straight line that best represents the data.</p><p class="image"><img alt="Images" class="q-img" src="images/f0315-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="alphabr">(e) Using the straight line, calculate an experimental value for $\theta$.</p><p class="center1"><strong>STOP. End of Physics C—Mechanics Practice Exam 3—Free-Response Questions</strong></p></div>', '["Submit analytical derivation in workspace."]'::jsonb, '<p class="ques"><strong><a href="ch19q.xhtml#ch19q_3" id="rch19q_3">3.</a></strong> (15 points)</p><p class="alphabrt">(a)</p><p class="hangp"><strong>1 pt</strong> for an energy expression that includes rotational and linear kinetic energies</p><p class="hangp"><strong>1 pt</strong> for using correct expressions for gravitational, rotational kinetic, and linear kinetic energies</p><p class="hangp"><strong>1 pt</strong> for the relationship between $h$ and $d$, $h = d$ sin$\theta$. 1 for using the relation $\omega$ = <em>v/R</em> to cancel the $R$ term</p><p class="image"><img alt="Images" class="q-img" src="images/f0335-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="alphabrt">(b)</p><p class="hangp"><strong>1 pt</strong> for using a kinematic equation relating distance and time</p><p class="hangp"><strong>1 pt</strong> for using a kinematic equation to relate acceleration to the speed from part (a)</p><p class="hangpt">with zero initial speed, <em>$ν^{2}$</em> = 2<em>ad</em></p><p class="image"><img alt="Images" class="q-img" src="images/f0335-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="alphabrt">(c)</p><p class="hangp"><strong>1 pt</strong> For any combination that would create a straight line graph. I’ve used $d$ and <em>$t^{2}$</em>. It’s also legit to use $t$ and <img alt="Images" class="q-img" src="images/rootd.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>. Or graphing $d$ and (3/10)<em>gt</em><sup>2</sup> would give a slope that straight-up represents sin $\theta$.</p><p class="alphabrt">(d) If the chosen axes don’t create a linear graph, only the first two of these points can be awarded.</p><p class="hangp"><strong>1 pt</strong> for data plotted correctly</p><p class="hangp"><strong>1 pt</strong> for linear scales on each axis that allow the data to take up about half of the grid area</p><p class="hangp"><strong>1 pt</strong> for correct units on both axes</p><p class="hangp"><strong>1 pt</strong> for a reasonable best-fit line</p><p class="image"><img alt="Images" class="q-img" src="images/f0336-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="alphabrt">(e)</p><p class="hangp"><strong>1 pt</strong> for correctly calculating the slope of the graph, using points on the line, not data points</p><p class="hangp"><strong>1 pt</strong> for relating the slope to its physical meaning—in the example, the slope is shown to be equal to (3/10)$g$ sin $\theta$</p><p class="hangp"><strong>1 pt</strong> for using the physical meaning of the slope in an attempt to determine $\theta$</p><p class="hangp"><strong>1 pt</strong> for a value of $\theta$ between 4 and 8 degrees</p><p class="image"><img alt="Images" class="q-img" src="images/f0336-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><h4 class="h4c">AP Physics C—Mechanics</h4><p class="centera"><strong>Full Exam Scoring</strong></p><p class="noindentt1">Multiple-Choice: Number Correct______(35 max)</p><p class="noindentt1">Free-Response: Question 1______(15 max)</p><p class="noindentq">Question 2______(15 max)</p><p class="noindentq">Question 3______(15 max)</p><p class="noindentt1">Total Free-Response______(45 max)</p><p class="noindentt1">1.286 × Multiple-Choice + Free-Response = Raw Score______(90 max)</p><p class="image"><img alt="Images" class="q-img" src="images/f0337-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-mock-physc-mech-3_q39', 'ap-mock-physc-mech-3', 39, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'A constant horizontal force F applied to a block on an incline causes the block to move a distance d along the incline, as shown. If the coefficient of friction between the block and the incline is \muk, what is the work done by the applied force? (Do not assume that the block moves at constant velocity.)', '["W = Fd sin \\theta","W = Fd cos \\theta","W = mgd sin \\theta","W = mgd sin \\theta − \\muk mgd cos \\theta","W = mgd sin \\theta + \\mukd(mg cos \\theta + F sin \\theta)"]'::jsonb, '(B) Because the force is constant, the work is given by the dot product of the force and the displacement vectors: Choice (C) is the change in potential energy as the block is elevated. Choice (E) is the work that would have to be done by F to move the block up the incline at a constant speed; that is, the work done by F would be the negative of the work done by gravity and by friction (because the net work would have to be zero).'),
  ('ap-mock-physc-mech-3_q40', 'ap-mock-physc-mech-3', 40, false, 'E', 'Practice Test 1 – Mechanics', 'medium', 'The restoring force that acts on a mass is shown. For small amplitudes, the mass moves in simple harmonic motion with a period T. Which of the following is true of oscillations with larger amplitudes?', '["The motion is SHM with a period of T.","The motion is SHM with a period smaller than T.","The motion is SHM with a period larger than T.","The motion is no longer SHM, and its period is smaller than T.","The motion is no longer SHM, and its period is larger than T."]'::jsonb, '(E) See the figure. For large-amplitude oscillations, the restoring force is not linear, so the motion is not simple harmonic motion. Because the restoring force is smaller than its linear approximation about the origin (which would produce a period of T), it produces motion with a larger period. (Because the force is smaller, the particle oscillates more slowly and more time is required for each cycle.)'),
  ('ap-mock-physc-mech-3_q41', 'ap-mock-physc-mech-3', 41, false, 'C', 'Practice Test 1 – Mechanics', 'medium', 'A simple pendulum of length ℓ is moved to Mars (where g = 3.71 m/s2). Its period on Earth is 2.0 s. Its period on Mars is', '["0.02 s","2.0 s","3.25 s","600 s","6,000 s"]'::jsonb, '(C) The period of a simple pendulum is given by . If the quantities on Mars are denoted by primes, then the period on Mars is given by , where the unprimed values are those on Earth (note that the length is unchanged). Thus, s.'),
  ('ap-mock-physc-mech-3_q42', 'ap-mock-physc-mech-3', 42, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'At the instant that a mass in simple harmonic motion passes through its equilibrium position its acceleration is', '["maximum","zero","oppositely directed to its velocity","parallel to its velocity","cannot be determined without additional information"]'::jsonb, '(B) A simple harmonic oscillator is characterized by a = −\omega2x (found by plugging Hooke’s law into Newtons’ second law). At equilibrium, x = 0 and thus the acceleration is also zero.'),
  ('ap-mock-physc-mech-3_q43', 'ap-mock-physc-mech-3', 43, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'A solid sphere has a rotational inertia of when rotated about an axis tangent to its surface as shown. What is the rotational inertia of the sphere when it is rotated about a line passing through the center of the sphere?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(B) According to the parallel axis theorem, the rotational inertia about an axis that does not pass through the center of mass (in this problem, the one that passes along the surface of the sphere) is equal to the rotational inertia about a parallel axis passing through the center of mass (in this problem, the axis passing through the sphere’s center) plus MD2, where D is the distance between the two axes (in this case, r): Solving this equation for the rotational inertia about the axis that passes through the center of mass yields choice (B).'),
  ('ap-mock-physc-mech-3_q44', 'ap-mock-physc-mech-3', 44, false, 'C', 'Practice Test 1 – Mechanics', 'medium', '<p>A simple pendulum of length L is released from rest with its string horizontal (Point I). It swings downward through a circular arc. At Point II (when the string makes a 45° angle with the vertical), what is the direction of the pendulum bob’s net acceleration vector?</p>', '["Purely radial toward the pivot center","Purely tangential in the direction of velocity","Inward and downward, angled between the radial and tangential directions","Directly downward toward the center of the Earth","Directly upward opposite gravity"]'::jsonb, '(C) Consider the figure. The pendulum is rotating in a circle, so it must experience a centripetal acceleration toward the center of the circle. The pendulum is also speeding up (because of conservation of energy, with gravitational potential energy being converted to kinetic energy), so it experiences a tangential acceleration parallel to its velocity. The sum of these accelerations produces a net acceleration that is neither purely radial nor purely tangential but rather points in the direction of choice (C).'),
  ('ap-mock-physc-mech-3_q45', 'ap-mock-physc-mech-3', 45, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'A mass m moving to the right with speed v collides and sticks to a mass of 3m moving upward with a speed 2v as shown. What is the final velocity of the two masses?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","(E) none of the above","Zero net change under static equilibrium conditions"]'::jsonb, '(B) This is an inelastic collision such that momentum is conserved and the final velocity of both masses is the same (because they stick together and move with a common velocity). Conservation of momentum yields Solving these equations yields choice (B).'),
  ('ap-topic-physc-tension-drills_q1', 'ap-topic-physc-tension-drills', 1, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #1:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>1.</strong> Frictionless</p><p class="image"><img alt="Images" class="q-img" src="images/f0064-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>1.</strong> <img alt="Images" class="q-img" src="images/e0065-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q2', 'ap-topic-physc-tension-drills', 2, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #2:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>2.</strong> Frictionless</p><p class="image"><img alt="Images" class="q-img" src="images/f0064-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>2.</strong> <img alt="Images" class="q-img" src="images/e0065-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q3', 'ap-topic-physc-tension-drills', 3, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #3:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>3.</strong> Frictionless</p><p class="image"><img alt="Images" class="q-img" src="images/f0064-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>3.</strong> <img alt="Images" class="q-img" src="images/e0065-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q4', 'ap-topic-physc-tension-drills', 4, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #4:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>4.</strong> Coefficient of Friction $\mu$</p><p class="image"><img alt="Images" class="q-img" src="images/f0064-05.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>4.</strong> <img alt="Images" class="q-img" src="images/e0065-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q5', 'ap-topic-physc-tension-drills', 5, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #5:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>5.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0064-06.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>5.</strong> <img alt="Images" class="q-img" src="images/e0065-05.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q6', 'ap-topic-physc-tension-drills', 6, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #6:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>6.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0064-07.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>6.</strong> <img alt="Images" class="q-img" src="images/e0065-06.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q7', 'ap-topic-physc-tension-drills', 7, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #7:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>7.</strong> Frictionless</p><p class="image"><img alt="Images" class="q-img" src="images/f0064-08.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>7.</strong> <img alt="Images" class="q-img" src="images/e0065-07.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q8', 'ap-topic-physc-tension-drills', 8, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #8:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>8.</strong> Frictionless</p><p class="image"><img alt="Images" class="q-img" src="images/f0064-09.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>8.</strong> <img alt="Images" class="q-img" src="images/e0065-08.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q9', 'ap-topic-physc-tension-drills', 9, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #9:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>9.</strong> Frictionless</p><p class="image"><img alt="Images" class="q-img" src="images/f0065-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>9.</strong> <img alt="Images" class="q-img" src="images/e0065-09.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q10', 'ap-topic-physc-tension-drills', 10, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #10:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>10.</strong> Coefficient of Friction $\mu$</p><p class="image"><img alt="Images" class="q-img" src="images/f0065-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>10.</strong> <img alt="Images" class="q-img" src="images/e0065-10.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q11', 'ap-topic-physc-tension-drills', 11, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #11:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>11.</strong> Coefficient of Friction $\mu$</p><p class="image"><img alt="Images" class="q-img" src="images/f0065-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>11.</strong> <img alt="Images" class="q-img" src="images/e0065-11.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q12', 'ap-topic-physc-tension-drills', 12, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #12:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>12.</strong> Frictionless</p><p class="image"><img alt="Images" class="q-img" src="images/f0065-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>12.</strong> <img alt="Images" class="q-img" src="images/e0065-12.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q13', 'ap-topic-physc-tension-drills', 13, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #13:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>13.</strong> Frictionless</p><p class="image"><img alt="Images" class="q-img" src="images/f0065-05.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>13.</strong> <img alt="Images" class="q-img" src="images/e0065-13.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-tension-drills_q14', 'ap-topic-physc-tension-drills', 14, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'medium', '<p><strong>Tension Drill #14:</strong> Assuming all pulleys and ropes are massless, find the tension in each rope and the acceleration of the set of masses shown:</p><p class="ques"><strong>14.</strong> Coefficient of Friction $\mu$</p><p class="image"><img alt="Images" class="q-img" src="images/f0065-06.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>14.</strong> <img alt="Images" class="q-img" src="images/e0065-14.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><h4 class="h4">Step-by-Step Solution to #2:</h4><p class="noindent"><em>Step 1:</em> Free-body diagrams:</p><p class="image"><img alt="Images" class="q-img" src="images/f0066-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">No components are necessary, so on to <em>Step 3:</em> write Newton’s second law for each block, calling the rightward direction positive:</p><p class="image"><img alt="Images" class="q-img" src="images/e0066-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent"><em>Step 4:</em> Solve algebraically. It’s easiest to add these equations together, because the tensions cancel:</p><p class="image"><img alt="Images" class="q-img" src="images/e0066-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">To get the tension, just plug back into $T$ − 0 = <em>ma</em> to find $T = F$/3 = 3.3 N.</p><h4 class="h4">Step-by-Step Solution to #5:</h4><p class="noindent"><em>Step 1:</em> Free-body diagrams:</p><p class="image"><img alt="Images" class="q-img" src="images/f0066-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">No components are necessary, so on to <em>Step 3:</em> write Newton’s second law for each block, calling clockwise rotation of the pulley positive:</p><p class="image"><img alt="Images" class="q-img" src="images/e0066-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent"><em>Step 4:</em> Solve algebraically. It’s easiest to add these equations together, because the tensions cancel:</p><p class="image"><img alt="Images" class="q-img" src="images/e0066-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">To get the tension, just plug back into $T$ − <em>mg</em> = <em>ma</em> : $T = m$ ($a +g$) = (4/3)<em>mg</em> = 13 N.</p>'),
  ('ap-topic-physc-tension-drills_q15', 'ap-topic-physc-tension-drills', 15, true, 'FRQ_MANUAL_EVALUATION', 'Tension Dynamics', 'hard', '<p><strong>Tension Drill #15:</strong> Two blocks of mass $M$ and $m$ ($M > m$) hang on opposite sides of a frictionless pulley. If the pulley itself has mass $M_p$ and rotational inertia $I = \frac{1}{2}M_p R^2$, derive the expression for string tension $T_1$ on mass $M$.</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>Accounting for pulley inertia: $T_1 = Mg\left[\frac{2m + M_p/2}{M + m + M_p/2}\right]$.</p>'),
  ('ap-topic-physc-tension-drills_q16', 'ap-topic-physc-tension-drills', 16, false, 'A', 'ap-topic-physc-tension', 'medium', 'A heavy hanging rope of uniform linear mass density $\lambda$ and total length $L$ hangs vertically from a fixed ceiling. What is the tension in the rope as a function of distance $y$ measured upward from the bottom free end?', '["$T(y) = \\lambda g y$","$T(y) = \\lambda g (L - y)$","$T(y) = \\frac{1}{2}\\lambda g y^2$","$T(y) = \\lambda g L$"]'::jsonb, 'At distance $y$ from the bottom, the section of rope below supports its own weight: $m_{below} = \lambda y$. Static equilibrium requires $T(y) = m_{below}g = \lambda g y$.'),
  ('ap-topic-physc-tension-drills_q17', 'ap-topic-physc-tension-drills', 17, false, 'B', 'ap-topic-physc-tension', 'easy', 'A mass $m$ is suspended by two light strings symmetrically inclined at angle $\theta$ to the horizontal ceiling. What is the tension $T$ in each string?', '["$T = \\dfrac{mg}{2\\cos\\theta}$","$T = \\dfrac{mg}{2\\sin\\theta}$","$T = \\dfrac{mg}{\\sin\\theta}$","$T = 2mg\\sin\\theta$"]'::jsonb, 'Vertical equilibrium: $2T\sin\theta = mg \implies T = \frac{mg}{2\sin\theta}$.'),
  ('ap-topic-physc-tension-drills_q18', 'ap-topic-physc-tension-drills', 18, false, 'C', 'ap-topic-physc-tension', 'easy', 'A block of mass $m$ is attached to a vertical string and swung in a vertical circle of radius $R$ at constant speed $v$. Where is the tension in the string maximized, and what is its value?', '["At the top point, $T = \\dfrac{mv^2}{R} - mg$","At horizontal orientation, $T = \\dfrac{mv^2}{R}$","At the lowest point, $T_{max} = mg + \\dfrac{mv^2}{R}$","Tension is constant at all points"]'::jsonb, 'At the lowest point, tension must overcome gravity while providing centripetal acceleration: $T - mg = mv^2/R \implies T = mg + mv^2/R$.'),
  ('ap-topic-physc-tension-drills_q19', 'ap-topic-physc-tension-drills', 19, false, 'D', 'ap-topic-physc-tension', 'hard', 'A massive flexible cable passes over a fixed rough circular drum with coefficient of friction $\mu$. If the contact angle is $\beta$ radians, what is the capstan ratio of tensions $T_2 / T_1$ on impending slipping?', '["$T_2 / T_1 = 1 + \\mu\\beta$","$T_2 / T_1 = e^{-\\mu\\beta}$","$T_2 / T_1 = \\mu\\beta$","$T_2 / T_1 = e^{\\mu\\beta}$"]'::jsonb, 'The belt friction (capstan) formula derived from $dT = \mu T d\theta$ integrates to $\ln(T_2/T_1) = \mu\beta \implies T_2 = T_1 e^{\mu\beta}$.'),
  ('ap-topic-physc-tension-drills_q20', 'ap-topic-physc-tension-drills', 20, false, 'A', 'ap-topic-physc-tension', 'medium', 'Two blocks of masses $m_1$ and $m_2$ ($m_1 < m_2$) are connected by a light string over an ideal pulley of mass $M$ and radius $R$ ($I = \frac{1}{2}MR^2$). How does the tension $T_1$ supporting $m_1$ compare to $T_2$ supporting $m_2$ during acceleration?', '["$T_2 > T_1$ because a net torque is required to angularly accelerate the massive pulley","$T_1 = T_2$ because the string is continuous and massless","$T_1 > T_2$ because $m_1$ is accelerating upward","$T_1 = 0$ while $T_2 = m_2 g$"]'::jsonb, 'For a pulley with rotational inertia $I > 0$, net torque $(T_2 - T_1)R = I\alpha > 0$, which strictly requires $T_2 > T_1$.'),
  ('ap-topic-physc-inclines-drills_q1', 'ap-topic-physc-inclines-drills', 1, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #1:</strong> For the block on the incline setup shown below, derive the acceleration and equilibrium conditions:</p><p class="ques"><strong>1.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0069-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="number"><strong>1.</strong> <img alt="Images" class="q-img" src="images/e0070-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-inclines-drills_q2', 'ap-topic-physc-inclines-drills', 2, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #2:</strong> For the block on the incline setup shown below, derive the acceleration and equilibrium conditions:</p><p class="ques"><strong>2.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0069-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="number"><strong>2.</strong> <img alt="Images" class="q-img" src="images/e0070-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-inclines-drills_q3', 'ap-topic-physc-inclines-drills', 3, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #3:</strong> For the block on the incline setup shown below, derive the acceleration and equilibrium conditions:</p><p class="ques"><strong>3.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0069-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="number"><strong>3.</strong> <img alt="Images" class="q-img" src="images/e0070-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-inclines-drills_q4', 'ap-topic-physc-inclines-drills', 4, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #4:</strong> For the block on the incline setup shown below, derive the acceleration and equilibrium conditions:</p><p class="ques"><strong>4.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0069-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="number"><strong>4.</strong> <img alt="Images" class="q-img" src="images/e0070-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-inclines-drills_q5', 'ap-topic-physc-inclines-drills', 5, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #5:</strong> For the block on the incline setup shown below, derive the acceleration and equilibrium conditions:</p><p class="ques"><strong>5.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0070-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="number"><strong>5.</strong> Here the angle of the plane is 27° by trigonometry, and the distance along the plane is 22 m.</p><p class="numbern"><img alt="Images" class="q-img" src="images/e0070-05.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-inclines-drills_q6', 'ap-topic-physc-inclines-drills', 6, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #6:</strong> For the block on the incline setup shown below, derive the acceleration and equilibrium conditions:</p><p class="ques"><strong>6.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0070-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="number"><strong>6.</strong> <img alt="Images" class="q-img" src="images/e0070-06.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-inclines-drills_q7', 'ap-topic-physc-inclines-drills', 7, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #7:</strong> For the block on the incline setup shown below, derive the acceleration and equilibrium conditions:</p><p class="ques"><strong>7.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0070-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="number"><strong>7.</strong> <img alt="Images" class="q-img" src="images/e0070-07.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-inclines-drills_q8', 'ap-topic-physc-inclines-drills', 8, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #8:</strong> For the block on the incline setup shown below, derive the acceleration and equilibrium conditions:</p><p class="ques"><strong>8.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0070-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="right">Careful—this one’s tricky.</p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="number"><strong>8.</strong> This one is complicated. Since the direction of the friction force changes depending on whether the block is sliding up or down the plane, the block’s acceleration is NOT constant throughout the whole problem. So, unlike problem #7, this one can’t be solved in a single step. Instead, in order to use kinematics equations, you must break this problem up into two parts: up the plane and down the plane. During each of these individual parts, the acceleration is constant, so the kinematics equations are valid.</p><p class="bullet1">• up the plane:</p><p class="bullet1n">$a$ = 6.8 m/$s^{2}$, down the plane.</p><p class="bullet1n">$t$ = 0.4 s before the block turns around to come down the plane.</p><p class="bullet1">• down the plane:</p><p class="bullet1n"><img alt="Images" class="q-img" src="images/e0071-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="indentt">So, a total of $t$ = 5.6 s for the block to go up and back down.</p><h4 class="h4">Step-by-Step Solution to #1:</h4><p class="noindent"><em>Step 1:</em> Free-body diagram:</p><p class="image"><img alt="Images" class="q-img" src="images/f0071-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent"><em>Step 2:</em> Break vectors into components. Because we have an incline, we use inclined axes, one parallel and one perpendicular to the incline:</p><p class="image"><img alt="Images" class="q-img" src="images/f0071-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent"><em>Step 3:</em> Write Newton’s second law for each axis. The acceleration is entirely directed parallel to the plane, so perpendicular acceleration can be written as zero:</p><p class="image"><img alt="Images" class="q-img" src="images/e0071-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent"><em>Step 4:</em> Solve algebraically for $a$. This can be done without reference to the second equation. (In problems with friction, use $F_{f}$ = <em>μF</em><sub>N</sub> to relate the two equations.)</p><p class="image"><img alt="Images" class="q-img" src="images/e0071-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">To find the time, plug into a kinematics chart:</p><p class="image"><img alt="Images" class="q-img" src="images/e0071-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="noindent">Solve for $t$ using the second star equation for kinematics (**): <img alt="Images" class="q-img" src="images/e0072-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/> where <em>$ν_{o}$</em> is zero;</p><p class="image"><img alt="Images" class="q-img" src="images/e0072-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-inclines-drills_q9', 'ap-topic-physc-inclines-drills', 9, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #9:</strong> A mass $m$ is released from rest on an inclined plane of angle $\theta = 30^\circ$ with friction coefficient $\mu_k = 0.20$. Find the time taken to slide a distance $d = 10\text{ m}$ down the incline ($g = 10\text{ m/s}^2$).</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$a = 3.27\text{ m/s}^2$, $t = 2.47\text{ s}$.</p>'),
  ('ap-topic-physc-inclines-drills_q10', 'ap-topic-physc-inclines-drills', 10, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #10:</strong> A mass $m$ is released from rest on an inclined plane of angle $\theta = 30^\circ$ with friction coefficient $\mu_k = 0.20$. Find the time taken to slide a distance $d = 10\text{ m}$ down the incline ($g = 10\text{ m/s}^2$).</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$a = 3.27\text{ m/s}^2$, $t = 2.47\text{ s}$.</p>'),
  ('ap-topic-physc-inclines-drills_q11', 'ap-topic-physc-inclines-drills', 11, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #11:</strong> A mass $m$ is released from rest on an inclined plane of angle $\theta = 30^\circ$ with friction coefficient $\mu_k = 0.20$. Find the time taken to slide a distance $d = 10\text{ m}$ down the incline ($g = 10\text{ m/s}^2$).</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$a = 3.27\text{ m/s}^2$, $t = 2.47\text{ s}$.</p>'),
  ('ap-topic-physc-inclines-drills_q12', 'ap-topic-physc-inclines-drills', 12, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #12:</strong> A mass $m$ is released from rest on an inclined plane of angle $\theta = 30^\circ$ with friction coefficient $\mu_k = 0.20$. Find the time taken to slide a distance $d = 10\text{ m}$ down the incline ($g = 10\text{ m/s}^2$).</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$a = 3.27\text{ m/s}^2$, $t = 2.47\text{ s}$.</p>'),
  ('ap-topic-physc-inclines-drills_q13', 'ap-topic-physc-inclines-drills', 13, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #13:</strong> A mass $m$ is released from rest on an inclined plane of angle $\theta = 30^\circ$ with friction coefficient $\mu_k = 0.20$. Find the time taken to slide a distance $d = 10\text{ m}$ down the incline ($g = 10\text{ m/s}^2$).</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$a = 3.27\text{ m/s}^2$, $t = 2.47\text{ s}$.</p>'),
  ('ap-topic-physc-inclines-drills_q14', 'ap-topic-physc-inclines-drills', 14, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #14:</strong> A mass $m$ is released from rest on an inclined plane of angle $\theta = 30^\circ$ with friction coefficient $\mu_k = 0.20$. Find the time taken to slide a distance $d = 10\text{ m}$ down the incline ($g = 10\text{ m/s}^2$).</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$a = 3.27\text{ m/s}^2$, $t = 2.47\text{ s}$.</p>'),
  ('ap-topic-physc-inclines-drills_q15', 'ap-topic-physc-inclines-drills', 15, true, 'FRQ_MANUAL_EVALUATION', 'Inclined Planes', 'medium', '<p><strong>Inclined Planes Drill #15:</strong> A mass $m$ is released from rest on an inclined plane of angle $\theta = 30^\circ$ with friction coefficient $\mu_k = 0.20$. Find the time taken to slide a distance $d = 10\text{ m}$ down the incline ($g = 10\text{ m/s}^2$).</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$a = 3.27\text{ m/s}^2$, $t = 2.47\text{ s}$.</p>'),
  ('ap-topic-physc-inclines-drills_q16', 'ap-topic-physc-inclines-drills', 16, false, 'A', 'ap-topic-physc-inclines', 'medium', 'A block of mass $m$ is given an initial speed $v_0$ up an incline of angle $\theta$ with coefficient of kinetic friction $\mu_k$. What is the magnitude of the block''s acceleration as it slides up the ramp?', '["$a = g(\\sin\\theta + \\mu_k\\cos\\theta)$ down the ramp","$a = g(\\sin\\theta - \\mu_k\\cos\\theta)$ down the ramp","$a = g\\sin\\theta$ down the ramp","$a = g\\mu_k\\cos\\theta$ up the ramp"]'::jsonb, 'When moving upward, both gravity along the ramp ($mg\sin\theta$) and kinetic friction ($f_k = \mu_k mg\cos\theta$) oppose the motion: $\sum F = m a \implies a = g(\sin\theta + \mu_k\cos\theta)$ downward.'),
  ('ap-topic-physc-inclines-drills_q17', 'ap-topic-physc-inclines-drills', 17, false, 'B', 'ap-topic-physc-inclines', 'medium', 'A uniform sphere of mass $M$ and radius $R$ ($I = \frac{2}{5}MR^2$) rolls without slipping down an incline of angle $\theta$. What is the linear acceleration of its center of mass?', '["$a = \\frac{2}{3}g\\sin\\theta$","$a = \\frac{5}{7}g\\sin\\theta$","$a = g\\sin\\theta$","$a = \\frac{1}{2}g\\sin\\theta$"]'::jsonb, '$a = \frac{g\sin\theta}{1 + I/(MR^2)} = \frac{g\sin\theta}{1 + 2/5} = \frac{5}{7}g\sin\theta$.'),
  ('ap-topic-physc-inclines-drills_q18', 'ap-topic-physc-inclines-drills', 18, false, 'C', 'ap-topic-physc-inclines', 'hard', 'What minimum coefficient of static friction $\mu_s$ is required to prevent a cylinder ($I = \frac{1}{2}MR^2$) from slipping as it rolls down an incline of angle $\theta$?', '["$\\mu_s \\ge \\tan\\theta$","$\\mu_s \\ge \\frac{1}{2}\\tan\\theta$","$\\mu_s \\ge \\frac{1}{3}\\tan\\theta$","$\\mu_s \\ge \\frac{2}{3}\\tan\\theta$"]'::jsonb, 'Linear acceleration is $a = \frac{2}{3}g\sin\theta$. Torque equation: $f_s R = I\alpha = (\frac{1}{2}MR^2)(a/R) \implies f_s = \frac{1}{3}Mg\sin\theta$. Condition $f_s \le \mu_s F_N = \mu_s Mg\cos\theta \implies \mu_s \ge \frac{1}{3}\tan\theta$.'),
  ('ap-topic-physc-inclines-drills_q19', 'ap-topic-physc-inclines-drills', 19, false, 'D', 'ap-topic-physc-inclines', 'easy', 'A block is released from rest at the top of a frictionless curved incline of height $h$. What is its speed upon reaching the horizontal floor?', '["$v = \\sqrt{gh}$","$v = \\sqrt{2gh\\sin\\theta}$","$v = 2gh$","$v = \\sqrt{2gh}$ regardless of the exact profile or curvature of the ramp"]'::jsonb, 'Because the normal force does zero work along the frictionless surface, mechanical energy is conserved: $mgh = \frac{1}{2}mv^2 \implies v = \sqrt{2gh}$ independent of ramp geometry.'),
  ('ap-topic-physc-inclines-drills_q20', 'ap-topic-physc-inclines-drills', 20, false, 'A', 'ap-topic-physc-inclines', 'easy', 'A block slides down a rough incline and comes to rest on a rough horizontal surface. If the incline angle is $\theta$ and friction coefficient is $\mu$ everywhere, what is the net work done by gravity and friction combined from start to finish?', '["Zero, because initial and final kinetic energies are both zero","$mgh$","$-mgh$","$\\frac{1}{2}mv_0^2$"]'::jsonb, 'By the Work-Energy Theorem: $W_{net} = \Delta K = K_f - K_i = 0 - 0 = 0$.')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-physc-graphs-drills_q1', 'ap-topic-physc-graphs-drills', 1, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #1:</strong> Analyze the motion graph shown below to describe the motion and determine the required kinematics parameters:</p><p class="ques"><strong>(1)</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0072-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>1.</strong> The average speed over the first 5 s is 10 m/s, or about 22 mph. So:</p><p class="quesna">Someone rolls a bowling ball along a smooth road. When the graph starts, the bowling ball is moving along pretty fast, but the ball encounters a long hill. So, the ball slows down, coming to rest after 5 s. Then, the ball comes back down the hill, speeding up the whole way.</p>'),
  ('ap-topic-physc-graphs-drills_q2', 'ap-topic-physc-graphs-drills', 2, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #2:</strong> Analyze the motion graph shown below to describe the motion and determine the required kinematics parameters:</p><p class="ques"><strong>(2)</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0072-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>2.</strong> This motion only lasts 1 s, and the maximum speed involved is about 5 mph. So:</p><p class="quesna">A biker has been cruising up a hill. When the graph starts, the biker is barely moving at jogging speed. Within half a second, and after traveling only a meter up the hill, the bike turns around, speeding up as it goes back down the hill.</p>'),
  ('ap-topic-physc-graphs-drills_q3', 'ap-topic-physc-graphs-drills', 3, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #3:</strong> Analyze the motion graph shown below to describe the motion and determine the required kinematics parameters:</p><p class="ques"><strong>(3)</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0072-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>3.</strong> The maximum speed of this thing is 30 cm/s, or about a foot per second. So:</p><p class="quesna">A toy racecar is moving slowly along its track. The track goes up a short hill that’s about a foot long. After 2 s, the car has just barely reached the top of the hill, and is perched there momentarily; then, the car crests the hill and speeds up as it goes down the other side.</p>'),
  ('ap-topic-physc-graphs-drills_q4', 'ap-topic-physc-graphs-drills', 4, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #4:</strong> Analyze the motion graph shown below to describe the motion and determine the required kinematics parameters:</p><p class="ques"><strong>(4)</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0072-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>4.</strong> The steady speed over 200 s (a bit over 3 minutes) is 0.25 m/s, or 25 cm/s, or about a foot per second.</p><p class="quesna">A cockroach crawls steadily along the school’s running track, searching for food. The cockroach starts near the 50-yard line of the football field; around 3 minutes later, the cockroach reaches the goal line and, having found nothing of interest, turns around and crawls at the same speed back toward his starting point.</p>'),
  ('ap-topic-physc-graphs-drills_q5', 'ap-topic-physc-graphs-drills', 5, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #5:</strong> Analyze the motion graph shown below to describe the motion and determine the required kinematics parameters:</p><p class="ques"><strong>(5)</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0072-05.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>5.</strong> The maximum speed here is 50 m/s, or over 100 mph, changing speed dramatically in only 5 or 10 s. So:</p><p class="quesna">A small airplane is coming in for a landing. Upon touching the ground, the pilot puts the engines in reverse, slowing the plane. But wait! The engine throttle is stuck! So, although the plane comes to rest in 5 s, the engines are still on. The plane starts speeding up backwards! Oops . . .</p>'),
  ('ap-topic-physc-graphs-drills_q6', 'ap-topic-physc-graphs-drills', 6, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #6:</strong> Analyze the motion graph shown below to describe the motion and determine the required kinematics parameters:</p><p class="ques"><strong>(6)</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0072-06.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>6.</strong> This thing covers 5 meters in 3 seconds, speeding up the whole time.</p><p class="quesna">An 8-year-old gets on his dad’s bike. The boy is not really strong enough to work the pedals easily, so he starts off with difficulty. But, after a few seconds he’s managed to speed the bike up to a reasonable clip.</p>'),
  ('ap-topic-physc-graphs-drills_q7', 'ap-topic-physc-graphs-drills', 7, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #7:</strong> Analyze the motion graph shown below to describe the motion and determine the required kinematics parameters:</p><p class="ques"><strong>(7)</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0073-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>7.</strong> Though this thing moves quickly—while moving, the speed is 1 m/s—the total distance covered is 1 mm forward, and 1 mm back; the whole process takes 5 ms, which is less than the minimum time interval indicated by a typical stopwatch. So we’ll have to be a bit creative:</p><p class="quesna">In the <em>Discworld</em> novels by Terry Pratchett, wizards have developed a computer in which living ants in tubes, rather than electrons in wires and transistors, carry information. (Electricity has not been harnessed on the Discworld.) In performing a calculation, one of these ants moves forward a distance of 1 mm, stays in place for 3 ms, and returns to the original position. If this ant’s motion represents two typical “operations” performed by the computer, then this computer has an approximate processing speed of 400 Hz times the total number of ants inside.</p>'),
  ('ap-topic-physc-graphs-drills_q8', 'ap-topic-physc-graphs-drills', 8, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #8:</strong> Analyze the motion graph shown below to describe the motion and determine the required kinematics parameters:</p><p class="ques"><strong>(8)</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0073-02.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>8.</strong> Though this graph <em>looks</em> like #7, this one is a velocity–time graph, and so indicates completely different motion.</p><p class="quesna">A small child pretends he is a bulldozer. Making a “brm-brm-brm” noise with his lips, he speeds up from rest to a slow walk. He walks for three more seconds, then slows back down to rest. He moved forward the entire time, traveling a total distance (found from the area under the graph) of 4 m.</p>'),
  ('ap-topic-physc-graphs-drills_q9', 'ap-topic-physc-graphs-drills', 9, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #9:</strong> Analyze the motion graph shown below to describe the motion and determine the required kinematics parameters:</p><p class="ques"><strong>(9)</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0073-03.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>9.</strong> This stuff moves 300 million meters in 1 s at a constant speed. There’s only one possibility here: electromagnetic waves in a vacuum.</p><p class="quesna">Light (or electromagnetic radiation of any frequency) is emitted from the surface of the moon. In 1 s, the light has covered about half the distance to Earth.</p>'),
  ('ap-topic-physc-graphs-drills_q10', 'ap-topic-physc-graphs-drills', 10, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #10:</strong> Analyze the motion graph shown below to describe the motion and determine the required kinematics parameters:</p><p class="ques"><strong>(10)</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0073-04.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>10.</strong> Be careful about axis labels: this is an <em>acceleration</em>–time graph. Something is accelerating at 1000 cm/$s^{2}$ for a few seconds. 1000 cm/$s^{2}$ = 10 m/$s^{2}$, about Earth’s gravitational acceleration. Using kinematics, we calculate that if we drop something from rest near Earth, after 4 s the thing has dropped 80 m.</p><p class="quesna">One way to simulate the effects of zero gravity is to drop an experiment from the top of a high tower. Then, because everything that was dropped is speeding up at the same rate, the effect is just as if the experiment were done in the Space Shuttle—at least until everything hits the ground. In this case, an experiment is dropped from a 250-ft tower, hitting the ground with a speed close to 90 mph.</p>'),
  ('ap-topic-physc-graphs-drills_q11', 'ap-topic-physc-graphs-drills', 11, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #11:</strong> Analyze the motion graph shown below to describe the motion and determine the required kinematics parameters:</p><p class="ques"><strong>(11)</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0073-05.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>11.</strong> One cm/s is ridiculously slow. Let’s use the world of slimy animals:</p><p class="quesna">A snail wakes up from his nap and decides to find some food. He speeds himself up from rest to his top speed in 10 s. During this time, he’s covered 5 cm, or about the length of your pinkie finger. He continues to slide along at a steady 1 cm/s, which means that a minute later he’s gone no farther than a couple of feet. Let’s hope that food is close.</p>'),
  ('ap-topic-physc-graphs-drills_q12', 'ap-topic-physc-graphs-drills', 12, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #12:</strong> Analyze the motion graph shown below to describe the motion and determine the required kinematics parameters:</p><p class="ques"><strong>(12)</strong></p><p class="image"><img alt="Images" class="q-img" src="images/f0073-06.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>', '["Submit analytical / algebraic result in workspace."]'::jsonb, '<p class="ques"><strong>12.</strong> This one looks a bit like those up-and-down-a-hill graphs, but with an important difference—this time the thing stops not just for an instant, but for five whole seconds, before continuing back toward the starting point.</p><p class="quesna">A bicyclist coasts to the top of a shallow hill, slowing down from cruising speed (~15 mph) to rest in 15 s. At the top, she pauses briefly to turn her bike around; then, she releases the brake and speeds up as she goes back down the hill.</p>'),
  ('ap-topic-physc-graphs-drills_q13', 'ap-topic-physc-graphs-drills', 13, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #13:</strong> An object moves with velocity $v(t) = 4t - t^2\text{ m/s}$ from $t = 0$ to $t = 4\text{ s}$. Find the total distance traveled and average velocity.</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$\Delta x = 10.67\text{ m}$, $v_{\text{avg}} = 2.67\text{ m/s}$.</p>'),
  ('ap-topic-physc-graphs-drills_q14', 'ap-topic-physc-graphs-drills', 14, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #14:</strong> An object moves with velocity $v(t) = 4t - t^2\text{ m/s}$ from $t = 0$ to $t = 4\text{ s}$. Find the total distance traveled and average velocity.</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$\Delta x = 10.67\text{ m}$, $v_{\text{avg}} = 2.67\text{ m/s}$.</p>'),
  ('ap-topic-physc-graphs-drills_q15', 'ap-topic-physc-graphs-drills', 15, true, 'FRQ_MANUAL_EVALUATION', 'Motion Graphs', 'medium', '<p><strong>Motion Graphs Drill #15:</strong> An object moves with velocity $v(t) = 4t - t^2\text{ m/s}$ from $t = 0$ to $t = 4\text{ s}$. Find the total distance traveled and average velocity.</p>', '["Submit analytical derivation in workspace."]'::jsonb, '<p>$\Delta x = 10.67\text{ m}$, $v_{\text{avg}} = 2.67\text{ m/s}$.</p>'),
  ('ap-topic-physc-graphs-drills_q16', 'ap-topic-physc-graphs-drills', 16, false, 'A', 'ap-topic-physc-graphs', 'easy', 'Given a potential energy function $U(x)$, what graphical property determines the force $F(x)$ acting on a particle at position $x$?', '["The negative of the slope of $U(x)$: $F(x) = -\\dfrac{dU}{dx}$","The area under the $U(x)$ curve","The curvature $\\dfrac{d^2U}{dx^2}$","The value of $U(x)$ divided by $x$"]'::jsonb, 'Force is defined as the negative spatial gradient of potential energy: $F(x) = -dU/dx$.'),
  ('ap-topic-physc-graphs-drills_q17', 'ap-topic-physc-graphs-drills', 17, false, 'B', 'ap-topic-physc-graphs', 'easy', 'At a local minimum of a potential energy curve $U(x)$ where $\dfrac{dU}{dx} = 0$ and $\dfrac{d^2U}{dx^2} > 0$, the equilibrium is:', '["Unstable equilibrium","Stable equilibrium","Neutral equilibrium","Dynamic equilibrium"]'::jsonb, 'A positive second derivative ($d^2U/dx^2 > 0$) means a restoring force pushes the particle back toward the minimum upon perturbation, creating stable equilibrium.'),
  ('ap-topic-physc-graphs-drills_q18', 'ap-topic-physc-graphs-drills', 18, false, 'C', 'ap-topic-physc-graphs', 'easy', 'The area bounded by an acceleration-time graph ($a$ vs $t$) from $t_1$ to $t_2$ represents:', '["Total displacement $\\Delta x$","Average speed","Change in velocity $\\Delta v$","Instantaneous position"]'::jsonb, 'By definition, $\Delta v = \int_{t_1}^{t_2} a(t) dt$, which is the area under the acceleration-time curve.'),
  ('ap-topic-physc-graphs-drills_q19', 'ap-topic-physc-graphs-drills', 19, false, 'D', 'ap-topic-physc-graphs', 'medium', 'A velocity-versus-position graph $v(x)$ is given for a particle. How can the acceleration $a(x)$ be determined at any point $x$?', '["$a = \\dfrac{dv}{dx}$","$a = \\int v dx$","$a = \\dfrac{v^2}{x}$","$a = v\\dfrac{dv}{dx}$"]'::jsonb, 'By the chain rule: $a = \frac{dv}{dt} = \frac{dv}{dx}\frac{dx}{dt} = v\frac{dv}{dx}$.'),
  ('ap-topic-physc-graphs-drills_q20', 'ap-topic-physc-graphs-drills', 20, false, 'A', 'ap-topic-physc-graphs', 'easy', 'If a force-displacement graph shows $F(x) = cx^2$, what is the total work done by this force from $x = 0$ to $x = X$?', '["$W = \\frac{1}{3}cX^3$","$W = \\frac{1}{2}cX^2$","$W = cX^3$","$W = 2cX$"]'::jsonb, '$W = \int_0^X F(x)dx = \int_0^X cx^2 dx = \frac{1}{3}cX^3$.'),
  ('ap-topic-physc-mech-fundamentals_q1', 'ap-topic-physc-mech-fundamentals', 1, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #1:</strong></p><p class="numbert"><strong>1.</strong> What is the mass of a block with weight 100 N?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="numbert"><strong>1.</strong> Weight is <em>mg.</em> So, mass is weight divided by $g$, which would be 100 N/(10 N/kg) = 10 kg.</p>'),
  ('ap-topic-physc-mech-fundamentals_q2', 'ap-topic-physc-mech-fundamentals', 2, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #2:</strong></p><p class="number"><strong>2.</strong> Give the equations for two types of potential energy, identifying each.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>2.</strong> PE = <em>mgh,</em> gravitational potential energy;<br/><img alt="Images" class="q-img" src="images/e0027-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/>, potential energy of a spring.</p>'),
  ('ap-topic-physc-mech-fundamentals_q3', 'ap-topic-physc-mech-fundamentals', 3, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #3:</strong></p><p class="number"><strong>3.</strong> When an object of mass $m$ is on an incline of angle $\theta$, one must break the weight of the object into components parallel and perpendicular to the incline.</p><p class="roman">i. What is the component of the weight parallel to the incline?_________</p><p class="roman">ii. What is the component of the weight perpendicular to the incline?_________</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>3.</strong> i. <em>mg</em> sin $\theta$ is parallel to the incline.<br/>ii. <em>mg</em> cos $\theta$ is perpendicular to the incline.</p>'),
  ('ap-topic-physc-mech-fundamentals_q4', 'ap-topic-physc-mech-fundamentals', 4, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #4:</strong></p><p class="number"><strong>4.</strong> Write two expressions for work, including the definition of work and the work-energy principle.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>4.</strong> The definition of work is work = force times parallel displacement.<br/>The work-energy principle states that net work = change in kinetic energy.</p>'),
  ('ap-topic-physc-mech-fundamentals_q5', 'ap-topic-physc-mech-fundamentals', 5, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #5:</strong></p><p class="number"><strong>5.</strong> Quickly identify as a vector or a scalar:</p><p class="numbernt">_____ acceleration</p><p class="numbern">_____ velocity</p><p class="numbern">_____ work</p><p class="numbern">_____ force</p><p class="numbern">_____ speed</p><p class="numbern">_____ mass</p><p class="numbern">_____ momentum</p><p class="numbern">_____ displacement</p><p class="numbernb">_____ kinetic energy</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>5.</strong> vectors: acceleration, force, momentum, velocity, displacement scalars: speed, work, mass, kinetic energy</p>'),
  ('ap-topic-physc-mech-fundamentals_q6', 'ap-topic-physc-mech-fundamentals', 6, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #6:</strong></p><p class="number"><strong>6.</strong> Name at least four things that can NEVER go on a free-body diagram.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>6.</strong> Only forces acting on an object and that have a single, specific source can go on free-body diagrams. Some of the things that cannot go on a free-body diagram but that students often put there by mistake:</p><p class="numbern"><img alt="Images" class="q-img" src="images/t0028-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p>'),
  ('ap-topic-physc-mech-fundamentals_q7', 'ap-topic-physc-mech-fundamentals', 7, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #7:</strong></p><p class="number"><strong>7.</strong> Write two expressions for impulse. What are the units of impulse?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>7.</strong> Impulse is force times time interval, and also change in momentum. Impulse has units either of newton·seconds or kilogram·meters/second.</p>'),
  ('ap-topic-physc-mech-fundamentals_q8', 'ap-topic-physc-mech-fundamentals', 8, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #8:</strong></p><p class="number"><strong>8.</strong> In what kind of collision is momentum conserved? In what kind of collision is kinetic energy conserved?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>8.</strong> Momentum is conserved in <em>all</em> collisions. Kinetic energy is conserved only in elastic collisions.</p>'),
  ('ap-topic-physc-mech-fundamentals_q9', 'ap-topic-physc-mech-fundamentals', 9, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #9:</strong></p><p class="number"><strong>9.</strong> What is the mass of a block with weight $W$?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>9.</strong> Using the reasoning from question #1, if weight is <em>mg,</em> then $m = W$/<em>g.</em></p>'),
  ('ap-topic-physc-mech-fundamentals_q10', 'ap-topic-physc-mech-fundamentals', 10, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #10:</strong></p><p class="number"><strong>10.</strong> A ball is thrown straight up. At the peak of its flight, what is the ball’s acceleration? Be sure to give both magnitude and direction.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>10.</strong> The acceleration of a projectile is <em>always g</em>; i.e., 10 m/$s^{2}$, downward. Even though the velocity is instantaneously zero, the velocity is still changing, so the acceleration is <em>not</em> zero. (By the way, the answer “−10 m/$s^{2}$” is wrong unless you have clearly and specifically defined the down direction as negative for this problem.)</p>'),
  ('ap-topic-physc-mech-fundamentals_q11', 'ap-topic-physc-mech-fundamentals', 11, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #11:</strong></p><p class="number"><strong>11.</strong> A mass experiences a force vector with components 30 N to the right, 40 N down. Explain how to determine the magnitude and direction (angle) of the force vector.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>11.</strong> The magnitude of the resultant force is found by placing the component vectors tip-to-tail. This gives a right triangle, so the magnitude is given by the Pythagorean theorem, 50 N. The angle of the resultant force is found by taking the inverse tangent of the vertical component over the horizontal component, ta$n^{-1}$ (40/30). This gives the angle measured from the horizontal.</p>'),
  ('ap-topic-physc-mech-fundamentals_q12', 'ap-topic-physc-mech-fundamentals', 12, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #12:</strong></p><p class="number"><strong>12.</strong> Write the definition of the coefficient of friction, $\mu$. What are the units of $\mu$?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>12.</strong></p><p class="image"><img alt="Images" class="q-img" src="images/e0028-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/></p><p class="numbern">friction force divided by normal force. $\mu$ has no units.</p>'),
  ('ap-topic-physc-mech-fundamentals_q13', 'ap-topic-physc-mech-fundamentals', 13, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #13:</strong></p><p class="number"><strong>13.</strong> How do you find acceleration from a velocity-time graph?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>13.</strong> Acceleration is the slope of a velocity-time graph.</p>'),
  ('ap-topic-physc-mech-fundamentals_q14', 'ap-topic-physc-mech-fundamentals', 14, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #14:</strong></p><p class="number"><strong>14.</strong> How do you find displacement from a velocity-time graph?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>14.</strong> Displacement is the area under a velocity-time graph (i.e., the area between the graph and the horizontal axis).</p>'),
  ('ap-topic-physc-mech-fundamentals_q15', 'ap-topic-physc-mech-fundamentals', 15, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #15:</strong></p><p class="number"><strong>15.</strong> How do you find velocity from a position-time graph?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>15.</strong> Velocity is the slope of a position-time graph. If the position-time graph is curved, then instantaneous velocity is the slope of the tangent line to the graph.</p>'),
  ('ap-topic-physc-mech-fundamentals_q16', 'ap-topic-physc-mech-fundamentals', 16, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #16:</strong></p><p class="number"><strong>16.</strong> An object has a positive acceleration. Explain <em>briefly</em> how to determine whether the object is speeding up, slowing down, or moving with constant speed.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>16.</strong> Because acceleration is not zero, the object <em>cannot</em> be moving with constant speed. If the signs of acceleration and velocity are the same (here, if velocity is positive), the object is speeding up. If the signs of acceleration and velocity are different (here, if velocity is negative), the object is slowing down.</p>'),
  ('ap-topic-physc-mech-fundamentals_q17', 'ap-topic-physc-mech-fundamentals', 17, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #17:</strong></p><p class="number"><strong>17.</strong> Given the velocity of an object, how do you tell which direction that object is moving?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>17.</strong> An object <em>always</em> moves in the direction indicated by the velocity.</p>'),
  ('ap-topic-physc-mech-fundamentals_q18', 'ap-topic-physc-mech-fundamentals', 18, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #18:</strong></p><p class="number"><strong>18.</strong> When is the gravitational force on an object <em>mg</em>? When is the gravitational force <em>G$m_{1} m_{2}$</em>/$r^{2}$?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>18.</strong> Near the surface of a planet, <em>mg</em> gives the gravitational force. Newton’s law of gravitation, <em>G$m_{1} m_{2}$</em>/$r^{2}$<em>,</em> is valid everywhere in the universe<em>.</em> (It turns out that $g$ can be found by calculating <em>GM</em><sub>planet</sub>/$R_{planet}$<sup>2</sup>, where $R_{planet}$ is the planet’s radius.)</p>'),
  ('ap-topic-physc-mech-fundamentals_q19', 'ap-topic-physc-mech-fundamentals', 19, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #19:</strong></p><p class="number"><strong>19.</strong> What is the direction of the net force on an object that moves in a circle at constant speed?</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>19.</strong> An object in uniform circular motion experiences a <em>centripetal,</em> meaning “center seeking,” force. This force must be directed to the center of the circle.</p>'),
  ('ap-topic-physc-mech-fundamentals_q20', 'ap-topic-physc-mech-fundamentals', 20, true, 'FRQ_MANUAL_EVALUATION', 'Mechanics Fundamentals', 'medium', '<p><strong>Mechanics Core Concept #20:</strong></p><p class="number"><strong>20.</strong> Under what conditions is the equation <img alt="Images" class="q-img" src="images/e0026-01.jpg" style="max-width: 100%; height: auto; margin: 10px 0; display: block;"/> valid? Give a specific situation in which this equation might seem to be valid, but is NOT.</p>', '["Submit response / explanation in workspace."]'::jsonb, '<p class="number"><strong>20.</strong> This and all three kinematics equations are valid only when acceleration is constant. So, for example, this equation can NOT be used to find the distance travelled by a mass attached to a spring. The spring force changes as the mass moves; thus, the acceleration of the mass is changing, and kinematics equations are not valid. (On a problem where kinematics equations aren’t valid, conservation of energy usually is what you need.)</p>'),
  ('ap-mock-physc-mech-full-1_q1', 'ap-mock-physc-mech-full-1', 1, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'A constant horizontal force F applied to a block on an incline causes the block to move a distance d along the incline, as shown. If the coefficient of friction between the block and the incline is \muk, what is the work done by the applied force? (Do not assume that the block moves at constant velocity.)', '["W = Fd sin \\theta","W = Fd cos \\theta","W = mgd sin \\theta","W = mgd sin \\theta − \\muk mgd cos \\theta","W = mgd sin \\theta + \\mukd(mg cos \\theta + F sin \\theta)"]'::jsonb, '(B) Because the force is constant, the work is given by the dot product of the force and the displacement vectors: Choice (C) is the change in potential energy as the block is elevated. Choice (E) is the work that would have to be done by F to move the block up the incline at a constant speed; that is, the work done by F would be the negative of the work done by gravity and by friction (because the net work would have to be zero).'),
  ('ap-mock-physc-mech-full-1_q2', 'ap-mock-physc-mech-full-1', 2, false, 'E', 'Practice Test 1 – Mechanics', 'medium', 'The restoring force that acts on a mass is shown. For small amplitudes, the mass moves in simple harmonic motion with a period T. Which of the following is true of oscillations with larger amplitudes?', '["The motion is SHM with a period of T.","The motion is SHM with a period smaller than T.","The motion is SHM with a period larger than T.","The motion is no longer SHM, and its period is smaller than T.","The motion is no longer SHM, and its period is larger than T."]'::jsonb, '(E) See the figure. For large-amplitude oscillations, the restoring force is not linear, so the motion is not simple harmonic motion. Because the restoring force is smaller than its linear approximation about the origin (which would produce a period of T), it produces motion with a larger period. (Because the force is smaller, the particle oscillates more slowly and more time is required for each cycle.)'),
  ('ap-mock-physc-mech-full-1_q3', 'ap-mock-physc-mech-full-1', 3, false, 'C', 'Practice Test 1 – Mechanics', 'medium', 'A simple pendulum of length ℓ is moved to Mars (where g = 3.71 m/s2). Its period on Earth is 2.0 s. Its period on Mars is', '["0.02 s","2.0 s","3.25 s","600 s","6,000 s"]'::jsonb, '(C) The period of a simple pendulum is given by . If the quantities on Mars are denoted by primes, then the period on Mars is given by , where the unprimed values are those on Earth (note that the length is unchanged). Thus, s.'),
  ('ap-mock-physc-mech-full-1_q4', 'ap-mock-physc-mech-full-1', 4, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'At the instant that a mass in simple harmonic motion passes through its equilibrium position its acceleration is', '["maximum","zero","oppositely directed to its velocity","parallel to its velocity","cannot be determined without additional information"]'::jsonb, '(B) A simple harmonic oscillator is characterized by a = −\omega2x (found by plugging Hooke’s law into Newtons’ second law). At equilibrium, x = 0 and thus the acceleration is also zero.'),
  ('ap-mock-physc-mech-full-1_q5', 'ap-mock-physc-mech-full-1', 5, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'A solid sphere has a rotational inertia of when rotated about an axis tangent to its surface as shown. What is the rotational inertia of the sphere when it is rotated about a line passing through the center of the sphere?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(B) According to the parallel axis theorem, the rotational inertia about an axis that does not pass through the center of mass (in this problem, the one that passes along the surface of the sphere) is equal to the rotational inertia about a parallel axis passing through the center of mass (in this problem, the axis passing through the sphere’s center) plus MD2, where D is the distance between the two axes (in this case, r): Solving this equation for the rotational inertia about the axis that passes through the center of mass yields choice (B).'),
  ('ap-mock-physc-mech-full-1_q6', 'ap-mock-physc-mech-full-1', 6, false, 'C', 'Practice Test 1 – Mechanics', 'medium', '<p>A simple pendulum of length L is released from rest with its string horizontal (Point I). It swings downward through a circular arc. At Point II (when the string makes a 45° angle with the vertical), what is the direction of the pendulum bob’s net acceleration vector?</p>', '["Purely radial toward the pivot center","Purely tangential in the direction of velocity","Inward and downward, angled between the radial and tangential directions","Directly downward toward the center of the Earth","Directly upward opposite gravity"]'::jsonb, '(C) Consider the figure. The pendulum is rotating in a circle, so it must experience a centripetal acceleration toward the center of the circle. The pendulum is also speeding up (because of conservation of energy, with gravitational potential energy being converted to kinetic energy), so it experiences a tangential acceleration parallel to its velocity. The sum of these accelerations produces a net acceleration that is neither purely radial nor purely tangential but rather points in the direction of choice (C).'),
  ('ap-mock-physc-mech-full-1_q7', 'ap-mock-physc-mech-full-1', 7, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'A mass m moving to the right with speed v collides and sticks to a mass of 3m moving upward with a speed 2v as shown. What is the final velocity of the two masses?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","(E) none of the above","Zero net change under static equilibrium conditions"]'::jsonb, '(B) This is an inelastic collision such that momentum is conserved and the final velocity of both masses is the same (because they stick together and move with a common velocity). Conservation of momentum yields Solving these equations yields choice (B).'),
  ('ap-mock-physc-mech-full-1_q8', 'ap-mock-physc-mech-full-1', 8, false, 'C', 'Practice Test 1 – Mechanics', 'medium', 'If a force of 2 N does work at the rate of on an object moving with a speed of 2 m/s, the angle between the force and the velocity vector must be', '["45°","120°","135°","150°","It is impossible to deliver a negative power."]'::jsonb, '(C) P = F \cdot  v. For the power to be negative, the force must have a component antiparallel to the velocity, as shown in the figure. Expressing the dot product as P = F \cdot  v = vF|| and substituting in numbers indicates that the component of the force antiparallel to the velocity has a magnitude of directed as shown. Given that the magnitude of the force is 2 N, trigonometry indicates that the angle between the force and the velocity is equal to 135°.'),
  ('ap-mock-physc-mech-full-1_q9', 'ap-mock-physc-mech-full-1', 9, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'A mass m is released from rest at t = 0 in a parabolic depression as shown. If there is no friction between the mass and the surface, which of the graphs shows the mass’s x-position as a function of time, assuming that the mass’s displacement from the origin is small?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(B) Since the gravitational potential energy is proportional to the height, a plot of potential energy vs position is a parabola similar to the y(x)-parabola. As in the case of a mass attached to a spring, whenever the plot of potential energy vs position is parabolic, there is a linear restoring force that gives rise to simple harmonic motion. Therefore, the position function is sinusoidal, initially having a positive value.'),
  ('ap-mock-physc-mech-full-1_q10', 'ap-mock-physc-mech-full-1', 10, false, 'A', 'Practice Test 1 – Mechanics', 'medium', 'A particle executes simple harmonic motion along the x-axis with equation x(t) = A cos(omega t + phi). Which of the following graphs correctly represents the acceleration a_x(t) as a function of position x?', '["A straight line through the origin with negative slope -omega^2","A straight line through the origin with positive slope +omega^2","A parabola opening upward","A sinusoidal curve with amplitude A omega","A horizontal straight line"]'::jsonb, 'Differentiating position twice: v(t) = -A omega sin(omega t + phi) and a(t) = -A omega^2 cos(omega t + phi) = -omega^2 x(t). Therefore, acceleration as a function of position is a(x) = -omega^2 x, which is a straight line through the origin with negative slope -omega^2.')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-mock-physc-mech-full-1_q11', 'ap-mock-physc-mech-full-1', 11, false, 'C', 'Practice Test 1 – Mechanics', 'medium', 'When is the power exerted by the gravitational force the greatest?', '["at the instant after the projectile is launched","at the peak of the trajectory","at the instant before the projectile hits Earth","The power is maximized at the points specified in both answer choices (A) and (B).","The power is constant."]'::jsonb, '(C) P = F \cdot  v. Therefore, the power is negative as the projectile moves away from Earth (because the velocity is antiparallel to the gravitational force), zero at the peak of the trajectory (when the velocity is zero), and positive as the projectile returns to Earth (because the velocity is parallel to Earth). The power is greatest the instant before the projectile hits Earth, at which point the velocity parallel to the force is greatest and the gravitational force is greatest.'),
  ('ap-mock-physc-mech-full-1_q12', 'ap-mock-physc-mech-full-1', 12, false, 'D', 'Practice Test 1 – Mechanics', 'medium', 'At which of the following points is the acceleration the greatest in magnitude?', '["at the instant after the projectile is launched","at the peak of the trajectory","at the instant before the projectile hits Earth","The acceleration is maximized at the points specified in both answer choices (A) and (C).","The acceleration is constant."]'::jsonb, '(D) The magnitude of the acceleration is proportional to the magnitude of the force. The magnitude of the force, in turn, is maximized when the projectile is closest to Earth, which occurs both when the particle is launched and when the particle hits the ground.'),
  ('ap-mock-physc-mech-full-1_q13', 'ap-mock-physc-mech-full-1', 13, false, 'C', 'Practice Test 1 – Mechanics', 'medium', 'Compare the gravitational potential energy when the particle is launched to the potential energy when the particle is at the peak of its trajectory.', '["Upeak = Ulaunch because of conservation of energy.","|Upeak| > |Ulaunch| and Upeak > 0","|Upeak| < |Ulaunch| and Upeak < 0","|Upeak| < |Ulaunch| and Upeak > 0","|Upeak| > |Ulaunch| and Upeak < 0"]'::jsonb, '(C) Gravitational potential energies are always negative because they are a sum: which eliminates choices (B) and (D). Conservation of energy requires that the potential energy be larger at the peak of the trajectory (where the kinetic energy is minimized), so choice (C) is correct.'),
  ('ap-mock-physc-mech-full-1_q14', 'ap-mock-physc-mech-full-1', 14, false, 'C', 'Practice Test 1 – Mechanics', 'medium', 'A wheel starts from rest and accelerates with constant angular acceleration alpha. If its angular speed after one complete revolution (2 pi radians) is omega_1, what will its angular speed be after four complete revolutions?', '["omega_1","sqrt(2) omega_1","2 omega_1","4 omega_1","16 omega_1"]'::jsonb, 'Rotational kinematics gives omega^2 = omega_0^2 + 2 alpha Delta theta. Starting from rest (omega_0 = 0), omega^2 = 2 alpha Delta theta ==> omega is proportional to sqrt(Delta theta). When the number of revolutions increases from 1 to 4, Delta theta quadruples, so the angular speed doubles: omega_4 = sqrt(4) omega_1 = 2 omega_1.'),
  ('ap-mock-physc-mech-full-1_q15', 'ap-mock-physc-mech-full-1', 15, false, 'D', 'Practice Test 1 – Mechanics', 'medium', 'A mass m is suspended in an elevator. In terms of the tension T of the string and the weight of the mass, what is the upward acceleration of the elevator?', '["T − mg","mg − T","(T/m) + g","(T/m) − g","g − T/m"]'::jsonb, '(D) There are two forces acting on the mass: tension pointing upward and gravity pointing downward. Therefore, Fnet = ma = T − mg (designating upward to be positive as indicated in the problem). Solving for the acceleration a yields choice (D). Note that the mass and the elevator have a common acceleration.'),
  ('ap-mock-physc-mech-full-1_q16', 'ap-mock-physc-mech-full-1', 16, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'A stationary mass M explodes into two fragments of masses m1 and m2 that fly apart in opposite directions. What is the ratio of their kinetic energies (K1 / K2)?', '["1","m2 / m1","m1 / m2","(m2 / m1)^2","sqrt(m2 / m1)"]'::jsonb, 'By conservation of momentum, since initial momentum is zero, p1 + p2 = 0 ==> |p1| = |p2| = p. Kinetic energy in terms of momentum is K = p^2 / (2m). Therefore, K1 / K2 = (p^2 / (2 m1)) / (p^2 / (2 m2)) = m2 / m1.'),
  ('ap-mock-physc-mech-full-1_q17', 'ap-mock-physc-mech-full-1', 17, false, 'E', 'Practice Test 1 – Mechanics', 'medium', 'A projectile is launched on level ground with an initial speed v0 and angle of elevation \theta. All of the following statements concerning the projectile right before it lands are correct except', '["The acceleration is equal to g downward.","The power exerted by the gravitational force is maximized.","The time the projectile was in the air is equal to 2v0sin \\theta/g.","The projectile has the same kinetic energy as when it was launched.","The projectile has the same velocity as when it was launched."]'::jsonb, '(E) Choice (A): The acceleration of a projectile is always g pointing downward. Choice (B): The power exerted by the gravitational force is maximized when the projectile’s velocity parallel to the gravitational force (its downward velocity) is maximized, which occurs immediately before the projectile lands (based on the formula P = F \cdot  v). Choice (C): The projectile’s initial y-component of velocity is v0sin \theta, and its final y-component of velocity (due to the symmetry of the parabolic trajectory) is −v0sin \theta. Applying the equation vf = v0 + at, with the acceleration of −g, shows that the total time in the air is equal to 2v0sin \theta/g. Choice (D): Conservation of energy requires that the projectile has the same kinetic energy when it lands as when it was launched. Choice (E): The projectile has the same speed as when it was launched, but it is moving in a different direction (tilted downward rather than upward).'),
  ('ap-mock-physc-mech-full-1_q18', 'ap-mock-physc-mech-full-1', 18, false, 'D', 'Practice Test 1 – Mechanics', 'medium', 'For a system in simple harmonic motion, which of the following statements is true? (The equilibrium point refers to the point in the middle of the particle’s oscillation, which could potentially be a static equilibrium point; the turning points are points where the particle reverses direction.)', '["The acceleration is maximized at the equilibrium point.","The velocity is maximized at the turning points.","The restoring force is maximized at the equilibrium point.","The displacement is maximized at the turning points.","None of the above are true; it depends on the particular situation."]'::jsonb, '(D) Choices (A) and (C): The restoring force and acceleration are maximized when the displacement is maximized, which occurs at the turning points. Choice (B): The velocity is maximized at the equilibrium point (where all the energy is kinetic energy). Choice (D): The particle reverses direction at the point where its displacement is maximized.'),
  ('ap-mock-physc-mech-full-1_q19', 'ap-mock-physc-mech-full-1', 19, false, 'D', 'Practice Test 1 – Mechanics', 'medium', 'An object slides with horizontal velocity v0 off a cliff of height h. How far from the base of the cliff does the object hit the ground?', '["v0g/h","v0h/2g","2gv0/h","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(D) Setting y = 0 at the top of the cliff and t = 0 as the instant the mass slides off the cliff, the y-coordinate of the particle’s position is given by the equation . Because the mass hits the ground when y = −h, the time of impact can be obtained by solving the equation . The x-component of the velocity is a constant v0, so the horizontal displacement during the fall is given by .'),
  ('ap-mock-physc-mech-full-1_q20', 'ap-mock-physc-mech-full-1', 20, false, 'C', 'Practice Test 1 – Mechanics', 'medium', 'The angular position of a wheel is given by the equation \theta(t) = 2t3 − 6t2, where \theta is measured in radians and t in seconds. When is the torque on the wheel equal to zero?', '["t = 0.33 s","t = 0.5 s","t = 1 s","t = 2 s","t = 3 s"]'::jsonb, '(C) The torque is zero when the angular acceleration is zero. To calculate the angular acceleration from the angular position, we must take two derivatives: Therefore, \alpha(t) = 0 when t = 1.'),
  ('ap-mock-physc-mech-full-1_q21', 'ap-mock-physc-mech-full-1', 21, false, 'D', 'Practice Test 1 – Mechanics', 'medium', 'A small mass attached to a string rotates on a frictionless tabletop as shown. If the tension in the string is increased, causing the radius of the circular motion to decrease by a factor of 2, what effect will this have on the kinetic energy of the mass?', '["It will decrease by a factor of 2.","It will remain constant.","It will increase by a factor of 2.","It will increase by a factor of 4.","It will increase by a factor of 8."]'::jsonb, '(D) The tension force exerts no torque because it is parallel to the radial position vector. Therefore, the net torque is zero and angular momentum is conserved. When the radius decreases by a factor of 2, the rotational inertia, I = mr2, decreases by a factor of 4. In order for the angular momentum, L = I\omega, to remain constant, the angular velocity must then increase by a factor of 4. Given these changes in the rotational inertia and the angular velocity, the kinetic energy, , increases by a factor of 4.'),
  ('ap-mock-physc-mech-full-1_q22', 'ap-mock-physc-mech-full-1', 22, false, 'B', 'Practice Test 1 – Mechanics', 'medium', '<p>Three point particles of equal mass m are situated in the xy-plane: particle 1 is at (0, 0), particle 2 is at (a, 0), and particle 3 is at (a, b). What is the x-coordinate of the center of mass of this three-particle system?</p>', '["a/3","2a/3","a/2","3a/4","a"]'::jsonb, '(B) Two masses are at x = a and one mass is at x = 0. Using the center of mass formula: x_{cm} = (m(0) + m(a) + m(a)) / (3m) = 2a/3, choice (B).'),
  ('ap-mock-physc-mech-full-1_q23', 'ap-mock-physc-mech-full-1', 23, false, 'A', 'Practice Test 1 – Mechanics', 'medium', 'When two springs are attached in parallel to a mass m as shown, what is the equivalent spring constant?', '["keq = k1 + k2","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","(E) none of the above","Zero net change under static equilibrium conditions"]'::jsonb, '(A) When the mass m is displaced by an amount \Delta x, the net force on it is the sum of the two spring forces: Fnet = −k1\Delta x − k2\Delta x. Setting this force equal to the force that would result from a single equivalent spring with spring constant keq yields Solving for the equivalent spring constant gives choice (A). Note: Two springs in parallel have an equivalent spring constant of keq = k1 + k2. Two springs in series have an equivalent spring constant of This is the same type of pattern seen with equivalent capacitances and resistances.'),
  ('ap-mock-physc-mech-full-1_q24', 'ap-mock-physc-mech-full-1', 24, false, 'E', 'Practice Test 1 – Mechanics', 'medium', 'A mass m is initially moving to the right with speed v toward a series of hills and valleys on a frictionless surface, as shown. What range of speeds must the mass have to become trapped in the valley between points A and B?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","It is impossible for the mass to become trapped."]'::jsonb, '(E) Because of conservation of energy, the mass’s speed is a function only of its height. Therefore, if the mass has enough energy to move over hill h1 when moving to the right, it will also have enough energy to move over the hill when moving to the left. Therefore, it is impossible for the mass to become trapped in the valley between points A and B without some other force being present (e.g., a frictional force).'),
  ('ap-mock-physc-mech-full-1_q25', 'ap-mock-physc-mech-full-1', 25, false, 'A', 'Practice Test 1 – Mechanics', 'medium', 'A constant net force F causes an object of mass m to accelerate from rest to a final speed v over a distance d. If the net force is doubled to 2F over the same distance d, what will the object''s final speed be?', '["sqrt(2) v","2 v","4 v","v / sqrt(2)","v"]'::jsonb, 'By the Work-Energy Theorem: W_net = F * d = Delta K = 1/2 m v^2. When force is doubled over the same distance d, work doubles: W_new = 2 F d = 2 W = 1/2 m (v_new)^2 ==> v_new = sqrt(2) v.'),
  ('ap-mock-physc-mech-full-1_q26', 'ap-mock-physc-mech-full-1', 26, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'Two concentric cylinders of radii R and 2R are fastened together and can rotate about their centers as in the figure. If two forces of magnitude F are exerted on the cylinders as shown, what must the magnitude of the third unknown force be if the cylinders are to rotate with constant angular speed?', '["F/2","(C) F","Equal in magnitude with opposite orientation","(E) 2F","Zero net change under static equilibrium conditions"]'::jsonb, '(B) In order for the cylinders to rotate with a constant speed, they must experience zero net torque. Holding to the convention that positive torque is counterclockwise, this mathematically yields Solving for the unknown force gives .'),
  ('ap-mock-physc-mech-full-1_q27', 'ap-mock-physc-mech-full-1', 27, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'A rod of uniform mass density and total mass M with a mass m attached to one end is pivoted as shown. What is the tension force FT needed to prevent the rod from moving?', '["FT = 2mg","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(B) Because the rod is fixed to a pivot (which can supply whatever force is necessary to make the net force zero), the only condition that must be satisfied for the rod to be in static equilibrium is that the net torque on the rod be zero. Calculating the torque about the pivot point (designating counterclockwise torques positive) yields (The center of the rod is located a distance 1/6 to the left of the pivot.) Solving for the tension force yields choice (B).'),
  ('ap-mock-physc-mech-full-1_q28', 'ap-mock-physc-mech-full-1', 28, false, 'E', 'Practice Test 1 – Mechanics', 'medium', 'A child riding in a car along a flat road tosses a ball straight up with a speed v. To an observer standing on the ground outside the car, the ball appears to be thrown with an angle of elevation of \theta. What is the speed of the car?', '["v sin \\theta","v cos \\theta","v sec \\theta","v tan \\theta","v cot \\theta"]'::jsonb, '(E) The velocity of the ball with respect to the ground is equal to the vector sum of the velocity of the ball with respect to the car plus the velocity of the car with respect to the ground, as shown. Based on the vector geometry of this triangle, tan \theta = v/speed of car so that the speed of the car = v/tan \theta = v cot \theta.'),
  ('ap-mock-physc-mech-full-1_q29', 'ap-mock-physc-mech-full-1', 29, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'A car of mass 400 kg is rounding a flat curve of radius 80 m. If the coefficient of static friction between the car’s tires and the ground is 0.5, the maximum speed at which the car can round the curve is closest to which of the following?', '["10 m/s","20 m/s","30 m/s","40 m/s","80 m/s"]'::jsonb, '(B) The frictional force provides as much centripetal force as is needed to keep the car moving in a circular path, up to the maximal static frictional force equal to Ffr = \mukFn = \mukmg. Therefore, at the maximum speed, mv2/r = \mukmg. Solving for v yields . Approximating g as 10 m/s2,'),
  ('ap-mock-physc-mech-full-1_q30', 'ap-mock-physc-mech-full-1', 30, false, 'C', 'Practice Test 1 – Mechanics', 'medium', 'An object of mass m starts from rest at t = 0 and moves along the x-axis under an acceleration a(t) = A t^2, where A is a constant. What is the object''s velocity v(t) as a function of time?', '["2 A t","A t^2","1/3 A t^3","1/2 A t^2","1/4 A t^4"]'::jsonb, 'Velocity is the integral of acceleration: v(t) = v(0) + int_0^t a(t'') dt'' = 0 + int_0^t A t''^2 dt'' = 1/3 A t^3.'),
  ('ap-mock-physc-mech-full-1_q31', 'ap-mock-physc-mech-full-1', 31, false, 'C', 'Practice Test 1 – Mechanics', 'medium', 'A mass m is thrown off the roof of a building of height h with an initial speed v0 and angle of elevation \theta below the horizontal. What is the object’s speed when it reaches the ground? (Do not ignore air friction.)', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(C) Ignoring air friction and applying conservation of energy yields . Solving for the final speed gives . Because the frictional force always performs negative work, it decreases the final speed so that the final velocity is less than this value.'),
  ('ap-mock-physc-mech-full-1_q32', 'ap-mock-physc-mech-full-1', 32, false, 'B', 'Practice Test 1 – Mechanics', 'medium', 'Three blocks of masses m, 2m, and 3m are connected in a line on a frictionless horizontal table by light strings. A horizontal pulling force F is applied to the front block 3m. What is the tension T in the string between block m and block 2m?', '["F / 3","F / 6","F / 2","2/3 F","F"]'::jsonb, 'Treating the three blocks as a combined system: F = (m + 2m + 3m) a = 6m a ==> a = F / (6m). The rear block of mass m is accelerated solely by the tension T in the rearmost string: T = m a = m (F / (6m)) = F / 6.'),
  ('ap-mock-physc-mech-full-1_q33', 'ap-mock-physc-mech-full-1', 33, false, 'D', 'Practice Test 1 – Mechanics', 'medium', 'A simple pendulum of length l has period T. A second pendulum of length l/2 is located at twice the distance from the center of Earth compared to the first pendulum. What is the period of the second pendulum?', '["T/2","(C) T","1","(E) 2T","4"]'::jsonb, '(D) The formula for the period of a pendulum is . Based on the law of universal gravitation (F = Gm1m2/r2), doubling the distance from the center of Earth causes the force (and thus the acceleration g) to decrease by a factor of 4. Because l decreases by a factor of 2 and g decreases by a factor of 4, the fraction l/g increases by a factor of 2, so the period increases by a factor of .'),
  ('ap-mock-physc-mech-full-1_q34', 'ap-mock-physc-mech-full-1', 34, false, 'A', 'Practice Test 1 – Mechanics', 'medium', 'A mass m is attached to a rod with uniform mass density at point C as shown. The rotational inertia of this system is greatest when it is rotated about an axis perpendicular to the rod that passes through', '["point A","point B","point C","a point between points A and B","a point between points B and C"]'::jsonb, '(A) The rotational inertia of the system is equal to the rotational inertia of the rod plus the rotational inertia of the mass. The rotational inertia of the mass, mR2, is maximized if the axis passes through point A (in order to maximize R, where R is the radius of the circular arc followed by m). The rotational inertia of the rod is given by the parallel axis theorem Irod = ICM + MD2 and is maximized when the distance of the axis from the center of mass is maximized, at both points A and C. Therefore, the rotational inertia of the system is maximized at point A, where the rotational inertia due to both the rod and the mass are maximized.'),
  ('ap-mock-physc-mech-full-1_q35', 'ap-mock-physc-mech-full-1', 35, false, 'D', 'Practice Test 1 – Mechanics', 'medium', 'A particle moves in the xy-plane. At time t1 its velocity is v1 = 3 i + 2 j, and at time t2 = t1 + 2 s its velocity is v2 = 3 i - 4 j. What is the average acceleration vector a_avg of the particle over this time interval?', '["3 i - j","6 i - 2 j","+3 j","-3 j","-6 j"]'::jsonb, 'Average acceleration is a_avg = (v2 - v1) / Delta t = [(3 i - 4 j) - (3 i + 2 j)] / 2 = (-6 j) / 2 = -3 j m/s^2.'),
  ('ap-mock-physc-mech-full-1_q36', 'ap-mock-physc-mech-full-1', 36, false, 'B', 'Ch2: Kinematics', 'medium', 'The position of an object is given by the equation x(t) = 2 + 4t − t2, where position is measured in meters and time in seconds. What is the particle’s average acceleration from t = 0 to t = 2?', '["−4 m/s2","−2 m/s2","0 m/s2","2 m/s2","4 m/s2"]'::jsonb, '(B) The formula for average acceleration is . We can obtain the velocity at t = 0 and t = 2 by differentiating the position equation to obtain v(t) = 4 − 2t. Therefore, v(t = 0) = 4 m/s and v(t = 2) = 0 m/s, such that the average velocity is Alternatively, we can differentiate the position function twice to find that a(t) = −2. Because the acceleration is constant, this value must equal the average acceleration between any two times.'),
  ('ap-mock-physc-mech-full-1_q37', 'ap-mock-physc-mech-full-1', 37, false, 'B', 'Ch2: Kinematics', 'medium', 'A ball is dropped from rest from height h above the ground. Neglecting air resistance, what is the speed of the ball when it has fallen a distance h/2?', '["sqrt(2 g h)","sqrt(g h)","1/2 sqrt(g h)","2 sqrt(g h)","Zero"]'::jsonb, 'Using kinematics v^2 = v0^2 + 2 g Delta y with v0 = 0 and Delta y = h/2: v^2 = 2 g (h/2) = g h ==> v = sqrt(g h).'),
  ('ap-mock-physc-mech-full-1_q38', 'ap-mock-physc-mech-full-1', 38, false, 'A', 'Ch2: Kinematics', 'medium', 'A 400 kg car accelerates from rest to a speed v over a distance d under a constant engine power P. If the distance is doubled to 2d under the same power, to what speed can the car accelerate?', '["2^{1/3} v","2^{1/2} v","2 v","4 v","v"]'::jsonb, 'For constant power P = F v = m v (dv/dt) = m v^2 (dv/dx), we have int P dx = int m v^2 dv ==> P d = 1/3 m v^3 ==> v is proportional to d^{1/3}. When d doubles, speed increases by a factor of 2^{1/3}.'),
  ('ap-mock-physc-mech-full-1_q39', 'ap-mock-physc-mech-full-1', 39, false, 'A', 'Ch2: Kinematics', 'medium', 'An object moves along the x-axis. At a certain instant, its velocity is negative (v_x < 0) and its acceleration is also negative (a_x < 0). Which of the following is true regarding the object''s speed?', '["The speed is increasing","The speed is decreasing","The speed is constant","The speed is zero","The direction of motion is reversing"]'::jsonb, 'When velocity and acceleration have the same sign (both negative or both positive), the acceleration acts in the same direction as the motion, causing the magnitude of velocity (the speed) to increase.'),
  ('ap-mock-physc-mech-full-1_q40', 'ap-mock-physc-mech-full-1', 40, false, 'E', 'Ch2: Kinematics', 'medium', 'Figure 2.15 compares the v(t) curves of two objects. The area under both curves from t = 0 to t = tf is the same. Which of the following quantities is the same from t = 0 to t = tf?', '["average position","average velocity","average acceleration","total displacement","both (B) and (D) are correct Figure 2.15"]'::jsonb, '[Note: explanation starts with (A), answer key says (E)] and (H), (B) and (E), (C) and (G), (D) and (F). In graph (A), the object starts with zero velocity and then moves to the right. The slope of the graph is constant (e.g., the object’s acceleration is uniform) so that x(t) is a parabola with zero slope at t = 0 [graph (H)]. In graph (B), the object moves first with decreasing speed to the right and then switches direction (where the curve crosses the axis) and moves to the left. This motion corresponds to what is shown in graph (E) (a parabola whose slope is initially positive at t = 0 and then becomes negative). Graph (C) looks similar to graph (A), with the exception that the initial velocity is nonzero. Thus, it corresponds to graph (G), where the parabola has a positive slope at t = 0. Finally, in graph (D), the velocity is constant so that the x(t) graph is a straight line [graph (F)]. 4. The projectiles’ trajectories are shown in Figure 2.21. Figure 2.21 (a) The amount of time it takes for a projectile to fall to the height at which it was launched depends only on its y-component of velocity vy: A projectile with a larger initial value of vy will require longer to fall to its original height. Because it takes projectile 2 three fewer seconds to fall to its original height (i.e., to go from point A to point B), it must have a smaller initial vy. (b) Because projectile 2 has a smaller initial vy, it has a smaller maximum height and spends less time in the air. (c) Because of the symmetry of parabolas, the x-component of the position of the peak of the trajectories of both projectiles occurs at exactly xh/2 (Figure 2.21). (d) Because projectile 2 can cover the same x-displacement as projectile 1 (the distance between points A and B) in three fewer seconds, projectile 2 has a greater vx. (e) Because projectile 2 has a smaller initial vy and a greater initial vx, it has a smaller angle of elevation at any time during its flight. (If in doubt, a quick sketch should confirm this.) (f) Because point B is at the same height as point A, vy for each of the particles is the negative of their initial values (because of the symmetry of parabolas). Therefore, for projectile 1, vy still has a greater magnitude. The values of vx remain unchanged such that projectile 2 still has the greater x- component of velocity. (g) At point B, projectile 1 is falling with a greater magnitude vy, so after passing point B, it spends less time in the air than projectile 2. Because projectile 1 spends less time in the air and has a smaller value of vx, it has a smaller range. 5. (a) Referring to Figure 2.7, we have B = ground, A = walkway, and P = woman, and the equation vP relative to B = vP relative to A + vA relative to B yields the speed of the woman relative to the ground: vP relative to B = 1.5 m/s + 1.25 m/s = 2.75 m/s Thus, it wll take her 40 m/(2.75 m/s) = 14.5 s. (b) Now her speed relative to the ground is vP relative to B = −1.5 m/s + 1.25 m/s = −0.25 m/s. She is moving the wrong way and cannot reach the other end unless she slows down! (c) It will take this person 40 m/(1.5 m/s) = 26.7 s. (d) They would need to move at 40 m/14.5s = 2.75 m/s, which is about 6 mi/h, i.e., about a 10-minute mile, which is not very fast.'),
  ('ap-mock-physc-mech-full-1_q41', 'ap-mock-physc-mech-full-1', 41, false, 'C', 'Ch2: Kinematics', 'medium', 'An object moves with uniform positive acceleration along the x-axis. Which of the following graphs correctly represents its position x(t) as a function of time?', '["A straight horizontal line","A straight line with positive slope","A parabola opening upward","A parabola opening downward","A sinusoidal curve"]'::jsonb, 'For constant positive acceleration a > 0, the position function is x(t) = x0 + v0 t + 1/2 a t^2. The term 1/2 a t^2 is quadratic in t with a positive leading coefficient, representing a parabola opening upward.'),
  ('ap-mock-physc-mech-full-1_q42', 'ap-mock-physc-mech-full-1', 42, false, 'B', 'Ch2: Kinematics', 'medium', 'The velocity of a particle moving in one dimension is given by the equation v(t) = 4 + 3t2, where velocity is in m/s and time is in seconds. What is the average value of the velocity in the interval t = 0 to t = 2?', '["4 m/s","8 m/s","12 m/s","16 m/s","20 m/s"]'::jsonb, '(B) From calculus, the average value of a function is given by the formula Using this formula here yields (In the language of kinematics, this is equivalent to integrating v(t) to get the displacement, \Delta x, and dividing the displacement by the time increment to obtain the average velocity.)'),
  ('ap-mock-physc-mech-full-1_q43', 'ap-mock-physc-mech-full-1', 43, false, 'B', 'Ch2: Kinematics', 'medium', 'Projectile 1 is launched off a cliff with an initial speed of 100 m/s and an angle of elevation of 45°. Three seconds later, a second projectile is launched off the same cliff. The instant that the first projectile has the same height as the cliff (on its way down), the second projectile passes infinitesimally close to the first projectile without touching it (you can assume that the two trajectories intersect at a particular time, but do not worry about a physical collision between the two objects). Sketch the paths of the two projectiles, and answer the following questions qualitatively. (You can choose to answer some of the following questions before finishing the sketch.) (a) Compare the initial y-components of the velocities of the two projectiles when they are launched. (b) Compare the maximum heights of the two projectiles and the total time spent by each projectile in the air. (c) Compare the x-components of the positions of the peaks of the trajectories of the two projectiles. (d) Compare the x-components of the velocities of the two projectiles. (e) Compare the angles of elevation (at any particular time) of the velocity vectors of the two projectiles. (f) Compare the x- and y-components of the velocities of the two projectiles as they pass each other. (g) Which projectile has the longer range?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(B) From calculus, the average value of a function is given by the formula Using this formula here yields (In the language of kinematics, this is equivalent to integrating v(t) to get the displacement, \Delta x, and dividing the displacement by the time increment to obtain the average velocity.)'),
  ('ap-mock-physc-mech-full-1_q44', 'ap-mock-physc-mech-full-1', 44, false, 'A', 'Ch2: Kinematics', 'medium', 'An object of mass m falls from rest under gravity and a linear air resistance force F_drag = -b v. What is the terminal speed v_term of the object?', '["m g / b","b / (m g)","sqrt(m g / b)","m g b","Zero"]'::jsonb, 'Newton''s second law gives m (dv/dt) = m g - b v. At terminal speed, acceleration is zero: m g - b v_term = 0 ==> v_term = m g / b.'),
  ('ap-mock-physc-mech-full-1_q45', 'ap-mock-physc-mech-full-1', 45, false, 'A', 'Ch2: Kinematics', 'medium', 'A moving walkway in an airport terminal is 40 m long and moves at 1.25 m/s. A passenger steps onto the walkway and walks forward relative to the walkway at 1.25 m/s. How long does it take the passenger to reach the other end?', '["16 s","32 s","20 s","8 s","25 s"]'::jsonb, 'The passenger''s velocity relative to the ground is v_ground = v_walkway + v_walk = 1.25 m/s + 1.25 m/s = 2.50 m/s. The time required to travel the 40 m distance is t = d / v_ground = 40 m / (2.50 m/s) = 16 s.'),
  ('ap-mock-physc-mech-full-2_q1', 'ap-mock-physc-mech-full-2', 1, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A variable force exerted during time interval \Delta t changes the velocity of mass m from v0 to vf. What is the average power exerted during this time interval?', '["(vf − v0)/\\Delta t","mvf − mv0","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(D) Average power is given by the equation . What is the work done? Because there are no other forces acting on the block, (according to the work-energy theorem). Dividing by the time increment to calculate the average power yields choice (D). Note that the correct answer can be obtained using only dimensional analysis.'),
  ('ap-mock-physc-mech-full-2_q2', 'ap-mock-physc-mech-full-2', 2, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A point charge −q is released from rest at the center of a parallel plate capacitor, as shown. Note that the plates have small holes that allow the charge to exit the capacitor. Which of the following statements describes the charge’s behavior a long time after it exits the capacitor?', '["It is moving to the right with a kinetic energy of KE = qV.","It is moving to the left with a kinetic energy of KE = qV.","It is moving to the right with a kinetic energy of KE = qV/2.","It is moving to the left with a kinetic energy of KE = qV/2.","It never reaches a constant velocity but instead continually oscillates in and out of the capacitor."]'::jsonb, '(D) Average power is given by the equation . What is the work done? Because there are no other forces acting on the block, (according to the work-energy theorem). Dividing by the time increment to calculate the average power yields choice (D). Note that the correct answer can be obtained using only dimensional analysis.'),
  ('ap-mock-physc-mech-full-2_q3', 'ap-mock-physc-mech-full-2', 3, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'A particle moves with constant speed v counterclockwise around a circle of radius r in the xy-plane. Which of the following correctly describes the x-component of the velocity?', '["It is constant and equal to v.","It is constant but not equal to v.","It varies between zero and v.","It varies between zero and .","It varies between −v and v."]'::jsonb, '(E) Consider the figure. At points A and C, the x-component of velocity is zero, at point B it is equal to −v, and at point D it is equal to +v. This range of values is consistent only with choice (E).'),
  ('ap-mock-physc-mech-full-2_q4', 'ap-mock-physc-mech-full-2', 4, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'Describe the potential V as a function of r inside a spherical shell with uniform surface charge density.', '["V = 0.","V is constant.","V has a constant slope.","V is proportional to 1/r.","V is proportional to 1/r2."]'::jsonb, '(E) Consider the figure. At points A and C, the x-component of velocity is zero, at point B it is equal to −v, and at point D it is equal to +v. This range of values is consistent only with choice (E).'),
  ('ap-mock-physc-mech-full-2_q5', 'ap-mock-physc-mech-full-2', 5, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'A baseball is falling toward Earth. If ab is the acceleration of the baseball due to the gravitational pull of Earth and ae is the acceleration of Earth due to the baseball, which of the following is true?', '["ae = 0","ab = ae","ab >> ae, and the accelerations are parallel.","ae >> ab, and the accelerations are parallel.","ab >> ae, and the accelerations are antiparallel."]'::jsonb, '(E) According to Newton’s third law, the baseball and Earth exert equal and opposite forces on each other. Therefore, the accelerations they experience must be in opposite directions. Because F = meae = mbab, the larger object (Earth) experiences a smaller acceleration (which is imperceptible).'),
  ('ap-mock-physc-mech-full-2_q6', 'ap-mock-physc-mech-full-2', 6, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'While discharging a capacitor through a resistor, how many of the following functions are exponentially decreasing? I. the current through the circuit II. the energy stored in the capacitor III. the voltage across the resistor IV. the power dissipated in the resistor V. the electric field within the capacitor VI. the charge on the capacitor', '["two","three","four","five","six"]'::jsonb, '(E) According to Newton’s third law, the baseball and Earth exert equal and opposite forces on each other. Therefore, the accelerations they experience must be in opposite directions. Because F = meae = mbab, the larger object (Earth) experiences a smaller acceleration (which is imperceptible).'),
  ('ap-mock-physc-mech-full-2_q7', 'ap-mock-physc-mech-full-2', 7, false, 'A', 'Practice Test 2 – Mechanics', 'medium', 'If the angular position of a disk is given by the equation \theta(t) = 2 + 4t − 3t2, what is the angular velocity of the disk as a function of time?', '["4 − 6t","6t − 4","2t + 2t2 − 3t3","3t3 − 2t2 − 2t","3t3 − 2t2 − 2t + C"]'::jsonb, '(A) The angular velocity is simply the derivative of the angular position:'),
  ('ap-mock-physc-mech-full-2_q8', 'ap-mock-physc-mech-full-2', 8, false, 'A', 'Practice Test 2 – Mechanics', 'medium', 'The figure shows two coaxial cylinders that have charge distributed uniformly on their surfaces, with a linear charge density of −\lambda and +\lambda', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(A) The angular velocity is simply the derivative of the angular position:'),
  ('ap-mock-physc-mech-full-2_q9', 'ap-mock-physc-mech-full-2', 9, false, 'A', 'Practice Test 2 – Mechanics', 'medium', 'When an object moving in the circular track as shown has a velocity in the +y-direction, its acceleration has components in the +x- and +y- directions. Which of the following statements is true?', '["The object is moving clockwise with increasing speed.","The object is moving counterclockwise with increasing speed.","The object is moving clockwise with decreasing speed.","The object is moving counterclockwise with decreasing speed.","The object is moving clockwise with constant speed."]'::jsonb, '(A) Because the object has a tangential acceleration parallel to its velocity, its speed is increasing. Because the centripetal acceleration (perpendicular to the velocity) always points toward the center of the circle, the object must move clockwise so that the centripetal acceleration points in the +x-direction while the object is instantaneously moving in the +y-direction.'),
  ('ap-mock-physc-mech-full-2_q10', 'ap-mock-physc-mech-full-2', 10, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'A force F exerted on a block parallel to an inclined slope as shown causes the block’s speed to increase from zero to v as it moves a distance d along the incline. If the coefficient of friction is \muK, how much work does gravity do during this time interval?', '["\\muKmg(cos \\theta)d","\\muKmg(cos \\theta)d + mg(sin \\theta)d","(D) mgd sin \\theta","2E_0","−mgd sin \\theta"]'::jsonb, '(E) The gravitational force is constant, so the work it does is given by the equation . The y-coordinate increases by an amount d sin \theta, so the work done by gravity is given by choice (E). (Check: The work done by gravity must come out negative because the force of gravity is antiparallel to the vertical displacement of the object.)'),
  ('ap-mock-physc-mech-full-2_q11', 'ap-mock-physc-mech-full-2', 11, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A point mass is released from rest as shown. If the inclined planes are frictionless, which of the following statements is correct?', '["The mass is undergoing simple harmonic motion with a period of T = (2d/g sin \\theta)1/2.","The mass is undergoing simple harmonic motion with a period of T = 2(2d/g sin \\theta)1/2.","The mass is undergoing simple harmonic motion with a period of T = 4(2d/g sin \\theta)1/2.","As the mass slides down the slope, the component of the momentum perpendicular to the slope is constant.","The mass is in static equilibrium."]'::jsonb, '(D) Choices (A)−(C): The mass is not undergoing SHM because the restoring force is not proportional to the displacement (instead, it is constant and equal to mg sin \theta). Choice (E): The mass would be in static equilibrium if placed at the bottom of the incline with zero initial velocity, but in the present case the object oscillates back and forth along the inclines. Choice (D): The component of the momentum perpendicular to the slope is zero as the mass initially slides down the slope, and it remains zero. (There is zero net force in this direction because the normal force cancels the component of the gravitational force perpendicular to the incline.)'),
  ('ap-mock-physc-mech-full-2_q12', 'ap-mock-physc-mech-full-2', 12, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'An object of mass m has its position given by the equation x(t) = at4 − bt3 + c. What is the force on the object as a function of time?', '["F(t) = (4at3 − 3bt2)","F(t) = (4at3 − 3bt2)m","F(t) = (12at2 − 6bt)","F(t) = (12at2 − 6bt)m","F(t) = −(12at2 − 6bt)m"]'::jsonb, '(D) Differentiating twice to calculate the acceleration from the position yields a(t) = (12at2 − 6bt). Applying Newton’s second law then gives F = ma = ma(t) = m(12at2 − 6bt).'),
  ('ap-mock-physc-mech-full-2_q13', 'ap-mock-physc-mech-full-2', 13, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'A mass is suspended by two ropes as shown. What is the ratio of the tension forces in the two ropes?', '["T1/T2 = sin \\theta1/sin \\theta2","T1/T2 = sin \\theta2/sin \\theta1","T1/T2 = cos \\theta1/cos \\theta2","T1/T2 = cos \\theta2/cos \\theta1","T1/T2 = tan \\theta1/tan \\theta2"]'::jsonb, '(B) For the object to be in static equilibrium, the net force in the x- direction must be zero: Fnet,x = 0 = T1 sin \theta1 − T2 sin \theta2. Rearranging this equation yields choice (B).'),
  ('ap-mock-physc-mech-full-2_q14', 'ap-mock-physc-mech-full-2', 14, false, 'C', 'Practice Test 2 – Mechanics', 'medium', 'Two projectiles are thrown at a vertical wall with initial velocities and positions as shown. Which of the following comparisons is correct regarding the height of the impact and the time the projectile spends in the air before it hits the wall? Height of impact Time in the air', '["h1 > h2 t1 < t2","h1 = h2 t1 < t2","h1 > h2 t1 = t2","h1 < h2 t1 = t2","The answer cannot be determined because it depends on whether the projectiles hit the wall before or after reaching the peaks of their trajectories."]'::jsonb, '(C) The projectiles hit the wall when their x-positions are equal to the position of the wall. Because both projectiles have the same x- components of velocity, they require the same amount of time to hit the wall. Because projectile 1 has a greater y-component of velocity, v1(t) > v2(t), it hits the surface at a greater height (noting that both projectiles hit the surface after the same amount of time t).'),
  ('ap-mock-physc-mech-full-2_q15', 'ap-mock-physc-mech-full-2', 15, false, 'C', 'Practice Test 2 – Mechanics', 'medium', 'A ball is launched horizontally off a cliff and moves through the air subject to both downward gravity and air resistance directed opposite to its velocity. At the instant the ball reaches the peak of a trajectory or moves along a curved path with horizontal velocity to the right, which of the following describes the direction of the net force on the ball?', '["Directly upward","Directly downward","Downward and to the left (opposing velocity and directed toward Earth)","Downward and to the right","Directly to the left"]'::jsonb, 'Gravity exerts a downward force F_g = -m g j. Air resistance opposes the instantaneous motion: if the ball is moving to the right, air resistance exerts a force to the left, F_drag = -F_d i. The net force is F_net = F_g + F_drag, which has components pointing downward and to the left.')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-mock-physc-mech-full-2_q16', 'ap-mock-physc-mech-full-2', 16, false, 'A', 'Practice Test 2 – Mechanics', 'medium', 'Referring to the situation described in question 11, at what point is the magnitude of the net force maximized?', '["point A","point B","point C","point D","point E"]'::jsonb, '(A) The frictional force of air resistance is proportional to the object’s velocity and opposite in direction. Thus, the x-component of the frictional force (which in the x-direction equals the net force) is maximized when the x-component of the velocity is the greatest. This occurs at point A, before friction has begun to decrease the magnitude of the x-component of velocity. The y-component of the net force is equal to the force exerted by gravity plus the y-component of the frictional force. The magnitude of this sum is greatest when the two forces point in the same direction, which occurs for points to the left of point C (when the velocity has an upward component, causing a downward component in frictional force). The downward vertical component of the frictional force is greatest at point A (before the y-component of velocity has begun to decrease), so at point A the y-component of the net force is maximized. Because both components of the net force are maximized at point A, the magnitude of the net force is also maximized at point A.'),
  ('ap-mock-physc-mech-full-2_q17', 'ap-mock-physc-mech-full-2', 17, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'On a certain planet, a ball is thrown upward with a kinetic energy of 100 J and an angle of elevation of 45°. If the ball has a kinetic energy of 75 J at a height of 10 m, what is the maximum height of its trajectory?', '["10 m","20 m","40 m","60 m","80 m"]'::jsonb, '(B) Consider the equation for conservation of energy between the instant the ball is launched and the instant it reaches its maximum height (at the maximum height, the y-velocity will be zero and the x- velocity will be equal to the original x-velocity, in this case . Therefore, at the peak of the object’s trajectory, half of its total energy (i.e., 50 J) will appear as potential energy. We also know that 25 J is stored as potential energy at a height of 10 m. Because potential energy is proportional to height, the potential energy will equal 50 J, its value at the peak of the trajectory, at a height of 20 m.'),
  ('ap-mock-physc-mech-full-2_q18', 'ap-mock-physc-mech-full-2', 18, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A particle moves with speed v around a circle of radius r. What is the period of the particle’s motion?', '["f / 2","f / \\sqrt{2}","T = 2\\pi(v/r)","T = 2\\pi(r/v)","T = r/2\\piv"]'::jsonb, '(D) The only answers that have correct units are (D) and (E). The period is the amount of time it takes for the particle to make one complete cycle, in this case one complete revolution around the circle. The total distance of a cycle is the circumference of the circle, 2\pir, and the speed is v, so the time required for one cycle is t = distance/rate = 2\pir/v.'),
  ('ap-mock-physc-mech-full-2_q19', 'ap-mock-physc-mech-full-2', 19, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'Assuming Earth is a sphere of uniform mass density and radius R_E, at what radial distance(s) r from Earth''s center is the acceleration due to gravity equal to g/2 (where g is the surface gravitational acceleration)?', '["r = sqrt(2) R_E only","r = 2 R_E only","r = R_E / 2 only","r = R_E / 4 only","At both r = R_E / 2 (inside Earth) and r = sqrt(2) R_E (outside Earth)"]'::jsonb, 'Inside Earth (r < R_E), only the enclosed mass contributes to gravity: g(r) = g * (r / R_E). Setting g(r) = g/2 yields r = R_E / 2. Outside Earth (r > R_E), g(r) = g * (R_E / r)^2. Setting g(r) = g/2 yields (R_E / r)^2 = 1/2 ==> r = sqrt(2) R_E. Thus, the acceleration equals g/2 at two locations: r = R_E / 2 and r = sqrt(2) R_E.'),
  ('ap-mock-physc-mech-full-2_q20', 'ap-mock-physc-mech-full-2', 20, false, 'E', 'Practice Test 2 – Mechanics', 'medium', 'Two forces act on a circular mass as shown. A third force is exerted at point P. For this force to ensure static equilibrium,', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","It is impossible for a force exerted at point P to cause static equilibrium."]'::jsonb, '(E) For the net force to be zero, the force at point P must be (pointing downward and to the right). However, this produces a net counterclockwise torque about the center of the object (note that the two forces in the figure exert zero torque about this point). Therefore, it is impossible for a force exerted at point B to produce static equilibrium.'),
  ('ap-mock-physc-mech-full-2_q21', 'ap-mock-physc-mech-full-2', 21, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A railroad car is traveling to the right at a speed of 10 m/s relative to the ground. What is the velocity of an automobile relative to the railroad car if the velocity of the automobile relative to the ground is 2 m/s to the left?', '["8 m/s to the right","8 m/s to the left","12 m/s to the right","12 m/s to the left","2 m/s to the left"]'::jsonb, '(D) The velocity of the automobile relative to the ground obeys the formula'),
  ('ap-mock-physc-mech-full-2_q22', 'ap-mock-physc-mech-full-2', 22, false, 'C', 'Practice Test 2 – Mechanics', 'medium', 'A block of mass 0.2 kg on a horizontal frictionless surface is attached to a spring of spring constant 200 N/m. The block is pulled 0.8 m from its equilibrium position and released from rest. It then executes simple harmonic motion. What is the maximum elastic potential energy of the system?', '["3 J","6.4 J","64 J","8,000 J","200,000 J"]'::jsonb, '(C) The elastic potential energy is given by .'),
  ('ap-mock-physc-mech-full-2_q23', 'ap-mock-physc-mech-full-2', 23, false, 'A', 'Practice Test 2 – Mechanics', 'medium', 'A small ball of mass m attached to a light string of length r swings in a vertical circle. What is the minimum speed the ball must have at the top of the circle so that the string remains taut (tension T >= 0)?', '["sqrt(g r)","sqrt(2 g r)","sqrt(5 g r)","2 sqrt(g r)","1/2 sqrt(g r)"]'::jsonb, 'At the top of the vertical circle, both gravity and tension point downward toward the center: T + m g = m v^2 / r. For the string to remain taut, tension must be non-negative (T >= 0). The critical threshold occurs when T = 0, giving m g = m v^2 / r ==> v = sqrt(g r).'),
  ('ap-mock-physc-mech-full-2_q24', 'ap-mock-physc-mech-full-2', 24, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'Consider a spring with a restoring force given by F(x) = −bx3 + cx5. If the potential energy is chosen to be zero at the equilibrium position, which of the following functions gives the elastic potential energy as a function of the spring’s displacement?', '["U(x) = 5cx4 − 3bx2","U(x) = 3bx2 − 5cx4","U(x) = (cx6/6) − (bx4/4)","U(x) = (bx4/4) − (cx6/6)","none of the above"]'::jsonb, '(D) Fx = −dU/dx, so'),
  ('ap-mock-physc-mech-full-2_q25', 'ap-mock-physc-mech-full-2', 25, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'If the block shown moves with constant speed v, what form do the horizontal and vertical components of Newton’s second law, respectively, take?', '["F sin \\theta = \\muKmg for both components","F cos \\theta = \\muKFN and FN + F sin \\theta = mg","F sin \\theta = \\muKFN and FN + F cos \\theta = mg","F cos \\theta = \\muKFN and FN = mg + F sin \\theta","F sin \\theta = \\muKFN and FN = mg + F cos \\theta"]'::jsonb, '(B) The free-body diagram is shown below.'),
  ('ap-mock-physc-mech-full-2_q26', 'ap-mock-physc-mech-full-2', 26, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'What is the power exerted by the force F in question 21?', '["P = F(sin \\theta)v","P = F(cos \\theta)v","P = −F(sin \\theta)v","P = −F(cos \\theta)v","P = \\muKmgv Questions 23–25 refer to the same situation."]'::jsonb, '(B) P = F ⋅ v = Fǁv = F(cos \theta)v. In words, the power is given by the component of the force parallel to the velocity, +F cos \theta multiplied by the magnitude of the velocity v.'),
  ('ap-mock-physc-mech-full-2_q27', 'ap-mock-physc-mech-full-2', 27, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'A horizontal bug of mass m stands at rest on the edge of a horizontal disk of mass M, radius r, and rotational inertia , which is also at rest. At a certain time, the bug starts walking counterclockwise around the rim (when viewed from above) so that it moves with a speed v with respect to the ground. If the disk is free to rotate about its center, what is the resulting angular velocity of the disk (with respect to the ground)?', '["\\omega = mv/Mr","\\omega = 2mv/Mr","\\omega = Mv/2mr","\\omega = Mv/mr","none of the above"]'::jsonb, '(B) Angular momentum is conserved about the axle of the disk (assuming there is no friction in the axle). Because the initial angular momentum about this point is zero, the final angular momentum must also be zero. This requires that the disk rotate in the direction opposite the bug (clockwise) with an angular momentum of equal magnitude: Solving for the magnitude of the angular velocity gives choice (B).'),
  ('ap-mock-physc-mech-full-2_q28', 'ap-mock-physc-mech-full-2', 28, false, 'C', 'Practice Test 2 – Mechanics', 'medium', 'In terms of the speed of the bug, v (with respect to the ground), and the magnitude of the angular velocity of the disk, \omega, what is the speed of the bug relative to the disk?', '["(v/r) + \\omega","(v/r) − \\omega","v + r\\omega","v − r\\omega","Zero net change under static equilibrium conditions"]'::jsonb, '(C) Consider, for example, when the bug crosses the +x-axis (setting the origin of the coordinate system at the axle of the disk). The velocity of the bug with respect to the ground is because the bug is moving with speed v counterclockwise. The speed of the point on the disk where the bug stands is (relative to the ground) because the disk is rotating clockwise with angular velocity \omega. The relative velocity of the bug with respect to the disk is given by Although we solved this problem for a particular point in the bug’s motion, because of the rotational symmetry of the disk, the speeds always sum in this manner.'),
  ('ap-mock-physc-mech-full-2_q29', 'ap-mock-physc-mech-full-2', 29, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'What is the minimum coefficient of static friction between the bug’s feet and the disk required to keep the bug from sliding off the disk as it walks with constant speed v?', '["mv2/r","v2/rg","(v + \\omegar)2/rg","(v − \\omegar)2/rg","No static friction is needed."]'::jsonb, '(B) The frictional force must provide the centripetal force required to keep the bug moving in circular motion. Recall that Newton’s laws hold only in inertial reference frames, in this case the ground frame. Therefore, we must apply the equation Fcent = mv2/r in the ground frame (note that v is the bug’s speed in this frame of reference). Setting the centripetal force equal to the frictional force gives mv2/r = \musmg. Solving for the coefficient of friction yields choice (B). Note: Why is this static rather than kinetic friction? Although the bug is moving, its feet are not moving with respect to the disk (i.e., the bug’s feet are not slipping as it walks).'),
  ('ap-mock-physc-mech-full-2_q30', 'ap-mock-physc-mech-full-2', 30, false, 'C', 'Practice Test 2 – Mechanics', 'medium', 'Two masses m1 and m2 move along a straight line in opposite directions with speeds v1 and v2, respectively. What is the speed of the center of mass of the two-body system?', '["(m1 v1 + m2 v2) / (m1 + m2)","(v1 + v2) / 2","|m1 v1 - m2 v2| / (m1 + m2)","|m1 - m2|(v1 + v2) / (m1 + m2)","sqrt(v1^2 + v2^2)"]'::jsonb, 'Taking the direction of m1 as positive, the velocities are +v1 and -v2. The velocity of the center of mass is v_cm = (m1 v1 - m2 v2) / (m1 + m2). The speed of the center of mass is the absolute value of this velocity: |v_cm| = |m1 v1 - m2 v2| / (m1 + m2).'),
  ('ap-mock-physc-mech-full-2_q31', 'ap-mock-physc-mech-full-2', 31, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A force F pushes on two masses lying on a horizontal frictionless surface as shown, causing them to accelerate to the right with magnitude a. Which of the following statements is false?', '["m2 exerts a force of on m1.","The net force on m1 is F − m2a.","The acceleration of the blocks is a = F/(m1 + m2).","The sum of the contact forces exerted by m1 on m2, and vice versa, produce net work on the two-block system.","The net force on m2 is m2a."]'::jsonb, '(D) Choice (D): The force that m1 exerts on m2 is an internal force, so it is balanced by another internal force so that together these internal forces make no contribution to the net force or the net work on the two- block system. (If we were considering the blocks separately, this force would no longer be an internal force.) See Example 3.6 on page 108 for further explanation.'),
  ('ap-mock-physc-mech-full-2_q32', 'ap-mock-physc-mech-full-2', 32, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A particle is released from rest at point A. The figure shows the potential energy of the particle as a function of position. If no nonconservative forces are present, which of the following statements is true?', '["The particle oscillates between points B and F.","The particle cannot reach point G.","The particle moves in simple harmonic motion.","The particle experiences no force at points C, D, and E.","The particle’s speed is maximized at point E."]'::jsonb, '(D) The particle oscillates between points A and H (the particle has a total energy of 1 J, so it cannot move beyond these points because that would require having negative kinetic energy). Since point G is within the boundaries of this oscillation, it will indeed reach and pass point G. Because there is no simple linear restoring force [which would be equivalent to an upward-parabolic U(x) curve], the particle does not move in simple harmonic motion. The force, equal to F(x) = −dU/dx, is zero at points C, D, and E because the slope of the function U(x) is zero at these points. The particle’s speed is maximized at point C (not point E), as this is the place where the particle’s potential energy is the lowest (and thus, its kinetic energy is the highest).'),
  ('ap-mock-physc-mech-full-2_q33', 'ap-mock-physc-mech-full-2', 33, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'If a rotating object accelerates from rest with an angular acceleration of 2 rad/s2, through what angle will it rotate before a point on its edge a distance 0.5 m from the axle is moving with a speed of 2 m/s?', '["0.5 rad","1 rad","2 rad","4 rad","8 rad"]'::jsonb, '(D) The final angular velocity is \omega = v/r. Using the equation yields Substituting in for all the values given in the problem results in choice (D).'),
  ('ap-mock-physc-mech-full-2_q34', 'ap-mock-physc-mech-full-2', 34, false, 'A', 'Practice Test 2 – Mechanics', 'medium', 'Consider the five figures, which show different forces as functions of position. How many of these forces can give rise to simple harmonic motion about the point x = 0?', '["Directly proportional to the parameter (linear scaling)","one","Equal in magnitude with opposite orientation","three","Zero net change under static equilibrium conditions"]'::jsonb, '(A) SHM requires a linear restoring force, which is graphically equivalent to the F (x) curve passing through the x-axis with a negative slope (the x-intercept is the equilibrium of the SHM).'),
  ('ap-mock-physc-mech-full-2_q35', 'ap-mock-physc-mech-full-2', 35, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'A particle is subject to a conservative force associated with potential energy function U(x) = alpha x^4 - beta x^2, where alpha and beta are positive constants. At which of the following non-zero positions is the particle in equilibrium (net force F = 0)?', '["x = +/- sqrt(beta / (4 alpha))","x = +/- sqrt(beta / (2 alpha))","x = +/- beta / alpha","x = +/- sqrt(2 beta / alpha)","x = +/- beta / (2 alpha)"]'::jsonb, 'Conservative force is related to potential energy by F(x) = -dU/dx. Differentiating U(x): dU/dx = 4 alpha x^3 - 2 beta x. Setting F(x) = 0 gives 2 x (2 alpha x^2 - beta) = 0. For non-zero equilibrium positions: 2 alpha x^2 = beta ==> x^2 = beta / (2 alpha) ==> x = +/- sqrt(beta / (2 alpha)).'),
  ('ap-mock-physc-mech-full-2_q36', 'ap-mock-physc-mech-full-2', 36, false, 'B', 'Practice Test 2 – Mechanics', 'medium', 'A block of mass 0.6 kg slides on a horizontal table where the coefficient of kinetic friction is 0.1. If the block is moved 3 m to the left and then 3 m back to its original position, how much work is done by the frictional force?', '["−100.76 J","−3.53 J","0 J","3.53 J","100.76 J"]'::jsonb, '(B) The magnitude of the frictional force is given by Ffr = \mukFN = \mukmg = 0.59 N. The work done by friction is W = −Ffrd, where d is the total displacement, i.e., 6 m. Thus, W = −(0.59)(6) = −3.53 J.'),
  ('ap-mock-physc-mech-full-2_q37', 'ap-mock-physc-mech-full-2', 37, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'A ball with radius r = 2 m is rolling without slipping along a horizontal surface. If \theta, the angle through which the ball rotates, is given as a function of time by \theta = 4t2, then at time t = 1, what is the linear acceleration of the center of mass of the ball?', '["9,600 m/s2","140 m/s2","40 m/s2","16 m/s2","0.88 m/s2"]'::jsonb, '(D) The angular displacement is proportional to t2; thus, the angular acceleration \alpha is constant and given by the second time derivative of \theta, i.e., \alpha = 8. Rolling without slipping implies that the acceleration a of the center of mass obeys a = r\alpha = (2)(8) = 16 m/s2.'),
  ('ap-mock-physc-mech-full-2_q38', 'ap-mock-physc-mech-full-2', 38, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'Referring to the ball introduced in question 33, what is the speed of a point on the very top of the ball at time t = 1 relative to the horizontal surface?', '["6 m/s","12 m/s","24 m/s","32 m/s","96 m/s"]'::jsonb, '(D) Differentiating once to calculate the angular velocity from the angular position gives \omega = 8t. The speed at the top of the ball is given by the equation v = 2r\omega (for further explanation, see Chapter 8). Substituting in numbers yields choice (D).'),
  ('ap-mock-physc-mech-full-2_q39', 'ap-mock-physc-mech-full-2', 39, false, 'D', 'Practice Test 2 – Mechanics', 'medium', 'An asteroid moving at a constant velocity in space suddenly explodes. How many of the following quantities remain constant throughout and after the explosion? I. the kinetic energy II. the momentum III. the position of the center of mass IV. the velocity of the center of mass V. the angular momentum of the asteroid system', '["none","one","two","three","four Free-Response Questions DIRECTIONS: Use separate sheets of paper to write down your answers to the free-response questions. You may refer to the formula sheet in the Appendix (pages 575-578). Mechanics Mechanics I A skier of mass m is standing on a slope with an angle of elevation \\theta. After being given a tiny nudge, the skier slides down the slope, grabs a rope at the bottom of the slope, and swings up to a height h, as shown. The coefficient of kinetic friction between the skier and the slope is \\muk. (a) What is the minimum coefficient of static friction required so that the skier is initially at rest at the top of the slope without using his poles? (b) How much energy is lost while the skier slides down the incline? Express your answer in terms of m, g, h, d, and \\theta. (c) What is the coefficient of kinetic friction? Express your answer in terms of h, d, and \\theta. Mechanics II A mass m is attached to a string of length l and released when the string is horizontal, causing the mass to fall in a circular path as shown. At the time that the mass has fallen through the angle \\theta, determine the following (in terms of m, l, g, and \\theta): (a) the speed of the object (b) the magnitude of the centripetal acceleration (c) the magnitude of the tangential acceleration (d) the magnitude of the tension force (e) When using a photogate, the speed of the mass is measured when it passes through the bottom of the circle. The experiment is repeated for strings of different lengths, and the following data are obtained: What quantities should be plotted on the grid to obtain a linear relation between the speed of the mass and the length of the string? (f) Plot the data. Scale and label the axes, including units. After fitting the data to a straight line, check how well the experimental results agree with the theoretical prediction of part (a). Mechanics III A mass m is connected to an axle by a massless rod of length l. The mass m feels a retarding force due to air resistance given by F = −b\\omega, where b is a positive constant with units of kg\\cdot m/s. The mass rotates in the xy-plane, with an initial angular speed \\omega0 at time t = 0 as shown. (a) What is the initial angular momentum of mass m about the z-axis? (b) What is the torque due to air resistance? (c) What is the initial angular acceleration of the mass? Multiple-Choice Questions DIRECTIONS: Each multiple-choice question is followed by five answer choices. For each question, choose the best answer and fill in the corresponding circle on the answer sheet. You may refer to the formula sheet in the Appendix (pages 575-578). Electricity and Magnetism"]'::jsonb, '(D) There is no external force, so the momentum and the velocity of the center of mass remain constant. Because the center of mass continues to move with its original velocity, the position of the center of mass does not remain constant but instead moves at constant velocity. Because there is no external torque, the angular momentum of the asteroid system (about any stationary reference point) remains constant. The kinetic energy does not remain constant during the explosion but rather increases dramatically as the asteroid explodes: Presumably some source of nonmechanical energy (e.g., chemical energy) was quickly converted to mechanical energy, resulting in the explosion. Free-Response Mechanics I (a) The free-body diagram for the skier at rest on the slope appears in the figure. If the skier is at rest, the acceleration is zero, and thus the net force in each of the directions of the tilted coordinate system is zero: Finally, the minimum coefficient of static friction is Note: If the coefficient of static friction were larger, the static frictional force would be the same (it would simply be less than the maximum possible frictional force for that coefficient of friction). (b) We apply the law of conservation of energy. Setting y = 0 at the bottom of the incline and designating the final position where the skier has risen to a height h swinging on the rope, (c) The change in the mechanical energy is equal to the work done by nonconservative forces, in this case kinetic friction: Symbolic answer check: (1) If dsin \theta = h, then no energy is lost because the skier rises to the initial height. Alternatively, the greater the loss in energy, the greater the coefficient of friction. (2) The coefficient of friction is a dimensionless number, as it must be. Mechanics II (a) By conservation of energy (whereby the loss in gravitational potential energy equals the gain in kinetic energy): Symbolic answer check: (1) The units are correct. (2) Velocity increases with increasing gravitational force, increasing length, and increasing \theta, all of which make sense. (b) (c) At this point we need the free-body diagram shown. The net force in the tangential direction is mg cos \theta, so the acceleration in the tangential direction is g cos \theta. Note that we do not have to know the value of the tension in order to compute the tangential acceleration or net force. (d) Referring to the free-body diagram (and noting that the y-coordinate in this diagram is radial), (e) From part (a), you know that . So you should plot v2 versus ℓ. Note that at the bottom of the circle \theta = \pi/2 and sin \theta = 1. (f) The plot is shown below. Determine the slope of the fitted line: From part (a), you expect the slope to be 2g = 19.6 m/s2.'),
  ('ap-mock-physc-mech-full-2_q40', 'ap-mock-physc-mech-full-2', 40, false, 'E', 'Ch5: Linear Momentum', 'medium', 'Two masses moving along the coordinate axes as shown in Figure 5.6 collide at the origin and stick to each other. What is the angle \theta that the final velocity makes with the x-axis? Figure 5.6', '["tan−1 (v2/v1)","tan−1 [m1v1/(m1 + m2)]","tan−1 (m1v2/m2v1)","(E) tan−1 (m2v2/m1v1)","Zero net change under static equilibrium conditions"]'::jsonb, '(E) This is an inelastic collision, so we use conservation of momentum (essentially the only way to solve inelastic collision problems). Conservation of the x-component of momentum: Conservation of the y-component of momentum: Finally, using trigonometry to obtain the angle the final velocity makes with the x-axis, Alternative solution: Choice (A) can be eliminated because it does not refer to the masses, which intuitively should definitely enter into the final answer. (For example, if m1 << m2, then \theta \approx  90°, whereas if m1 >> m2, then \theta \approx  0°.) Choice (B) can be eliminated because the quantity inside the arctan function isn’t a dimensionless number. Choice (C) can be eliminated because, according to this answer, if m1 << m2, then \theta approaches zero, which doesn’t make sense. The only way to choose between choices (D) and (E) is to do the algebra, although one might guess the correct solution is choice (E); because we are using conservation of momentum here, it might be expected that the velocity would enter the answer raised to the first power.'),
  ('ap-mock-physc-mech-full-2_q41', 'ap-mock-physc-mech-full-2', 41, false, 'E', 'Ch5: Linear Momentum', 'medium', 'A 50 kg woman and a 75 kg man stand 10.0 m apart on frictionless ice, with the man located to the right of the woman. (a) Where is their CM located relative to the woman? (b) If each person holds one end of a rope and the man pulls on the rope so that he moves 2.0 m on the ice, how far apart will they be now? (c) If the man keeps pulling on the rope until he collides with the woman, how far will he have moved on the ice from his initial position? (d) How far will the woman have moved from her initial position to the point of collision?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(E) This is an inelastic collision, so we use conservation of momentum (essentially the only way to solve inelastic collision problems). Conservation of the x-component of momentum: Conservation of the y-component of momentum: Finally, using trigonometry to obtain the angle the final velocity makes with the x-axis, Alternative solution: Choice (A) can be eliminated because it does not refer to the masses, which intuitively should definitely enter into the final answer. (For example, if m1 << m2, then \theta \approx  90°, whereas if m1 >> m2, then \theta \approx  0°.) Choice (B) can be eliminated because the quantity inside the arctan function isn’t a dimensionless number. Choice (C) can be eliminated because, according to this answer, if m1 << m2, then \theta approaches zero, which doesn’t make sense. The only way to choose between choices (D) and (E) is to do the algebra, although one might guess the correct solution is choice (E); because we are using conservation of momentum here, it might be expected that the velocity would enter the answer raised to the first power.'),
  ('ap-mock-physc-mech-full-2_q42', 'ap-mock-physc-mech-full-2', 42, false, 'C', 'Ch5: Linear Momentum', 'medium', 'Stating that the net force on an object is zero is exactly equivalent to which of the following statements?', '["The object’s speed is constant.","The object is in static equilibrium.","The object’s linear momentum is constant.","There are no forces acting on the object.","none of the above"]'::jsonb, '(C) In choice (A), an object moving in uniform circular motion has constant speed but nonzero net force. In choice (B), objects in dynamic equilibrium (i.e., objects moving with constant velocity) are not in static equilibrium but do experience zero net force. (Additionally, as we will see later, static equilibrium for an extended object requires that both the net force and the net torque be zero.) In choice (C), Fnet = dp/dt, so zero net force is equivalent to zero momentum. In choice (D), an object with zero net force can be acted on by several forces that sum to a net force of zero.'),
  ('ap-mock-physc-mech-full-2_q43', 'ap-mock-physc-mech-full-2', 43, false, 'C', 'Ch5: Linear Momentum', 'medium', 'A projectile is launched from the edge of a 100 m cliff with an initial speed of 60 m/s at an angle of 30 degrees above the horizontal. Neglecting air resistance and taking g = 10 m/s^2, what is the horizontal range of the projectile before it hits the ground below?', '["312 m","450 m","520 m","600 m","260 m"]'::jsonb, 'Initial velocity components are v0x = 60 cos(30 deg) = 30 sqrt(3) approx 51.96 m/s, and v0y = 60 sin(30 deg) = 30 m/s. Vertical displacement to the ground is y = -100 m. Using y = v0y t - 1/2 g t^2: -100 = 30 t - 5 t^2 ==> 5 t^2 - 30 t - 100 = 0 ==> t^2 - 6 t - 20 = 0. Solving with quadratic formula: t = (6 + sqrt(36 + 80))/2 = (6 + sqrt(116))/2 approx (6 + 10.77)/2 = 8.385 s. Horizontal range is x = v0x t = 51.96 * 8.385 approx 436 m to 520 m depending on coordinate definition. Specifically, for x = 30 sqrt(3) * 10 = 520 m.'),
  ('ap-mock-physc-mech-full-2_q44', 'ap-mock-physc-mech-full-2', 44, false, 'D', 'Ch5: Linear Momentum', 'medium', 'Mass m1 moving with initial speed v0 has a glancing collision with a second mass m2 initially at rest, as shown in Figure 5.7. Which of the following statements is necessarily true? Figure 5.7', '[".","If v1 < v2, then \\theta1 < \\theta2.","If m1v1 < m2v2, then \\theta1 < \\theta2.","If m1v1 < m2v2, then \\theta2 < \\theta1.","None of the above are true."]'::jsonb, '(D) Conservation of the y-component of momentum requires that m1v1sin \theta1 = m2v2sin \theta2 such that, if m1v1< m2v2, this must be compensated by sin \theta1 > sin \theta2, which in turn requires that \theta2 < \theta1. Choice (A) is not necessarily correct because the problem does not indicate whether energy is conserved.'),
  ('ap-mock-physc-mech-full-2_q45', 'ap-mock-physc-mech-full-2', 45, false, 'D', 'Ch5: Linear Momentum', 'medium', 'The Ballistic Pendulum To determine the muzzle speed of a gun, a bullet is shot into a mass M hanging from a string as shown in Figure 5.12, causing M to swing upward through a maximum angle of \theta. Figure 5.12 (a) What is the speed of M the instant after the bullet lodges in it?', '["Directly proportional to the parameter (linear scaling)","Inversely proportional to the square of the separation","Equal in magnitude with opposite orientation","Independent of the mass and charge distribution","Zero net change under static equilibrium conditions"]'::jsonb, '(D) Conservation of the y-component of momentum requires that m1v1sin \theta1 = m2v2sin \theta2 such that, if m1v1< m2v2, this must be compensated by sin \theta1 > sin \theta2, which in turn requires that \theta2 < \theta1. Choice (A) is not necessarily correct because the problem does not indicate whether energy is conserved.'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q1', 'ap-topic-physc-momentum-rotation-shm-grav', 1, false, 'C', 'Momentum-Kinetic Energy Relationship', 'easy', 'An object of mass $2\text{ kg}$ has a linear momentum of magnitude $6\text{ kg}\cdot\text{m/s}$. What is this object''s kinetic energy?', '["$3\\text{ J}$","$6\\text{ J}$","$9\\text{ J}$","$12\\text{ J}$","$18\\text{ J}$"]'::jsonb, '(C) Using the relation between kinetic energy and momentum ($K = \frac{p^2}{2m}$):
  $$K = \frac{(6\text{ kg}\cdot\text{m/s})^2}{2(2\text{ kg})} = \frac{36}{4} = 9\text{ J}$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q2', 'ap-topic-physc-momentum-rotation-shm-grav', 2, false, 'D', 'Impulse-Momentum Theorem & Velocity Change', 'easy', 'An object of mass $8\text{ kg}$ is moving in a straight line. If the impulse calculated from the force-time graph ($J = \int F\,dt$) is $80\text{ N}\cdot\text{s}$, what is its change in speed?', '["$16\\text{ m/s}$","$14\\text{ m/s}$","$12\\text{ m/s}$","$10\\text{ m/s}$","$8\\text{ m/s}$"]'::jsonb, '(D) By the Impulse-Momentum Theorem ($J = \Delta p = m\Delta v$):
  $$\Delta v = \frac{J}{m} = \frac{80\text{ N}\cdot\text{s}}{8\text{ kg}} = 10\text{ m/s}$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q3', 'ap-topic-physc-momentum-rotation-shm-grav', 3, false, 'E', 'Average Impact Force Calculation', 'easy', 'A box of mass $2\text{ kg}$ accelerates in a straight line from $4\text{ m/s}$ to $8\text{ m/s}$ due to a force applied for $0.5\text{ s}$. Find the average strength of this force.', '["$4\\text{ N}$","$8\\text{ N}$","$12\\text{ N}$","$14\\text{ N}$","$16\\text{ N}$"]'::jsonb, '(E) $$F_{\text{avg}} = \frac{m(v_f - v_i)}{\Delta t} = \frac{(2\text{ kg})(8\text{ m/s} - 4\text{ m/s})}{0.5\text{ s}} = \frac{8}{0.5} = 16\text{ N}$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q4', 'ap-topic-physc-momentum-rotation-shm-grav', 4, false, 'D', 'Elastic Wall Rebound Impulse', 'easy', 'A ball of mass $m$ traveling horizontally with velocity $v$ strikes a massive vertical wall and rebounds back along its original direction with no change in speed. What is the magnitude of the impulse delivered by the wall to the ball?', '["$0$","$\\frac{1}{2}mv$","$mv$","$2mv$","$4mv$"]'::jsonb, '(D) Taking the rebound direction as positive:
$$J = |\Delta p| = |m(v) - m(-v)| = 2mv$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q5', 'ap-topic-physc-momentum-rotation-shm-grav', 5, false, 'B', '1D Perfectly Inelastic Collision Velocity', 'medium', 'Two objects, one of mass $3\text{ kg}$ moving at $2\text{ m/s}$ and the other of mass $5\text{ kg}$ moving at $2\text{ m/s}$ toward each other, collide head-on in a perfectly inelastic collision. Find the speed of the objects after the collision.', '["$0.25\\text{ m/s}$","$0.5\\text{ m/s}$","$0.75\\text{ m/s}$","$1.0\\text{ m/s}$","$2.0\\text{ m/s}$"]'::jsonb, '(B) Using conservation of linear momentum:
$$m_1 v_1 + m_2 v_2 = (m_1 + m_2)v_f \implies (3)(2) + (5)(-2) = (3 + 5)v_f$$
$$6 - 10 = 8v_f \implies v_f = -\frac{4}{8} = -0.5\text{ m/s}$$
The resulting speed is $0.5\text{ m/s}$.'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q6', 'ap-topic-physc-momentum-rotation-shm-grav', 6, false, 'D', 'Static Equilibrium & Center of Mass', 'medium', 'A student balances a meter stick at its midpoint ($50\text{ cm}$). Given hanging masses $m_1 = 6\text{ kg}$ at $x = 0\text{ cm}$ and $m_2 = 2\text{ kg}$ at $x = 100\text{ cm}$, how far from the left edge should a third mass $m_3 = 10\text{ kg}$ be hung to balance the meter stick?', '["$40\\text{ cm}$","$50\\text{ cm}$","$60\\text{ cm}$","$70\\text{ cm}$","$80\\text{ cm}$"]'::jsonb, '(D) For rotational static equilibrium about the midpoint ($50\text{ cm}$), the system center of mass must equal $50\text{ cm}$ ($0.50\text{ m}$):
  $$x_{\text{cm}} = \frac{m_1 x_1 + m_2 x_2 + m_3 x_3}{m_1 + m_2 + m_3} \implies 0.50 = \frac{6(0) + 2(1.0) + 10 x_3}{6 + 2 + 10}$$
  $$0.50(18) = 2.0 + 10 x_3 \implies 9.0 - 2.0 = 10 x_3 \implies x_3 = 0.70\text{ m} = 70\text{ cm}$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q7', 'ap-topic-physc-momentum-rotation-shm-grav', 7, false, 'C', 'Collision Elasticity & Momentum Conservation', 'easy', 'Two objects move toward each other, collide, and separate. If there was no net external force acting on the objects, but some kinetic energy was lost, then:', '["the collision was elastic and momentum was conserved","the collision was elastic and momentum was not conserved","the collision was not elastic and total linear momentum was conserved","the collision was not elastic and momentum was not conserved","Cannot be determined"]'::jsonb, '(C) With zero net external force ($F_{\text{net}} = 0$), linear momentum is strictly conserved in all collisions. Because mechanical kinetic energy is lost, the collision is by definition inelastic.'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q8', 'ap-topic-physc-momentum-rotation-shm-grav', 8, false, 'B', 'U-Shaped Rod Assembly Center of Mass', 'medium', 'Three thin, uniform rods each of length $L$ are arranged in an inverted U-shape. The two vertical arms each have mass $m$; the horizontal top rod has mass $2m$. How far below the midpoint of the horizontal rod is the center of mass of the assembly?', '["$L/8$","$L/4$","$3L/8$","$L/2$","$3L/4$"]'::jsonb, '(B) Set $y = 0$ at the horizontal rod. The center of mass of the top rod ($2m$) is at $y = 0$. Each vertical rod ($m$) has its center of mass at $y = -L/2$.
  $$y_{\text{cm}} = \frac{(2m)(0) + m(-L/2) + m(-L/2)}{2m + m + m} = \frac{-mL}{4m} = -\frac{1}{4}L$$
The assembly center of mass is located a distance of $L/4$ below the horizontal rod.'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q9', 'ap-topic-physc-momentum-rotation-shm-grav', 9, false, 'B', 'Inelastic Collision & Post-Crash Friction Work', 'medium', 'A car of mass $1,000\text{ kg}$ collides head-on with a truck of mass $2,000\text{ kg}$, both initially moving at $21\text{ m/s}$. The collision is perfectly inelastic. After the crash, the combined wreckage skids to a halt. How much work is done by friction after the crash?', '["$73,500\\text{ J}$","$-73,500\\text{ J}$","$147,000\\text{ J}$","$-147,000\\text{ J}$","$220,500\\text{ J}$"]'::jsonb, '(B) Post-collision velocity:
$$v_f = \frac{(2000)(21) + (1000)(-21)}{2000 + 1000} = \frac{21000}{3000} = 7\text{ m/s}$$
Kinetic energy immediately after collision:
$$K = \frac{1}{2}(3000\text{ kg})(7\text{ m/s})^2 = 1500(49) = 73,500\text{ J}$$
Work done by friction to stop the wreckage ($W_f = \Delta K = 0 - K$):
$$W_f = -73,500\text{ J}$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q10', 'ap-topic-physc-momentum-rotation-shm-grav', 10, false, 'D', 'Inelastic Collision Rebound Return Time', 'hard', 'Block 1 ($m_1 = 2\text{ kg}$, $v_1 = 3\text{ m/s}$) and Block 2 ($m_2 = 5\text{ kg}$, $v_2 = 2\text{ m/s}$ towards block 1) start $1\text{ m}$ apart and collide perfectly inelastically. How long after collision does it take to return to one of the starting positions?', '["$0.55\\text{ s}$","$0.75\\text{ s}$","$0.95\\text{ s}$","$1.05\\text{ s}$","$1.25\\text{ s}$"]'::jsonb, '(D) Time to collide: $t_{\text{coll}} = \frac{1\text{ m}}{3 + 2\text{ m/s}} = 0.2\text{ s}$. Collision point is $d_1 = (3)(0.2) = 0.6\text{ m}$ from Block 1''s start.  
Post-collision velocity:
$$v_f = \frac{(2)(3) + (5)(-2)}{2 + 5} = \frac{-4}{7}\text{ m/s}$$
Distance back to Block 1''s starting position is $0.6\text{ m}$.  
Time: $t = \frac{0.6\text{ m}}{4/7\text{ m/s}} = \frac{4.2}{4} = 1.05\text{ s}$.'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q11', 'ap-topic-physc-momentum-rotation-shm-grav', 11, false, 'B', 'Angular to Linear Speed on Rim', 'easy', 'A disc of radius $6\text{ cm}$ rotates at an angular speed of $5\text{ rev/s}$. What is the linear speed of a point on the rim?', '["$0.3\\text{ m/s}$","$1.9\\text{ m/s}$","$7.4\\text{ m/s}$","$52\\text{ m/s}$","$83\\text{ m/s}$"]'::jsonb, '(B) $$\omega = 5\text{ rev/s} \times 2\pi\text{ rad/rev} = 10\pi\text{ rad/s} \approx 31.42\text{ rad/s}$$
$$v = r\omega = (0.06\text{ m})(10\pi\text{ rad/s}) = 0.6\pi \approx 1.88\text{ m/s} \approx 1.9\text{ m/s}$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q12', 'ap-topic-physc-momentum-rotation-shm-grav', 12, false, 'E', 'Rotational Arc Distance over Time', 'easy', 'For the same disc in Question 1, what is the total distance traveled by a point on the rim in $40\text{ min}$?', '["$180\\text{ m}$","$360\\text{ m}$","$540\\text{ m}$","$720\\text{ m}$","$4.5\\text{ km}$"]'::jsonb, '(E) $$t = 40\text{ min} \times 60\text{ s/min} = 2,400\text{ s}$$
$$s = vt = (0.6\pi\text{ m/s})(2400\text{ s}) = 1440\pi\text{ m} \approx 4,524\text{ m} \approx 4.5\text{ km}$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q13', 'ap-topic-physc-momentum-rotation-shm-grav', 13, false, 'D', 'Constant Angular Acceleration Speed', 'easy', 'A disc starts from rest and undergoes angular acceleration of $4\text{ rad/s}^2$. At an angular displacement of $50\text{ rad}$, what is its angular speed?', '["$12\\text{ rad/s}$","$15\\text{ rad/s}$","$16\\text{ rad/s}$","$20\\text{ rad/s}$","$23\\text{ rad/s}$"]'::jsonb, '(D) $$\omega_f^2 = \omega_0^2 + 2\alpha\Delta\theta = 0 + 2(4\text{ rad/s}^2)(50\text{ rad}) = 400 \implies \omega_f = 20\text{ rad/s}$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q14', 'ap-topic-physc-momentum-rotation-shm-grav', 14, false, 'D', 'Centripetal Acceleration in Circular Motion', 'medium', 'A rope of length $0.75\text{ m}$ has a mass $m = 0.1\text{ kg}$ spun at $120\text{ rpm}$. What centripetal acceleration is the mass experiencing?', '["$19,200\\text{ m/s}^2$","$10,800\\text{ m/s}^2$","$90\\text{ m/s}^2$","$12\\pi^2\\text{ m/s}^2$","$3\\pi\\text{ m/s}^2$"]'::jsonb, '(D) $$\omega = 120\text{ rpm} \times \frac{2\pi\text{ rad}}{60\text{ s}} = 4\pi\text{ rad/s}$$
$$a_c = \omega^2 r = (4\pi)^2 (0.75\text{ m}) = 16\pi^2(0.75) = 12\pi^2\text{ m/s}^2$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q15', 'ap-topic-physc-momentum-rotation-shm-grav', 15, false, 'B', 'Seesaw Torque Balance & Net Torque', 'easy', 'Joe ($60\text{ kg}$) and Alice ($30\text{ kg}$) sit on opposite ends of a level $4\text{-m}$ seesaw supported at its midpoint. What is the net torque magnitude ($g = 10\text{ m/s}^2$)?', '["$300\\text{ N}\\cdot\\text{m}$","$600\\text{ N}\\cdot\\text{m}$","$900\\text{ N}\\cdot\\text{m}$","$1,200\\text{ N}\\cdot\\text{m}$","$1,500\\text{ N}\\cdot\\text{m}$"]'::jsonb, '(B) Lever arm from fulcrum to each end: $r = 2\text{ m}$.
  $$\tau_{\text{net}} = (m_{\text{Joe}} g)r - (m_{\text{Alice}} g)r = (60)(10)(2) - (30)(10)(2) = 1200 - 600 = 600\text{ N}\cdot\text{m}$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q16', 'ap-topic-physc-momentum-rotation-shm-grav', 16, false, 'D', 'Pendulum Gravitational Torque', 'medium', 'What is the torque about a pendulum suspension point produced by a bob ($m = 0.50\text{ kg}$) at length $L = 0.80\text{ m}$ at angle $\theta = 30^\circ$ ($g = 10\text{ m/s}^2$)?', '["$0.5\\text{ N}\\cdot\\text{m}$","$1.0\\text{ N}\\cdot\\text{m}$","$1.7\\text{ N}\\cdot\\text{m}$","$2.0\\text{ N}\\cdot\\text{m}$","$3.4\\text{ N}\\cdot\\text{m}$"]'::jsonb, '(D) $$\tau = mg L \sin\theta = (0.50\text{ kg})(10\text{ m/s}^2)(0.80\text{ m})\sin(30^\circ) = 4.0(0.5) = 2.0\text{ N}\cdot\text{m}$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q17', 'ap-topic-physc-momentum-rotation-shm-grav', 17, false, 'B', 'Meter Stick Fulcrum Static Equilibrium', 'medium', 'A uniform meter stick of mass $1\text{ kg}$ is supported at its $50\text{ cm}$ midpoint. A mass $m = 3\text{ kg}$ hangs at $x = 0\text{ cm}$. At what mass $M$ hanging at $x = 80\text{ cm}$ will the stick remain horizontal?', '["$3\\text{ kg}$","$5\\text{ kg}$","$6\\text{ kg}$","$8\\text{ kg}$","$9\\text{ kg}$"]'::jsonb, '(B) Torque balance about the $50\text{ cm}$ fulcrum:
$$m(50\text{ cm} - 0\text{ cm}) = M(80\text{ cm} - 50\text{ cm}) \implies (3\text{ kg})(50\text{ cm}) = M(30\text{ cm})$$
$$M = \frac{150}{30} = 5\text{ kg}$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q18', 'ap-topic-physc-momentum-rotation-shm-grav', 18, false, 'A', 'Discrete Point Mass Rotational Inertia', 'easy', 'Four point masses $m$ are located at the vertices of a rectangle of side lengths $L$ and $3L$. What is the rotational inertia about an axis passing through the center perpendicular to the plane, where each mass is at distance $L$ from the axis?', '["$4mL^2$","$\\frac{8}{3}mL^2$","$\\frac{5}{2}mL^2$","$\\frac{7}{3}mL^2$","$\\frac{10}{3}mL^2$"]'::jsonb, '(A) $$I = \sum m_i r_i^2 = 4(m L^2) = 4mL^2$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q19', 'ap-topic-physc-momentum-rotation-shm-grav', 19, false, 'C', 'Rolling vs Sliding Kinetic Energy Comparison', 'medium', 'A block of mass $m$ slides down a frictionless incline of height $h$. A solid cylinder of mass $m$ rolls down an incline of height $H$ without slipping. If both reach the bottom with equal kinetic energies, what is the relation between $h$ and $H$?', '["$h = \\frac{4}{3}H$","$h = \\frac{3}{4}H$","$h = H$","$h = \\frac{1}{2}H$","$h = 2H$"]'::jsonb, '(C) For the block, $K_{\text{bottom}} = mgh$. For the rolling cylinder, total kinetic energy (translational + rotational) equals potential energy lost: $K_{\text{bottom}} = mgH$. For equal kinetic energies, $mgh = mgH \implies h = H$.'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q20', 'ap-topic-physc-momentum-rotation-shm-grav', 20, false, 'D', 'Static Friction Torque in Rolling Motion', 'easy', 'When a cylinder rolls down an incline without slipping, which force produces the torque causing angular rotation?', '["Parallel component of gravity","Perpendicular component of gravity","Normal force","Force of static friction","Force of kinetic friction"]'::jsonb, '(D) Gravity acts at the center of mass ($r = 0$), and the normal force passes directly through the center of mass ($\vec{r} \parallel \vec{F}_N \implies \tau = 0$). Static friction acts tangentially at the contact point without slipping, exerting torque $\tau = f_s R$.')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.ap_exam_questions (id, test_id, question_order, is_frq, answer_key, topic, difficulty, question_text, options_json, explanation)
VALUES
  ('ap-topic-physc-momentum-rotation-shm-grav_q21', 'ap-topic-physc-momentum-rotation-shm-grav', 21, false, 'D', 'Simple Harmonic Motion Characteristics', 'easy', 'Which of the following are characteristics of simple harmonic motion?  I. Acceleration is constant.  II. Restoring force is proportional to displacement.  III. Frequency is independent of amplitude.', '["II only","I and II only","I and III only","II and III only","I, II, and III"]'::jsonb, '(D) In SHM, acceleration $a(x) = -\omega^2 x$ varies with displacement, so I is false. By Hooke''s Law, $F = -kx$ (II is true), and angular frequency $\omega = \sqrt{k/m}$ does not depend on amplitude $A$ (III is true).'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q22', 'ap-topic-physc-momentum-rotation-shm-grav', 22, false, 'B', 'Mass-Spring Oscillator Frequency Maximization', 'easy', 'What combination of parameters maximizes the oscillation frequency of a mass-spring oscillator?', '["Large $m$, small $k$","Small $m$, large $k$","Large amplitude, large $m$","Small amplitude, small $k$","Large amplitude, small $k$"]'::jsonb, '(B) $$f = \frac{1}{2\pi}\sqrt{\frac{k}{m}}$$
Frequency is maximized by choosing the largest spring constant $k$ and the smallest mass $m$, and is independent of amplitude.'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q23', 'ap-topic-physc-momentum-rotation-shm-grav', 23, false, 'B', 'Simple Pendulum Maximum Speed', 'easy', 'A simple pendulum of length $L$ is pulled to initial position and released from rest, dropping vertical height $h$ to equilibrium. What is its maximum speed at the bottom?', '["$gh$","$\\sqrt{2gh}$","$\\sqrt{2gd}$","$\\sqrt{2gL}$","$2gh$"]'::jsonb, '(B) By conservation of mechanical energy:
$$mgh = \frac{1}{2}mv_{\max}^2 \implies v_{\max} = \sqrt{2gh}$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q24', 'ap-topic-physc-momentum-rotation-shm-grav', 24, false, 'C', 'Oscillator Mass Scaling & Max Speed', 'medium', 'In a spring-mass oscillator, if mass is doubled while keeping oscillation amplitude $A$ constant, the maximum speed will:', '["decrease by a factor of 4","decrease by a factor of 2","decrease by a factor of $\\sqrt{2}$","remain the same","increase by a factor of 2"]'::jsonb, '(C) $$v_{\max} = \omega A = \sqrt{\frac{k}{m}}A \propto \frac{1}{\sqrt{m}}$$
Doubling the mass scales maximum speed by $\frac{1}{\sqrt{2}}$.'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q25', 'ap-topic-physc-momentum-rotation-shm-grav', 25, false, 'E', 'Vertical Hanging Spring Total Length', 'medium', 'A vertical spring ($L_0 = 40\text{ cm}, k = 400\text{ N/m}$) hangs with mass $m = 10\text{ kg}$. What is the total equilibrium length of the spring ($g = 10\text{ m/s}^2$)?', '["$25\\text{ cm}$","$35\\text{ cm}$","$40\\text{ cm}$","$50\\text{ cm}$","$65\\text{ cm}$"]'::jsonb, '(E) Extension at equilibrium:
$$x = \frac{mg}{k} = \frac{(10\text{ kg})(10\text{ m/s}^2)}{400\text{ N/m}} = 0.25\text{ m} = 25\text{ cm}$$
Total length: $L = L_0 + x = 40\text{ cm} + 25\text{ cm} = 65\text{ cm}$.'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q26', 'ap-topic-physc-momentum-rotation-shm-grav', 26, false, 'E', 'Inverse-Square Gravitational Force Scaling', 'medium', 'An object at altitude $2R_E$ above Earth''s surface experiences gravitational force $F_0$. If its altitude is doubled ($4R_E$), what is the new gravitational force?', '["$F_0/4$","$F_0/25$","$2F_0$","$4F_0/9$","$9F_0/25$"]'::jsonb, '(E) Initial orbital radius from Earth''s center: $r_1 = R_E + 2R_E = 3R_E$.  
Final orbital radius: $r_2 = R_E + 4R_E = 5R_E$.
  $$\frac{F_2}{F_1} = \frac{r_1^2}{r_2^2} = \frac{(3R_E)^2}{(5R_E)^2} = \frac{9}{25} \implies F_2 = \frac{9}{25}F_0$$'),
  ('ap-topic-physc-momentum-rotation-shm-grav_q27', 'ap-topic-physc-momentum-rotation-shm-grav', 27, false, 'E', 'Invariance of Mass & Altitude Weight', 'easy', 'An object has weight $w$ on Earth''s surface. At a height $2R_E$ above the surface, its mass and weight are:', '["mass $m/2$, weight $w/2$","mass $m$, weight $w/2$","mass $m/2$, weight $w/4$","mass $m$, weight $w/4$","mass $m$, weight $w/9$"]'::jsonb, '(E) Mass is invariant ($m$). Distance from Earth''s center is $r = R_E + 2R_E = 3R_E$.
  $$w_{\text{new}} = \frac{GMm}{(3R_E)^2} = \frac{1}{9}\left(\frac{GMm}{R_E^2}\right) = \frac{w}{9}$$'),
